fn cloneRebasedGeneratedJoinSliceAlloc(
    alloc: std.mem.Allocator,
    joins: []const GeneratedSqlJoinAst,
    base: usize,
    end: usize,
) anyerror![]GeneratedSqlJoinAst {
    if (joins.len == 0) return &.{};
    const cloned = try alloc.alloc(GeneratedSqlJoinAst, joins.len);
    var initialized: usize = 0;
    errdefer {
        for (cloned[0..initialized]) |*join| join.deinit(alloc);
        alloc.free(cloned);
    }
    for (joins, cloned) |join, *out| {
        var temp = GeneratedSqlJoinAst{
            .tokens = try rebaseGeneratedSqlTokenRange(join.tokens, base, end),
            .operator_tokens = try rebaseGeneratedSqlTokenRange(join.operator_tokens, base, end),
            .kind = join.kind,
            .tree_index = join.tree_index,
            .tree_depth = join.tree_depth,
            .left_child_index = join.left_child_index,
            .left_tokens = try rebaseGeneratedSqlTokenRange(join.left_tokens, base, end),
            .left_table_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.left_table_tokens, base, end),
            .left_alias_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.left_alias_tokens, base, end),
            .left_alias_name_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.left_alias_name_tokens, base, end),
            .right_tokens = try rebaseGeneratedSqlTokenRange(join.right_tokens, base, end),
            .right_table_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_table_tokens, base, end),
            .right_alias_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_alias_tokens, base, end),
            .right_alias_name_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_alias_name_tokens, base, end),
            .right_lateral_subquery_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_lateral_subquery_tokens, base, end),
            .right_lateral_alias_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_lateral_alias_tokens, base, end),
            .right_lateral_alias_name_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_lateral_alias_name_tokens, base, end),
            .right_lateral_unnest_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_lateral_unnest_tokens, base, end),
            .right_lateral_unnest_name_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_lateral_unnest_name_tokens, base, end),
            .right_lateral_unnest_argument_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_lateral_unnest_argument_tokens, base, end),
            .right_lateral_unnest_alias_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_lateral_unnest_alias_tokens, base, end),
            .right_lateral_unnest_alias_name_tokens = try rebaseGeneratedSqlTokenRangeOptional(join.right_lateral_unnest_alias_name_tokens, base, end),
            .condition_kind = join.condition_kind,
            .condition_tokens = try rebaseGeneratedSqlTokenRange(join.condition_tokens, base, end),
        };
        errdefer temp.deinit(alloc);
        if (join.right_lateral_subquery_read_ast) |read| {
            const subquery_tokens = join.right_lateral_subquery_tokens orelse return error.UnsupportedSqlShape;
            temp.right_lateral_subquery_read_ast = try cloneGeneratedReadAstPtrAlloc(alloc, read, subquery_tokens.end - subquery_tokens.start);
