    .{ .sql = "VACUUM (FULL, VERBOSE, ANALYZE) public.usage_records", .kind = .unsupported },
    .{ .sql = "REINDEX INDEX CONCURRENTLY public.usage_status_idx", .kind = .unsupported },
    .{ .sql = "REASSIGN OWNED BY old_role TO new_role", .kind = .unsupported },
    .{ .sql = "REVOKE GRANT OPTION FOR readonly FROM app_writer", .kind = .unsupported },
    .{ .sql = "REVOKE readonly FROM app_writer", .kind = .ddl },
    .{ .sql = "SET ROLE app_user", .kind = .unsupported },
    .{ .sql = "SET ROLE DEFAULT", .kind = .unsupported },
    .{ .sql = "SET SESSION AUTHORIZATION app_user", .kind = .unsupported },
    .{ .sql = "SET SESSION AUTHORIZATION DEFAULT", .kind = .unsupported },
    .{ .sql = "RESET ROLE", .kind = .unsupported },
    .{ .sql = "RESET SESSION AUTHORIZATION", .kind = .unsupported },
    .{ .sql = "SECURITY LABEL ON TABLE usage_records IS 'internal'", .kind = .ddl },
    .{ .sql = "DROP RULE IF EXISTS usage_insert ON usage_records", .kind = .unsupported },
    .{ .sql = "DROP SERVER IF EXISTS usage_server CASCADE", .kind = .unsupported },
    .{ .sql = "DROP TRIGGER IF EXISTS usage_audit ON usage_records", .kind = .unsupported },
    .{ .sql = "DROP USER MAPPING IF EXISTS FOR usage_user SERVER usage_server", .kind = .unsupported },
    .{ .sql = "UNLISTEN *", .kind = .unsupported },
};

pub fn parseSqlAlloc(alloc: std.mem.Allocator, sql: []const u8) anyerror!GeneratedSqlParseResult {
    var tokens = try lexer.tokenizeAlloc(alloc, sql);
    defer lexer.freeTokens(alloc, &tokens);
    return try parseTokensAlloc(alloc, tokens.items);
}

pub fn parseTokensAlloc(alloc: std.mem.Allocator, tokens: []const token_mod.Token) anyerror!GeneratedSqlParseResult {
    return parseTokensAllocWithAstMode(alloc, tokens, .full);
}

pub fn parseTokensAllocWithAstMode(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    ast_mode: GeneratedSqlAstMode,
) anyerror!GeneratedSqlParseResult {
    const statement = classifyStatement(tokens);

    const grammar_statement_kind = blk: {
        var token_id_buffer: [generated_token_id_stack_capacity]u16 = undefined;
        if (tokenIdsIntoBuffer(tokens, &token_id_buffer)) |token_ids| {
            break :blk parseGeneratedTokenIdStatementKind(alloc, token_ids) catch |err| switch (err) {
                error.UnexpectedToken => {
                    if (generatedStatementAllowsLexicalGrammarFallback(statement)) break :blk std.meta.activeTag(statement);
                    return err;
                },
                else => return err,
            };
        } else |err| {
            switch (err) {
                error.NoSpaceLeft => {
                    const token_ids = try tokenIdsAlloc(alloc, tokens);
                    defer alloc.free(token_ids);
                    break :blk parseGeneratedTokenIdStatementKind(alloc, token_ids) catch |parse_err| switch (parse_err) {
                        error.UnexpectedToken => {
                            if (generatedStatementAllowsLexicalGrammarFallback(statement)) break :blk std.meta.activeTag(statement);
                            return parse_err;
                        },
                        else => return parse_err,
                    };
                },
                else => return err,
            }
        }
    };

    if (!generatedGrammarKindMatchesStatement(grammar_statement_kind, statement, tokens)) return error.UnsupportedSqlShape;
    return try buildGeneratedParseResult(alloc, tokens, statement, ast_mode);
}

fn generatedStatementAllowsLexicalGrammarFallback(statement: GeneratedSqlStatement) bool {
    return switch (statement) {
        .ddl => |ddl| ddl == .create_policy,
        else => false,
    };
}

fn generatedGrammarKindMatchesStatement(
    grammar_statement_kind: GeneratedSqlStatementKind,
    statement: GeneratedSqlStatement,
    tokens: []const token_mod.Token,
) bool {
    const statement_kind = std.meta.activeTag(statement);
    if (grammar_statement_kind == statement_kind) return true;
    if (grammar_statement_kind == .ddl) {
        switch (statement) {
            .unsupported => |kind| switch (kind) {
                .comment => return !generatedCommentLooksSupported(tokens),
                .security_label => return !generatedSecurityLabelLooksSupported(tokens),
                .alter_table_access_method => return generatedAlterTableAccessMethodUnsupported(tokens),
                .alter_table_cluster => return generatedAlterTableClusterUnsupported(tokens),
                .alter_table_column_statistics => return generatedAlterTableColumnStatisticsUnsupported(tokens),
                .alter_table_column_storage => return generatedAlterTableColumnStorageUnsupported(tokens),
                .alter_table_inheritance => return generatedAlterTableInheritanceUnsupported(tokens),
                .alter_table_owner => return generatedAlterTableOwnerUnsupported(tokens),
                .alter_table_persistence => return generatedAlterTablePersistenceUnsupported(tokens),
                .alter_table_replica_identity => return generatedAlterTableReplicaIdentityUnsupported(tokens),
                .alter_table_set_schema => return generatedAlterTableSetSchemaUnsupported(tokens),
                .alter_table_storage_parameters => return generatedAlterTableStorageParametersUnsupported(tokens),
                .alter_table_tablespace => return generatedAlterTableTablespaceUnsupported(tokens),
                .alter_table_trigger_state => return generatedAlterTableTriggerStateUnsupported(tokens),
                .alter_table_exclusion_constraint => return generatedAlterTableExclusionConstraintUnsupported(tokens),
                .create_table_exclusion_constraint => return generatedCreateTableExclusionConstraintUnsupported(tokens),
                else => {},
            },
            else => {},
        }
    }
    if (grammar_statement_kind != .unsupported) return false;
    if (statement == .extension_index and statement.extension_index == .create_index and generatedLooksLikeAntflyCreateTextSearch(tokens)) return true;
    if (statement == .ddl and (statement.ddl == .comment or statement.ddl == .security_label or statement.ddl == .grant or statement.ddl == .revoke or statement.ddl == .alter_default_privileges)) return true;
    return generatedUnsupportedGrammarRoleAliasMatchesDdl(statement, tokens);
}

fn generatedUnsupportedGrammarRoleAliasMatchesDdl(statement: GeneratedSqlStatement, tokens: []const token_mod.Token) bool {
    if (tokens.len < 2 or !tokens[1].matchesKeywordTag(.user)) return false;
    return switch (statement) {
        .ddl => |ddl| switch (ddl) {
            .create_role => tokens[0].matchesKeywordTag(.create) and !(tokens.len > 2 and tokens[2].matchesKeyword("mapping")),
            .alter_role => tokens[0].matchesKeywordTag(.alter) and !(tokens.len > 2 and tokens[2].matchesKeyword("mapping")),
            .drop_role => tokens[0].matchesKeywordTag(.drop) and !(tokens.len > 2 and tokens[2].matchesKeyword("mapping")),
            else => false,
        },
        else => false,
    };
}

fn generatedLooksLikeAntflyCreateTextSearch(tokens: []const token_mod.Token) bool {
    if (tokens.len <= 3) return false;
    if (!tokens[0].matchesKeywordTag(.create) or !tokens[1].matchesKeyword("text") or !tokens[2].matchesKeyword("search")) return false;
    return !generatedTextSearchCatalogKind(tokens[3]);
}

fn generatedTextSearchCatalogKind(token: token_mod.Token) bool {
    return token.matchesKeyword("configuration") or
        token.matchesKeyword("dictionary") or
        token.matchesKeyword("parser") or
        token.matchesKeyword("template");
}

fn parseGeneratedTokenIds(alloc: std.mem.Allocator, token_ids: []const u16) !void {
    if (token_ids.len + 1 <= generated_parse_stack_capacity) {
        var stack_buffer: [generated_parse_stack_capacity]u16 = undefined;
        return try generated.parseWithStackBuffer(token_ids, &stack_buffer);
    }
    return try generated.parse(alloc, token_ids);
}

pub fn parseStatementKindFromGrammarAlloc(alloc: std.mem.Allocator, tokens: []const token_mod.Token) !GeneratedSqlStatementKind {
    var token_id_buffer: [generated_token_id_stack_capacity]u16 = undefined;
    if (tokenIdsIntoBuffer(tokens, &token_id_buffer)) |token_ids| {
        return try parseGeneratedTokenIdStatementKind(alloc, token_ids);
    } else |err| switch (err) {
        error.NoSpaceLeft => {
            const token_ids = try tokenIdsAlloc(alloc, tokens);
            defer alloc.free(token_ids);
            return try parseGeneratedTokenIdStatementKind(alloc, token_ids);
        },
        else => return err,
    }
}

pub fn parseReductionTraceAlloc(alloc: std.mem.Allocator, tokens: []const token_mod.Token) !GeneratedSqlReductionTrace {
    var token_id_buffer: [generated_token_id_stack_capacity]u16 = undefined;
    if (tokenIdsIntoBuffer(tokens, &token_id_buffer)) |token_ids| {
        return try parseGeneratedTokenIdReductionTraceAlloc(alloc, token_ids);
    } else |err| switch (err) {
        error.NoSpaceLeft => {
            const token_ids = try tokenIdsAlloc(alloc, tokens);
            defer alloc.free(token_ids);
            return try parseGeneratedTokenIdReductionTraceAlloc(alloc, token_ids);
        },
        else => return err,
    }
}

const ReductionTraceHandler = struct {
    reductions: *std.ArrayListUnmanaged(GeneratedSqlReductionEvent),
    alloc: std.mem.Allocator,
    accepted_token_count: ?usize = null,

    pub fn shift(_: *@This(), _: generated.Shift) !void {}

    pub fn reduce(self: *@This(), reduction: generated.Reduction) !void {
        const info = generated.productionInfo(reduction.production) orelse return error.UnsupportedSqlShape;
        try self.reductions.append(self.alloc, .{
            .production = reduction.production,
            .rule = info.rule,
            .lhs = reduction.lhs,
            .rhs_len = reduction.rhs_len,
            .rhs = generated.productionRhs(reduction.production) orelse return error.UnsupportedSqlShape,
        });
    }

    pub fn accept(self: *@This(), accepted: generated.Accept) !void {
        self.accepted_token_count = accepted.token_count;
    }
};

const StatementKindTraceHandler = struct {
    statement_kind: ?GeneratedSqlStatementKind = null,
    saw_extension_index_ddl: bool = false,

    pub fn shift(_: *@This(), _: generated.Shift) !void {}

    pub fn reduce(self: *@This(), reduction: generated.Reduction) !void {
        const info = generated.productionInfo(reduction.production) orelse return error.UnsupportedSqlShape;
        if (reductionIsExtensionIndexDdl(info.rule, reduction.production)) {
            self.saw_extension_index_ddl = true;
        }
        if (info.rule != .statement) return;
        const rhs = generated.productionRhs(reduction.production) orelse return error.UnsupportedSqlShape;
        if (rhs.len != 1) return error.UnsupportedSqlShape;
        const rule = generated.symbolRule(rhs[0]) orelse return error.UnsupportedSqlShape;
        const kind = statementKindFromGrammarRule(rule) orelse return error.UnsupportedSqlShape;
        self.statement_kind = if (kind == .ddl and self.saw_extension_index_ddl) .extension_index else kind;
    }

    pub fn accept(_: *@This(), _: generated.Accept) !void {}
};

fn reductionIsExtensionIndexDdl(rule: ?GeneratedSqlGrammarRule, production: u16) bool {
    return switch (rule orelse return false) {
        .create_index_statement, .create_extension_statement => true,
        .drop_statement => dropStatementProductionIsExtensionIndex(production),
        else => false,
    };
}

fn dropStatementProductionIsExtensionIndex(production: u16) bool {
    const rhs = generated.productionRhs(production) orelse return false;
    if (rhs.len < 2) return false;
    if (!grammarSymbolNameEquals(rhs[0], "DROP")) return false;
    return grammarSymbolNameEquals(rhs[1], "INDEX") or grammarSymbolNameEquals(rhs[1], "EXTENSION");
}

fn grammarSymbolNameEquals(symbol: u16, expected: []const u8) bool {
    const name = generated.terminalName(symbol) orelse return false;
    return std.mem.eql(u8, name, expected);
}

fn parseGeneratedTokenIdStatementKind(alloc: std.mem.Allocator, token_ids: []const u16) !GeneratedSqlStatementKind {
    var handler = StatementKindTraceHandler{};

    if (token_ids.len + 1 <= generated_parse_stack_capacity) {
        var stack_buffer: [generated_parse_stack_capacity]u16 = undefined;
        try generated.parseWithEvents(token_ids, &stack_buffer, &handler);
    } else {
        const stack_buffer = try alloc.alloc(u16, token_ids.len + 1);
        defer alloc.free(stack_buffer);
        try generated.parseWithEvents(token_ids, stack_buffer, &handler);
    }

    return handler.statement_kind orelse error.UnsupportedSqlShape;
}

fn parseGeneratedTokenIdReductionTraceAlloc(alloc: std.mem.Allocator, token_ids: []const u16) !GeneratedSqlReductionTrace {
    var reductions: std.ArrayListUnmanaged(GeneratedSqlReductionEvent) = .empty;
    errdefer reductions.deinit(alloc);
    var handler = ReductionTraceHandler{ .reductions = &reductions, .alloc = alloc };

    if (token_ids.len + 1 <= generated_parse_stack_capacity) {
        var stack_buffer: [generated_parse_stack_capacity]u16 = undefined;
        try generated.parseWithEvents(token_ids, &stack_buffer, &handler);
    } else {
        const stack_buffer = try alloc.alloc(u16, token_ids.len + 1);
        defer alloc.free(stack_buffer);
        try generated.parseWithEvents(token_ids, stack_buffer, &handler);
    }

    return .{
        .reductions = try reductions.toOwnedSlice(alloc),
        .accepted_token_count = handler.accepted_token_count orelse token_ids.len,
    };
}

fn buildGeneratedParseResult(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    statement: GeneratedSqlStatement,
    ast_mode: GeneratedSqlAstMode,
) anyerror!GeneratedSqlParseResult {
    return .{
        .kind = std.meta.activeTag(statement),
        .statement = statement,
        .ast = if (ast_mode == .skip_read and statement == .read) null else try buildGeneratedAst(alloc, tokens, statement),
    };
}

fn generatedTokenEnd(tokens: []const token_mod.Token) usize {
    var end = tokens.len;
    while (end > 0 and tokens[end - 1].kind == .semicolon) end -= 1;
    return end;
}

pub fn parseFirstFamilyTokensAlloc(alloc: std.mem.Allocator, tokens: []const token_mod.Token) !?GeneratedSqlParseResult {
    const kind = parseStatementKindFromGrammarAlloc(alloc, tokens) catch |err| switch (err) {
        error.UnsupportedSqlShape, error.UnexpectedToken => return null,
        else => return err,
    };
    if (!generatedStatementKindIsFirstFamily(kind)) return null;
    return try parseTokensAlloc(alloc, tokens);
}

pub fn parseGeneratedGateTokensStrictAlloc(alloc: std.mem.Allocator, tokens: []const token_mod.Token) !?GeneratedSqlParseResult {
    return try parseGeneratedGateTokensStrictAllocWithAstMode(alloc, tokens, .full);
}

pub fn parseGeneratedGateTokensStrictAllocWithAstMode(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    ast_mode: GeneratedSqlAstMode,
) !?GeneratedSqlParseResult {
    if (tokens.len == 0) return null;
    return try parseTokensAllocWithAstMode(alloc, tokens, ast_mode);
}

fn generatedStatementKindIsFirstFamily(kind: GeneratedSqlStatementKind) bool {
    return kind == .session or kind == .transaction or kind == .prepared or kind == .prepared_transaction;
}

pub fn isFirstFamilyTokens(tokens: []const token_mod.Token) bool {
    return generatedStatementKindIsFirstFamily(classifyTokens(tokens));
}

pub fn isGeneratedGateTokens(tokens: []const token_mod.Token) bool {
    return classifyTokens(tokens) != .other;
}

pub fn diagnosticAlloc(alloc: std.mem.Allocator, tokens: []const token_mod.Token) !?GeneratedSqlDiagnostic {
    var diagnostic_tokens = try diagnosticTokenIdsAlloc(alloc, tokens);
    defer diagnostic_tokens.deinit(alloc);

    const generated_diagnostic = try parseGeneratedTokenIdsDiagnostic(alloc, diagnostic_tokens.token_ids) orelse return null;
    const source_token_index = diagnostic_tokens.sourceTokenIndex(generated_diagnostic.token_index);
    const span: DiagnosticSpan = if (source_token_index < tokens.len)
        .{ .start = tokens[source_token_index].source_start, .end = tokens[source_token_index].source_end, .actual = tokens[source_token_index].text }
    else
        .{ .start = diagnostic_tokens.endSourceOffset(tokens), .end = diagnostic_tokens.endSourceOffset(tokens), .actual = "$end" };
    return .{
        .token_index = source_token_index,
        .source_start = span.start,
        .source_end = span.end,
        .expected = generated_diagnostic.expected,
        .actual = span.actual,
    };
}

const DiagnosticTokenIds = struct {
    token_ids: []u16,
    source_indexes: []usize,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.token_ids);
        alloc.free(self.source_indexes);
        self.* = .{ .token_ids = &.{}, .source_indexes = &.{} };
    }

    fn sourceTokenIndex(self: @This(), generated_token_index: usize) usize {
        if (generated_token_index < self.source_indexes.len) return self.source_indexes[generated_token_index];
        return if (self.source_indexes.len == 0) 0 else self.source_indexes[self.source_indexes.len - 1] + 1;
    }

    fn endSourceOffset(self: @This(), tokens: []const token_mod.Token) usize {
        const end_token = self.sourceTokenIndex(self.source_indexes.len);
        if (end_token == 0) return 0;
        if (tokens.len == 0) return 0;
        const previous = @min(end_token - 1, tokens.len - 1);
        return tokens[previous].source_end;
    }
};

fn diagnosticTokenIdsAlloc(alloc: std.mem.Allocator, tokens: []const token_mod.Token) !DiagnosticTokenIds {
    var ids: std.ArrayListUnmanaged(u16) = .empty;
    var source_indexes: std.ArrayListUnmanaged(usize) = .empty;
    errdefer ids.deinit(alloc);
    errdefer source_indexes.deinit(alloc);

    var sink = TokenIdSink{ .list = .{ .items = &ids, .alloc = alloc } };
    for (tokens, 0..) |tok, index| {
        if (tok.kind == .semicolon and trailingSemicolonOnly(tokens, index)) break;
        const prev = if (index > 0) tokens[index - 1] else null;
        const next = if (index + 1 < tokens.len) tokens[index + 1] else null;
        const before = ids.items.len;
        try appendTokenIds(&sink, tokens, index, tok, prev, next);
        const added = ids.items.len - before;
        try source_indexes.ensureUnusedCapacity(alloc, added);
        for (0..added) |_| source_indexes.appendAssumeCapacity(index);
    }

    const token_ids = try ids.toOwnedSlice(alloc);
    errdefer alloc.free(token_ids);
    return .{
        .token_ids = token_ids,
        .source_indexes = try source_indexes.toOwnedSlice(alloc),
    };
}

fn parseGeneratedTokenIdsDiagnostic(alloc: std.mem.Allocator, token_ids: []const u16) !?generated.ParseDiagnostic {
    if (token_ids.len + 1 <= generated_parse_stack_capacity) {
        var stack_buffer: [generated_parse_stack_capacity]u16 = undefined;
        return try generated.parseDiagnosticWithStackBuffer(alloc, token_ids, &stack_buffer);
    }
    return try generated.parseDiagnostic(alloc, token_ids);
}

pub fn tokenIdsAlloc(alloc: std.mem.Allocator, tokens: []const token_mod.Token) ![]u16 {
    var ids: std.ArrayListUnmanaged(u16) = .empty;
    errdefer ids.deinit(alloc);
    var sink = TokenIdSink{ .list = .{ .items = &ids, .alloc = alloc } };
    for (tokens, 0..) |tok, index| {
        if (tok.kind == .semicolon and trailingSemicolonOnly(tokens, index)) break;
        const prev = if (index > 0) tokens[index - 1] else null;
        const next = if (index + 1 < tokens.len) tokens[index + 1] else null;
        try appendTokenIds(&sink, tokens, index, tok, prev, next);
    }
    return try ids.toOwnedSlice(alloc);
}

fn tokenIdsIntoBuffer(tokens: []const token_mod.Token, buffer: []u16) ![]const u16 {
    var sink = TokenIdSink{ .buffer = .{ .items = buffer } };
    for (tokens, 0..) |tok, index| {
        if (tok.kind == .semicolon and trailingSemicolonOnly(tokens, index)) break;
        const prev = if (index > 0) tokens[index - 1] else null;
        const next = if (index + 1 < tokens.len) tokens[index + 1] else null;
        try appendTokenIds(&sink, tokens, index, tok, prev, next);
    }
    return sink.buffer.items[0..sink.buffer.len];
}

const TokenIdSink = union(enum) {
    list: struct {
        items: *std.ArrayListUnmanaged(u16),
        alloc: std.mem.Allocator,
    },
    buffer: struct {
        items: []u16,
        len: usize = 0,
    },

    fn append(self: *TokenIdSink, id: u16) !void {
        switch (self.*) {
            .list => |list| try list.items.append(list.alloc, id),
            .buffer => |*buffer| {
                if (buffer.len == buffer.items.len) return error.NoSpaceLeft;
                buffer.items[buffer.len] = id;
                buffer.len += 1;
            },
        }
    }

    fn appendToken(self: *TokenIdSink, token: generated.Token) !void {
        try self.append(generated.tokenId(token));
    }
};

fn appendTokenIds(
    ids: *TokenIdSink,
    tokens: []const token_mod.Token,
    index: usize,
    tok: token_mod.Token,
    prev: ?token_mod.Token,
    next: ?token_mod.Token,
) !void {
    switch (tok.kind) {
        .identifier => {
            if (try contextualKeywordSymbolId(tokens, index, tok, prev, next)) |id| {
                try ids.append(id);
                return;
            }
            if (generatedParserTreatsKeywordAsIdentifier(tokens, index, tok, prev, next)) {
                try appendIdentifierIds(ids, tok.text, false);
                return;
            }
            if (try keywordSymbolId(tok)) |id| {
                try ids.append(id);
                return;
            }
            try appendIdentifierIds(ids, tok.text, true);
        },
        .string => try ids.appendToken(.STRING),
        .number => try ids.appendToken(.NUMBER),
        .placeholder => try ids.appendToken(.PLACEHOLDER),
        .comma => try ids.appendToken(.COMMA),
        .star => try ids.appendToken(.STAR),
        .eq => try ids.appendToken(.EQ),
        .neq => try ids.appendToken(.NEQ),
        .gt => try ids.appendToken(.GT),
        .gte => try ids.appendToken(.GTE),
        .lt => try ids.appendToken(.LT),
        .lte => try ids.appendToken(.LTE),
        .plus => try ids.appendToken(.PLUS),
        .minus => try ids.appendToken(.MINUS),
        .slash => try ids.appendToken(.SLASH),
        .percent => try ids.appendToken(.PERCENT),
        .colon => try ids.appendToken(.COLON),
        .pipe_concat => try ids.appendToken(.PIPE_CONCAT),
        .at_contains => try ids.appendToken(.AT_CONTAINS),
        .range_overlap => try ids.appendToken(.RANGE_OVERLAP),
        .question => try ids.appendToken(.QUESTION),
        .question_any => try ids.appendToken(.QUESTION_ANY),
        .question_all => try ids.appendToken(.QUESTION_ALL),
        .regex_match => try ids.appendToken(.REGEX_MATCH),
        .regex_imatch => try ids.appendToken(.REGEX_IMATCH),
        .regex_not_match => try ids.appendToken(.REGEX_NOT_MATCH),
        .regex_not_imatch => try ids.appendToken(.REGEX_NOT_IMATCH),
        .lparen => try ids.appendToken(.LPAREN),
        .rparen => try ids.appendToken(.RPAREN),
        .lbracket => try ids.appendToken(.LBRACKET),
        .rbracket => try ids.appendToken(.RBRACKET),
        .arrow_json => try ids.appendToken(.ARROW_JSON),
        .arrow_text => try ids.appendToken(.ARROW_TEXT),
        .path_arrow_json => try ids.appendToken(.PATH_ARROW_JSON),
        .path_arrow_text => try ids.appendToken(.PATH_ARROW_TEXT),
        .semicolon => try ids.appendToken(.SEMICOLON),
    }
}

fn contextualKeywordSymbolId(tokens: []const token_mod.Token, index: usize, tok: token_mod.Token, prev: ?token_mod.Token, next: ?token_mod.Token) !?u16 {
    if (generatedSessionAuthorizationKeywordContext(tokens, index)) {
        if (tok.matchesKeyword("authorization")) return generated.tokenId(.AUTHORIZATION);
        if (tok.matchesKeyword("session")) return generated.tokenId(.SESSION);
    }
    if (generatedIndexConcurrentlyKeywordContext(tokens, index) and tok.matchesKeyword("concurrently")) return generated.tokenId(.CONCURRENTLY);
    if (generatedIndexElementCollateKeywordContext(tokens, index, tok, prev, next)) return generated.tokenId(.COLLATE);
    if (generatedRoutineKeywordContext(tokens, index) and tok.matchesKeyword("routine")) return generated.tokenId(.ROUTINE);
    if (generatedSessionKeywordContext(tokens, index)) {
        if (tok.matchesKeyword("local")) return generated.tokenId(.LOCAL);
        if (tok.matchesKeyword("session")) return generated.tokenId(.SESSION);
    }
    if (generatedCursorKeywordContext(tokens, index)) {
        if (tok.matchesKeyword("binary")) return generated.tokenId(.BINARY);
        if (tok.matchesKeyword("cursor")) return generated.tokenId(.CURSOR);
        if (tok.matchesKeyword("hold")) return generated.tokenId(.HOLD);
        if (tok.matchesKeyword("scroll")) return generated.tokenId(.SCROLL);
    }
    if (generatedCopyDiagnosticIdentifierContext(tokens, index) and
        (tok.matchesKeywordTag(.escape) or tok.matchesKeywordTag(.where)))
    {
        return generated.tokenId(.IDENT);
    }
    if (generatedAlterTableDiagnosticIdentifierContext(tokens, index) and
        tok.matchesKeywordTag(.match) and
        !generatedAlterTableForeignKeyMatchClauseContext(tokens, index))
    {
        return generated.tokenId(.IDENT);
    }
    if (generatedCreateRoutineDiagnosticIdentifierContext(tokens, index) and
        (tok.matchesKeywordTag(.current) or tok.matchesKeywordTag(.from) or tok.matchesKeywordTag(.rows) or tok.matchesKeywordTag(.window)))
    {
        return generated.tokenId(.IDENT);
    }
    if (generatedCreateTriggerDiagnosticIdentifierContext(tokens, index) and generatedCreateTriggerDiagnosticKeywordAsIdentifier(tok)) {
        return generated.tokenId(.IDENT);
    }
    if (generatedFunctionArgumentNameIdentifierContext(tokens, index, tok, next)) return generated.tokenId(.IDENT);
    if (generatedMatchKeywordAliasContext(tokens, index, tok, prev, next)) return generated.tokenId(.IDENT);
    if (generatedCreateTableMissingAsSelectContext(tokens, index) and tok.matchesKeywordTag(.table)) return generated.tokenId(.IDENT);
    if (generatedSystemTimeForKeywordContext(tokens, index) and tok.matchesKeywordTag(.@"for")) return generated.tokenId(.SYSTEM_TIME_FOR);
    if (generatedAnalyzeKeywordContext(tokens, index) and tok.matchesKeyword("verbose")) return generated.tokenId(.ANALYZE_VERBOSE);
    if (!generatedTransactionControlContext(tokens, index)) return null;
    if (tok.matchesKeyword("characteristics")) return generated.tokenId(.CHARACTERISTICS);
    if (tok.matchesKeyword("committed")) return generated.tokenId(.COMMITTED);
    if (tok.matchesKeyword("constraints")) return generated.tokenId(.CONSTRAINTS);
    if (tok.matchesKeyword("deferrable")) return generated.tokenId(.DEFERRABLE);
    if (tok.matchesKeyword("deferred")) return generated.tokenId(.DEFERRED);
    if (tok.matchesKeyword("immediate")) return generated.tokenId(.IMMEDIATE);
    if (tok.matchesKeyword("isolation")) return generated.tokenId(.ISOLATION);
    if (tok.matchesKeyword("level")) return generated.tokenId(.LEVEL);
    if (tok.matchesKeyword("read")) return generated.tokenId(.READ);
    if (tok.matchesKeywordTag(.release)) return generated.tokenId(.RELEASE);
    if (tok.matchesKeyword("repeatable")) return generated.tokenId(.REPEATABLE);
    if (tok.matchesKeywordTag(.as)) return generated.tokenId(.AS);
    if (tok.matchesKeywordTag(.savepoint)) return generated.tokenId(.SAVEPOINT);
    if (tok.matchesKeyword("serializable")) return generated.tokenId(.SERIALIZABLE);
    if (tok.matchesKeyword("session")) return generated.tokenId(.SESSION);
    if (tok.matchesKeyword("start")) return generated.tokenId(.START);
    if (tok.matchesKeywordTag(.to)) return generated.tokenId(.TO);
    if (tok.matchesKeyword("transaction")) return generated.tokenId(.TRANSACTION);
    if (tok.matchesKeyword("uncommitted")) return generated.tokenId(.UNCOMMITTED);
    if (tok.matchesKeyword("work")) return generated.tokenId(.WORK);
    if (tok.matchesKeyword("write")) return generated.tokenId(.WRITE);
    return null;
}

fn generatedFunctionArgumentNameIdentifierContext(tokens: []const token_mod.Token, index: usize, tok: token_mod.Token, next: ?token_mod.Token) bool {
    if (!tok.matchesKeywordTag(.@"return")) return false;
    const next_token = next orelse return false;
    if (next_token.kind != .eq) return false;
    if (index == 0) return false;
    var depth: usize = 0;
    var cursor = index;
    while (cursor > 0) {
        cursor -= 1;
        switch (tokens[cursor].kind) {
            .rparen, .rbracket => depth += 1,
            .lparen, .lbracket => {
                if (depth == 0) return cursor > 0 and tokens[cursor - 1].kind == .identifier;
                depth -= 1;
            },
            .comma => if (depth == 0) return true,
            else => {},
        }
    }
    return false;
}

fn generatedMatchKeywordAliasContext(tokens: []const token_mod.Token, index: usize, tok: token_mod.Token, prev: ?token_mod.Token, next: ?token_mod.Token) bool {
    if (!tok.matchesKeywordTag(.match) or prev == null) return false;
    if (prev.?.matchesKeywordTag(.as)) return true;
    if (!generatedTokenIsInSelectProjectionList(tokens, index)) return false;
    const next_token = next orelse return true;
    return next_token.matchesKeywordTag(.from) or
        next_token.matchesKeywordTag(.order) or
        next_token.matchesKeywordTag(.group) or
        next_token.matchesKeywordTag(.having) or
        next_token.matchesKeywordTag(.limit) or
        next_token.kind == .comma or
        next_token.kind == .semicolon;
}

fn generatedTokenIsInSelectProjectionList(tokens: []const token_mod.Token, index: usize) bool {
    var target_depth: usize = 0;
    for (tokens[0..index]) |token| {
        switch (token.kind) {
            .lparen => target_depth += 1,
            .rparen => {
                if (target_depth > 0) target_depth -= 1;
            },
            else => {},
        }
    }

    var depth: usize = 0;
    var saw_select = false;
    var saw_from = false;
    for (tokens[0..index]) |token| {
        if (depth == target_depth) {
            if (token.matchesKeywordTag(.select)) {
                saw_select = true;
                saw_from = false;
            } else if (saw_select and token.matchesKeywordTag(.from)) {
                saw_from = true;
            }
        }
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth > 0) depth -= 1;
            },
            else => {},
        }
    }
    return saw_select and !saw_from;
}

fn generatedSessionKeywordContext(tokens: []const token_mod.Token, index: usize) bool {
    if (index >= tokens.len or index != 1 or tokens.len == 0) return false;
    return tokens[0].matchesKeywordTag(.set);
}

fn generatedCursorKeywordContext(tokens: []const token_mod.Token, index: usize) bool {
    if (index >= tokens.len or index < 2 or tokens.len == 0) return false;
    return tokens[0].matchesKeywordTag(.declare);
}

fn generatedSystemTimeForKeywordContext(tokens: []const token_mod.Token, index: usize) bool {
    if (index + 3 >= tokens.len) return false;
    return tokens[index].matchesKeywordTag(.@"for") and
        std.ascii.eqlIgnoreCase(tokens[index + 1].text, "system_time") and
        tokens[index + 2].matchesKeywordTag(.as) and
        tokens[index + 3].matchesKeywordTag(.of);
}

fn generatedAnalyzeKeywordContext(tokens: []const token_mod.Token, index: usize) bool {
    return index == 1 and tokens.len > 0 and tokens[0].matchesKeywordTag(.analyze);
}

fn generatedCopyDiagnosticIdentifierContext(tokens: []const token_mod.Token, index: usize) bool {
    return index > 0 and tokens.len > 0 and tokens[0].matchesKeywordTag(.copy);
}

fn generatedAlterTableDiagnosticIdentifierContext(tokens: []const token_mod.Token, index: usize) bool {
    if (index < 4 or tokens.len < 4) return false;
    if (!tokens[0].matchesKeywordTag(.alter) or !tokens[1].matchesKeywordTag(.table)) return false;
    var cursor: usize = 2;
    _ = consumeGeneratedIfExists(tokens, &cursor, tokens.len);
    if (cursor < tokens.len and tokens[cursor].matchesKeywordTag(.only)) cursor += 1;
    const table = generatedQualifiedNameRange(tokens, cursor, tokens.len) orelse return false;
    if (index < table.end) return false;
    return generatedAlterTableTailHasCommaBefore(tokens, table.end, index);
}

fn generatedAlterTableForeignKeyMatchClauseContext(tokens: []const token_mod.Token, index: usize) bool {
    return index > 0 and
        index + 1 < tokens.len and
        tokens[index - 1].kind == .rparen and
        (tokens[index + 1].matchesKeywordTag(.full) or tokens[index + 1].kind == .identifier);
}

fn generatedAlterTableTailHasCommaBefore(tokens: []const token_mod.Token, start: usize, end: usize) bool {
    var depth: usize = 0;
    var index = start;
    while (index < end and index < tokens.len) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth > 0) depth -= 1;
            },
            .comma => if (depth == 0) return true,
            else => {},
        }
    }
    return false;
}

fn generatedCreateRoutineDiagnosticIdentifierContext(tokens: []const token_mod.Token, index: usize) bool {
    if (index < 5 or tokens.len < 5) return false;
    if (!tokens[0].matchesKeywordTag(.create)) return false;
    var cursor: usize = 1;
    if (cursor + 1 < tokens.len and tokens[cursor].matchesKeywordTag(.@"or") and tokens[cursor + 1].matchesKeywordTag(.replace)) {
        cursor += 2;
    }
    if (cursor >= tokens.len or
        !(tokens[cursor].matchesKeywordTag(.function) or tokens[cursor].matchesKeywordTag(.procedure)))
    {
        return false;
    }
    cursor += 1;
    const routine_name = generatedQualifiedNameRange(tokens, cursor, tokens.len) orelse return false;
    cursor = routine_name.end;
    if (cursor >= tokens.len or tokens[cursor].kind != .lparen) return false;
    const close = findMatchingParen(tokens, cursor, tokens.len) orelse return false;
    return index > close;
}

fn generatedCreateTriggerDiagnosticIdentifierContext(tokens: []const token_mod.Token, index: usize) bool {
    if (tokens.len < 3 or index < 2 or !tokens[0].matchesKeywordTag(.create)) return false;
    if (tokens[1].matchesKeywordTag(.trigger)) return index >= 2;
    return index >= 4 and
        tokens.len >= 5 and
        tokens[1].matchesKeywordTag(.@"or") and
        tokens[2].matchesKeywordTag(.replace) and
        tokens[3].matchesKeywordTag(.trigger);
}

fn generatedCreateTriggerDiagnosticKeywordAsIdentifier(tok: token_mod.Token) bool {
    return tok.matchesKeywordTag(.@"and") or
        tok.matchesKeywordTag(.any) or
        tok.matchesKeywordTag(.array) or
        tok.matchesKeywordTag(.between) or
        tok.matchesKeywordTag(.case) or
        tok.matchesKeywordTag(.cast) or
        tok.matchesKeywordTag(.current) or
        tok.matchesKeywordTag(.current_date) or
        tok.matchesKeywordTag(.current_timestamp) or
        tok.matchesKeywordTag(.distinct) or
        tok.matchesKeywordTag(.@"else") or
        tok.matchesKeywordTag(.end) or
        tok.matchesKeywordTag(.escape) or
        tok.matchesKeywordTag(.extract) or
        tok.matchesKeywordTag(.filter) or
        tok.matchesKeywordTag(.ilike) or
        tok.matchesKeywordTag(.interval) or
        tok.matchesKeywordTag(.like) or
        tok.matchesKeywordTag(.@"or") or
        tok.matchesKeywordTag(.position) or
        tok.matchesKeywordTag(.some) or
        tok.matchesKeywordTag(.then) or
        tok.matchesKeywordTag(.unknown) or
        tok.matchesKeywordTag(.when);
}

fn generatedCreateTableMissingAsSelectContext(tokens: []const token_mod.Token, index: usize) bool {
    return index == 1 and generatedCreateTableMissingAsSelect(tokens);
}

fn generatedSessionAuthorizationKeywordContext(tokens: []const token_mod.Token, index: usize) bool {
    if (index >= tokens.len or tokens.len < 3) return false;
    const first = tokens[0];
    if (!first.matchesKeywordTag(.set) and !first.matchesKeywordTag(.reset)) return false;
    if (!tokens[1].matchesKeyword("session")) return false;
    if (!tokens[2].matchesKeyword("authorization")) return false;
    return index == 1 or index == 2;
}

fn generatedIndexConcurrentlyKeywordContext(tokens: []const token_mod.Token, index: usize) bool {
    if (index >= tokens.len or tokens.len < 3) return false;
    const first = tokens[0];
    if (first.matchesKeywordTag(.drop)) {
        return index == 2 and tokens.len > 3 and tokens[1].matchesKeywordTag(.index);
    }
    if (!first.matchesKeywordTag(.create)) return false;
    if (tokens[1].matchesKeywordTag(.index)) return index == 2 and tokens.len > 3;
    return index == 3 and tokens.len > 4 and tokens[1].matchesKeywordTag(.unique) and tokens[2].matchesKeywordTag(.index);
}

fn generatedIndexElementCollateKeywordContext(
    tokens: []const token_mod.Token,
    index: usize,
    tok: token_mod.Token,
    prev: ?token_mod.Token,
    next: ?token_mod.Token,
) bool {
    if (!tok.matchesKeyword("collate")) return false;
    if (prev == null or next == null or next.?.kind != .identifier) return false;
    switch (prev.?.kind) {
        .lparen, .comma, .semicolon => return false,
        else => {},
    }
    if (tokens.len < 6 or !tokens[0].matchesKeywordTag(.create)) return false;
    var open_index: ?usize = null;
    var close_index: ?usize = null;
    var depth: usize = 0;
    for (tokens, 0..) |candidate, candidate_index| {
        switch (candidate.kind) {
            .lparen => {
                if (depth == 0 and open_index == null and candidate_index > 0) open_index = candidate_index;
                depth += 1;
            },
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
                if (depth == 0 and open_index != null and close_index == null) {
                    close_index = candidate_index;
                    break;
                }
            },
            else => {},
        }
    }
    const open = open_index orelse return false;
    const close = close_index orelse return false;
    if (index <= open or index >= close) return false;
    var saw_index = false;
    var saw_on = false;
    for (tokens[0..open]) |candidate| {
        if (candidate.matchesKeywordTag(.index)) saw_index = true;
        if (candidate.matchesKeywordTag(.on)) saw_on = true;
    }
    return saw_index and saw_on;
}

fn generatedTransactionControlContext(tokens: []const token_mod.Token, index: usize) bool {
    if (index >= tokens.len or tokens.len == 0) return false;
    const first = tokens[0];
    if (first.matchesKeyword("start")) return true;
    if (first.matchesKeywordTag(.begin)) return true;
    if (first.matchesKeywordTag(.savepoint)) return true;
    if (first.matchesKeywordTag(.release)) return true;
    if (first.matchesKeywordTag(.prepare)) return index <= 1;
    if (first.matchesKeywordTag(.commit)) return index <= 1;
    if (first.matchesKeywordTag(.end)) return index <= 1;
    if (first.matchesKeywordTag(.rollback)) return index <= 3;
    if (!first.matchesKeywordTag(.set)) return false;
    if (tokens.len > 1 and tokens[1].matchesKeyword("constraints")) return true;
    if (tokens.len > 1 and tokens[1].matchesKeyword("transaction")) return true;
    return tokens.len > 4 and
        tokens[1].matchesKeyword("session") and
        tokens[2].matchesKeyword("characteristics") and
        tokens[3].matchesKeywordTag(.as) and
        tokens[4].matchesKeyword("transaction");
}

fn generatedRoutineKeywordContext(tokens: []const token_mod.Token, index: usize) bool {
    if (index >= tokens.len or tokens.len == 0) return false;
    if (index != 1) return false;
    return tokens[0].matchesKeywordTag(.drop);
}

fn generatedParserTreatsKeywordAsIdentifier(tokens: []const token_mod.Token, index: usize, tok: token_mod.Token, prev: ?token_mod.Token, next: ?token_mod.Token) bool {
    if (tok.matchesKeywordTag(.conflict)) {
        return prev != null and prev.?.matchesKeywordTag(.as);
    }
    if (tok.matchesKeywordTag(.offset)) return next != null and next.?.matchesKeywordTag(.limit);
    if (tok.matchesKeywordTag(.fetch)) return prev != null and prev.?.matchesKeywordTag(.as);
    if (tok.matchesKeywordTag(.start)) return next != null and next.?.kind == .eq;
    if (tok.matchesKeywordTag(.rows)) {
        if (generatedRowsKeywordStartsWindowFrame(tokens, index)) return false;
        return prev != null and prev.?.kind == .identifier and next != null and next.?.kind == .number;
    }
    if (tok.matchesKeywordTag(.window)) {
        return prev != null and prev.?.kind == .identifier and (next == null or next.?.kind == .semicolon);
    }
    return false;
}

fn generatedRowsKeywordStartsWindowFrame(tokens: []const token_mod.Token, index: usize) bool {
    if (index >= tokens.len or !tokens[index].matchesKeywordTag(.rows)) return false;
    var depth: usize = 0;
    var cursor = index;
    while (cursor > 0) {
        cursor -= 1;
        switch (tokens[cursor].kind) {
            .rparen, .rbracket => depth += 1,
            .lparen, .lbracket => {
                if (depth == 0) break;
                depth -= 1;
            },
            .semicolon => if (depth == 0) break,
            else => {},
        }
        if (depth == 0 and cursor > 0 and tokens[cursor].matchesKeywordTag(.by) and tokens[cursor - 1].matchesKeywordTag(.order)) return true;
    }
    return false;
}

fn appendIdentifierIds(ids: *TokenIdSink, text: []const u8, allow_trailing_dot: bool) !void {
    if (text.len == 0) return error.UnsupportedSqlShape;
    const has_trailing_dot = text[text.len - 1] == '.';
    if (has_trailing_dot and !allow_trailing_dot) return error.UnsupportedSqlShape;
    const body = if (has_trailing_dot) text[0 .. text.len - 1] else text;
    if (body.len == 0) return error.UnsupportedSqlShape;

    var parts = std.mem.splitScalar(u8, body, '.');
    var emitted = false;
    while (parts.next()) |part| {
        if (part.len == 0) return error.UnsupportedSqlShape;
        if (emitted) try ids.appendToken(.DOT);
        try ids.appendToken(.IDENT);
        emitted = true;
    }
    if (has_trailing_dot) try ids.appendToken(.DOT);
}

fn keywordSymbolId(tok: token_mod.Token) !?u16 {
    if (tok.keyword == null) return null;
    if (tok.text.len > 128) return error.UnsupportedSqlShape;
    var name_buffer: [128]u8 = undefined;
    const name = uppercaseKeyword(&name_buffer, tok.text);
    return generated.terminalIdByName(name);
}

fn uppercaseKeyword(buffer: []u8, text: []const u8) []const u8 {
    std.debug.assert(text.len <= buffer.len);
    const out = buffer[0..text.len];
    for (text, 0..) |ch, idx| {
        out[idx] = switch (ch) {
            'a'...'z' => ch - 'a' + 'A',
            else => ch,
        };
    }
    return out;
}

fn trailingSemicolonOnly(tokens: []const token_mod.Token, index: usize) bool {
    if (tokens[index].kind != .semicolon) return false;
    for (tokens[index + 1 ..]) |tok| {
        if (tok.kind != .semicolon) return false;
    }
    return true;
}

fn classifyTokens(tokens: []const token_mod.Token) GeneratedSqlStatementKind {
    return std.meta.activeTag(classifyStatement(tokens));
}

fn classifyStatement(tokens: []const token_mod.Token) GeneratedSqlStatement {
    if (tokens.len == 0) return .other;
    const first = tokens[0];
    if (first.matchesKeywordTag(.prepare) and tokens.len > 1 and tokens[1].matchesKeyword("transaction")) return .{ .prepared_transaction = .prepare };
    if (first.matchesKeywordTag(.commit) and tokens.len > 1 and tokens[1].matchesKeyword("prepared")) return .{ .prepared_transaction = .commit };
    if (first.matchesKeywordTag(.rollback) and tokens.len > 1 and tokens[1].matchesKeyword("prepared")) return .{ .prepared_transaction = .rollback };
    if (first.matchesKeywordTag(.set) and tokens.len > 1 and tokens[1].matchesKeyword("transaction")) return .{ .transaction = .set_transaction };
    if (first.matchesKeywordTag(.set) and tokens.len > 1 and tokens[1].matchesKeyword("constraints")) return .{ .transaction = .constraint_mode };
    if (first.matchesKeywordTag(.set) and tokens.len > 1 and tokens[1].matchesKeywordTag(.role)) return .{ .unsupported = .role_session_control };
    if (first.matchesKeywordTag(.set) and tokens.len > 2 and tokens[1].matchesKeyword("session") and tokens[2].matchesKeyword("authorization")) return .{ .unsupported = .role_session_control };
    if (first.matchesKeywordTag(.set)) return .{ .session = .set };
    if (first.matchesKeywordTag(.reset) and tokens.len > 1 and tokens[1].matchesKeywordTag(.role)) return .{ .unsupported = .role_session_control };
    if (first.matchesKeywordTag(.reset) and tokens.len > 2 and tokens[1].matchesKeyword("session") and tokens[2].matchesKeyword("authorization")) return .{ .unsupported = .role_session_control };
    if (first.matchesKeywordTag(.reset)) return .{ .session = .reset };
    if (first.matchesKeywordTag(.show)) return .{ .session = .show };
    if (first.matchesKeywordTag(.discard)) {
        if (tokens.len > 1 and tokens[1].matchesKeywordTag(.all)) return .{ .session = .discard_all };
        return .{ .unsupported = .discard };
    }
    if (first.matchesKeyword("start")) return .{ .transaction = .start_transaction };
    if (first.matchesKeywordTag(.begin)) return .{ .transaction = .begin };
    if (first.matchesKeywordTag(.commit)) return .{ .transaction = .commit };
    if (first.matchesKeywordTag(.end)) return .{ .transaction = .commit };
    if (first.matchesKeywordTag(.rollback)) {
        if (tokens.len > 1 and tokens[1].matchesKeywordTag(.to)) return .{ .transaction = .rollback_to_savepoint };
        return .{ .transaction = .rollback };
    }
    if (first.matchesKeywordTag(.savepoint)) return .{ .transaction = .savepoint };
    if (first.matchesKeywordTag(.release)) return .{ .transaction = .release_savepoint };
    if (first.matchesKeywordTag(.prepare)) return .{ .prepared = .prepare };
    if (first.matchesKeywordTag(.execute)) return .{ .prepared = .execute };
    if (first.matchesKeywordTag(.deallocate)) return .{ .prepared = .deallocate };
    if (first.matchesKeywordTag(.close)) return .{ .cursor = .close };
    if (first.matchesKeywordTag(.declare)) return .{ .cursor = .declare };
    if (first.matchesKeywordTag(.fetch)) return .{ .cursor = .fetch };
    if (first.matchesKeywordTag(.move)) return .{ .cursor = .move };
    if (first.matchesKeywordTag(.create) and tokens.len > 1) {
        if (generatedCreateTableMissingAsSelect(tokens)) return .{ .unsupported = .create_table_missing_as };
        if (generatedCreateTableExclusionConstraintUnsupported(tokens)) return .{ .unsupported = .create_table_exclusion_constraint };
        if (generatedCreateTableAsTargetRange(tokens, 0, statementTokenEnd(tokens)) != null) return .{ .ddl = .relation_population };
        if (generatedCreateTableTargetRange(tokens, 0, statementTokenEnd(tokens)) != null) return .{ .ddl = .create_table };
        const second = tokens[1];
        if (second.matchesKeyword("document") and tokens.len > 2 and tokens[2].matchesKeywordTag(.table)) return .{ .unsupported = .create_document_table_shorthand };
        if (second.matchesKeywordTag(.@"or") and tokens.len > 3 and tokens[2].matchesKeywordTag(.replace) and tokens[3].matchesKeywordTag(.table)) return .{ .ddl = .create_table };
        if (second.matchesKeywordTag(.@"or") and tokens.len > 3 and tokens[2].matchesKeywordTag(.replace) and tokens[3].matchesKeywordTag(.view)) return .{ .ddl = .create_view };
        if (second.matchesKeywordTag(.@"or") and tokens.len > 4 and tokens[2].matchesKeywordTag(.replace) and tokens[3].matchesKeywordTag(.materialized) and tokens[4].matchesKeywordTag(.view)) return .{ .ddl = .create_materialized_view };
        if (second.matchesKeywordTag(.@"or") and tokens.len > 3 and tokens[2].matchesKeywordTag(.replace) and tokens[3].matchesKeywordTag(.function)) return .{ .ddl = .create_function };
        if (second.matchesKeywordTag(.@"or") and tokens.len > 3 and tokens[2].matchesKeywordTag(.replace) and tokens[3].matchesKeywordTag(.procedure)) return .{ .ddl = .create_procedure };
        if (second.matchesKeywordTag(.database)) {
            if (generatedCreateCatalogHeadHasUnsupportedTail(tokens, 2)) return .{ .unsupported = .create_database_options };
            return .{ .ddl = .create_database };
        }
        if (second.matchesKeywordTag(.schema)) {
            if (generatedCreateCatalogHeadHasUnsupportedTail(tokens, 2)) return .{ .unsupported = .create_schema_options };
            return .{ .ddl = .create_schema };
        }
        if (second.matchesKeywordTag(.table)) return .{ .ddl = .create_table };
        if (second.matchesKeywordTag(.view)) return .{ .ddl = .create_view };
        if (second.matchesKeywordTag(.materialized) and tokens.len > 2 and tokens[2].matchesKeywordTag(.view)) return .{ .ddl = .create_materialized_view };
        if (second.matchesKeywordTag(.domain)) return .{ .ddl = .create_domain };
        if (second.matchesKeywordTag(.sequence)) return .{ .ddl = .create_sequence };
        if (second.matchesKeywordTag(.type)) return .{ .ddl = .create_enum_type };
        if (second.matchesKeywordTag(.tablespace)) return .{ .ddl = .create_tablespace };
        if (second.matchesKeywordTag(.publication)) return .{ .ddl = .create_publication };
        if (second.matchesKeywordTag(.subscription)) return .{ .ddl = .create_subscription };
        if (second.matchesKeywordTag(.policy)) return .{ .ddl = .create_policy };
        if (second.matchesKeywordTag(.function)) return .{ .ddl = .create_function };
        if (second.matchesKeywordTag(.procedure)) return .{ .ddl = .create_procedure };
        if (second.matchesKeyword("user") and tokens.len > 2 and tokens[2].matchesKeyword("mapping")) return .{ .unsupported = .create_user_mapping };
        if (isGeneratedRoleAliasKeyword(second)) return .{ .ddl = .create_role };
        if (second.matchesKeywordTag(.collation)) return .{ .ddl = .create_collation };
        if (second.matchesKeywordTag(.operator)) {
            if (tokens.len > 2 and tokens[2].matchesKeyword("class")) return .{ .unsupported = .create_operator_class };
            if (tokens.len > 2 and tokens[2].matchesKeyword("family")) return .{ .unsupported = .create_operator_family };
            return .{ .ddl = .create_operator };
        }
        if (second.matchesKeywordTag(.aggregate)) return .{ .ddl = .create_aggregate };
        if (second.matchesKeywordTag(.cast)) return .{ .ddl = .create_cast };
        if (second.matchesKeywordTag(.index)) return .{ .extension_index = .create_index };
        if (second.matchesKeywordTag(.unique) and tokens.len > 2 and tokens[2].matchesKeywordTag(.index)) return .{ .extension_index = .create_index };
        if (second.matchesKeywordTag(.access) and tokens.len > 2 and tokens[2].matchesKeywordTag(.method)) return .{ .unsupported = .create_access_method };
        if (second.matchesKeyword("conversion")) return .{ .unsupported = .create_conversion };
        if (second.matchesKeyword("event") and tokens.len > 2 and tokens[2].matchesKeywordTag(.trigger)) return .{ .unsupported = .create_event_trigger };
