fn isGeneratedRoleAliasKeyword(token: token_mod.Token) bool {
    return token.matchesKeywordTag(.role) or
        token.matchesKeyword("user") or
        token.matchesKeywordTag(.group);
}

fn generatedCreateLanguageUnsupported(tokens: []const token_mod.Token) bool {
    if (tokens.len < 3 or !tokens[0].matchesKeywordTag(.create)) return false;
    var index: usize = 1;
    if (index + 1 < tokens.len and
        tokens[index].matchesKeywordTag(.@"or") and
        tokens[index + 1].matchesKeywordTag(.replace))
    {
        index += 2;
    }
    if (index < tokens.len and tokens[index].matchesKeyword("trusted")) index += 1;
    if (index + 1 < tokens.len and tokens[index].matchesKeyword("procedural")) {
        index += 1;
    }
    return index < tokens.len and tokens[index].matchesKeyword("language");
}

fn classifyReadKind(tokens: []const token_mod.Token) GeneratedSqlReadKind {
    return classifyReadKindInRange(tokens, .{ .start = 0, .end = statementTokenEnd(tokens) });
}

fn generatedReadRowLockStart(tokens: []const token_mod.Token, start: usize, end: usize) ?usize {
    var depth: usize = 0;
    var index = start;
    var candidate: ?usize = null;
    while (index < end and index < tokens.len) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth > 0) depth -= 1;
            },
            else => {},
        }
        if (depth != 0 or !tokens[index].matchesKeywordTag(.@"for")) continue;
        if (!generatedReadRowLockModeStartsAt(tokens, index + 1, end)) continue;
        if (generatedReadHasCompleteSourceBefore(tokens, start, index)) candidate = index;
    }
    return candidate;
}

fn generatedReadRowLockModeStartsAt(tokens: []const token_mod.Token, start: usize, end: usize) bool {
    if (start >= end or end > tokens.len) return false;
    if (tokens[start].matchesKeywordTag(.update) or tokens[start].matchesKeywordTag(.share)) return true;
    if (start + 1 < end and
        tokens[start].matchesKeywordTag(.key) and
        tokens[start + 1].matchesKeywordTag(.share))
    {
        return true;
    }
    if (start + 2 < end and
        tokens[start].matchesKeywordTag(.no) and
        tokens[start + 1].matchesKeywordTag(.key) and
        tokens[start + 2].matchesKeywordTag(.update))
    {
        return true;
    }
    return false;
}

const GeneratedRowLockSemantics = struct {
    mode: GeneratedSqlRowLockMode,
    wait_policy: GeneratedSqlRowLockWaitPolicy,
};

fn generatedRowLockSemantics(
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) ?GeneratedRowLockSemantics {
    if (range.start + 1 >= range.end or range.end > tokens.len) return null;
    if (!tokens[range.start].matchesKeywordTag(.@"for")) return null;
    var cursor = range.start + 1;
    const mode: GeneratedSqlRowLockMode = if (tokens[cursor].matchesKeywordTag(.update)) blk: {
        cursor += 1;
        break :blk .update;
    } else if (tokens[cursor].matchesKeywordTag(.share)) blk: {
        cursor += 1;
        break :blk .share;
    } else if (cursor + 1 < range.end and
        tokens[cursor].matchesKeywordTag(.key) and
        tokens[cursor + 1].matchesKeywordTag(.share))
    blk: {
        cursor += 2;
        break :blk .key_share;
    } else if (cursor + 2 < range.end and
        tokens[cursor].matchesKeywordTag(.no) and
        tokens[cursor + 1].matchesKeywordTag(.key) and
        tokens[cursor + 2].matchesKeywordTag(.update))
    blk: {
        cursor += 3;
        break :blk .no_key_update;
    } else return null;

    if (cursor < range.end and tokens[cursor].matchesKeywordTag(.of)) {
        cursor += 1;
        if (cursor >= range.end) return null;
        var saw_target = false;
        var previous_was_comma = true;
        while (cursor < range.end and
            !tokens[cursor].matchesKeywordTag(.nowait) and
            !tokens[cursor].matchesKeywordTag(.skip))
        {
            if (tokens[cursor].kind == .comma) {
                if (previous_was_comma) return null;
                previous_was_comma = true;
            } else {
                saw_target = true;
                previous_was_comma = false;
            }
            cursor += 1;
        }
        if (!saw_target or previous_was_comma) return null;
    }

    var wait_policy = GeneratedSqlRowLockWaitPolicy.wait;
    if (cursor < range.end) {
        if (tokens[cursor].matchesKeywordTag(.nowait)) {
            wait_policy = .nowait;
            cursor += 1;
        } else if (cursor + 1 < range.end and
            tokens[cursor].matchesKeywordTag(.skip) and
            tokens[cursor + 1].matchesKeywordTag(.locked))
        {
            wait_policy = .skip_locked;
            cursor += 2;
        } else return null;
    }
    if (cursor != range.end) return null;
    return .{ .mode = mode, .wait_policy = wait_policy };
}

fn generatedReadHasCompleteSourceBefore(tokens: []const token_mod.Token, start: usize, end: usize) bool {
    var depth: usize = 0;
    var index = start;
    while (index < end and index < tokens.len) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth > 0) depth -= 1;
            },
            else => {},
        }
        if (depth == 0 and tokens[index].matchesKeywordTag(.from) and index + 1 < end) return true;
    }
    return false;
}

fn generatedSelectIntoTargetRange(tokens: []const token_mod.Token, start: usize, end: usize) ?GeneratedSqlTokenRange {
    const into_index = findTopLevelKeyword(tokens, start, end, .into) orelse return null;
    var index = into_index + 1;
    consumeGeneratedRelationLifetime(tokens, &index, end);
    if (index < end and tokens[index].matchesKeywordTag(.table)) index += 1;
    return generatedQualifiedNameRange(tokens, index, end);
}

fn generatedCreateTableAsTargetRange(tokens: []const token_mod.Token, start: usize, end: usize) ?GeneratedSqlTokenRange {
    var index = start + 1;
    consumeGeneratedRelationLifetime(tokens, &index, end);
    if (index >= end or !tokens[index].matchesKeywordTag(.table)) return null;
    index += 1;
    consumeGeneratedOnlyPrefix(tokens, &index, end);
    _ = consumeGeneratedIfNotExists(tokens, &index, end);
    const target = generatedQualifiedNameRange(tokens, index, end) orelse return null;
    index = target.end;
    if (index >= end or !tokens[index].matchesKeywordTag(.as)) return null;
    return target;
}

