            .drop_operator_family => .drop_operator_family_not_planned_by_generated_parser,
            .drop_publication_multi => .drop_publication_multi_not_planned_by_generated_parser,
            .drop_routine => .drop_routine_not_planned_by_generated_parser,
            .drop_role_multi => .drop_role_multi_not_planned_by_generated_parser,
            .drop_schema_multi => .drop_schema_multi_not_planned_by_generated_parser,
            .drop_sequence_multi => .drop_sequence_multi_not_planned_by_generated_parser,
            .drop_statistics => .drop_statistics_not_planned_by_generated_parser,
            .drop_table_multi => .drop_table_multi_not_planned_by_generated_parser,
            .drop_text_search_configuration => .drop_text_search_configuration_not_planned_by_generated_parser,
            .drop_text_search_dictionary => .drop_text_search_dictionary_not_planned_by_generated_parser,
            .drop_text_search_parser => .drop_text_search_parser_not_planned_by_generated_parser,
            .drop_text_search_template => .drop_text_search_template_not_planned_by_generated_parser,
            .drop_transform => .drop_transform_not_planned_by_generated_parser,
            .drop_type_multi => .drop_type_multi_not_planned_by_generated_parser,
            .drop_user_mapping => .drop_user_mapping_not_planned_by_generated_parser,
            .drop_view_multi => .drop_view_multi_not_planned_by_generated_parser,
            .explain => .explain_not_planned_by_generated_parser,
            .graph_query => .graph_query_not_planned_by_generated_parser,
            .grant => .grant_not_planned_by_generated_parser,
            .import_foreign_schema => .import_foreign_schema_not_planned_by_generated_parser,
            .listen => .listen_not_planned_by_generated_parser,
            .load => .load_not_planned_by_generated_parser,
            .lock => .lock_not_planned_by_generated_parser,
            .notify => .notify_not_planned_by_generated_parser,
            .reassign_owned => .reassign_owned_not_planned_by_generated_parser,
            .reindex => .reindex_not_planned_by_generated_parser,
            .restore_database => .restore_database_not_planned_by_generated_parser,
            .revoke => .revoke_not_planned_by_generated_parser,
            .role_session_control => .role_session_control_not_planned_by_generated_parser,
            .security_label => .security_label_not_planned_by_generated_parser,
            .drop_materialized_view => .drop_materialized_view_not_planned_by_generated_parser,
            .drop_policy => .drop_policy_not_planned_by_generated_parser,
            .drop_publication => .drop_publication_not_planned_by_generated_parser,
            .drop_rule => .drop_rule_not_planned_by_generated_parser,
            .drop_server => .drop_server_not_planned_by_generated_parser,
            .drop_subscription => .drop_subscription_not_planned_by_generated_parser,
            .drop_trigger => .drop_trigger_not_planned_by_generated_parser,
            .unlisten => .unlisten_not_planned_by_generated_parser,
            .vacuum => .vacuum_not_planned_by_generated_parser,
        },
        .statement_span = statement_span,
        .command_span = command_span,
    };
    errdefer ast.deinit(alloc);
    if (kind == .explain) {
        try populateGeneratedExplainUnsupportedAst(alloc, tokens, end, &ast);
    } else if (generatedUnsupportedSubjectStart(tokens, kind, end)) |subject_start| {
        ast.subject_tokens = .{ .start = subject_start, .end = end };
        if (kind == .alter_function or kind == .alter_procedure) {
            try populateGeneratedUnsupportedAlterRoutineAst(alloc, tokens, end, &ast);
        } else if (kind == .call) {
            populateGeneratedUnsupportedProcedureCallAst(tokens, end, &ast);
        } else if (generatedUnsupportedAlterTableOperationKind(kind)) {
            populateGeneratedUnsupportedAlterTableAst(tokens, end, &ast);
        } else if (kind == .create_trigger or kind == .drop_trigger) {
            populateGeneratedUnsupportedTriggerAst(tokens, end, &ast);
        } else if (kind == .listen or kind == .notify or kind == .unlisten) {
            populateGeneratedUnsupportedNotificationAst(tokens, end, &ast);
        } else if (kind == .lock) {
            try populateGeneratedUnsupportedTableLockAst(alloc, tokens, end, &ast);
        } else if (kind == .vacuum or kind == .analyze or kind == .reindex or kind == .cluster) {
            try populateGeneratedUnsupportedMaintenanceAst(alloc, tokens, end, &ast);
        } else if (kind == .copy) {
            try populateGeneratedUnsupportedBulkIoAst(alloc, tokens, end, &ast);
        } else if (kind == .graph_query) {
            try populateGeneratedUnsupportedGraphQueryAst(alloc, tokens, end, &ast);
        }
    }
    return ast;
}

fn populateGeneratedUnsupportedBulkIoAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    const table_name = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
    index = table_name.end;

    var columns = GeneratedSqlListAst{};
    defer columns.deinit(alloc);
    if (index < end and tokens[index].kind == .lparen) {
        const column_close = findMatchingParen(tokens, index, end) orelse return;
        columns = try buildTopLevelTokenListAst(alloc, tokens, .{ .start = index + 1, .end = column_close });
        if (!generatedBulkIoIdentifierListIsValid(tokens, columns)) return;
        index = column_close + 1;
    }

    const direction: GeneratedSqlBulkIoDirection = if (consumeGeneratedBulkIoKeywordText(tokens, &index, end, "from"))
        .from
    else if (consumeGeneratedBulkIoKeywordText(tokens, &index, end, "to"))
        .to
    else
        return;

    var endpoint_kind: GeneratedSqlBulkIoEndpointKind = .stream;
    const endpoint_tokens: GeneratedSqlTokenRange = blk: {
        if (consumeGeneratedBulkIoKeywordText(tokens, &index, end, "program")) {
            endpoint_kind = .program;
            break :blk generatedSingleTokenRangeIfKind(tokens, index, end, .string) orelse return;
        }
        if (index < end and tokens[index].kind == .string) {
            endpoint_kind = .file;
            break :blk .{ .start = index, .end = index + 1 };
        }
        break :blk generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
    };
    index = endpoint_tokens.end;
    if (endpoint_kind == .stream) {
        switch (direction) {
            .from => if (!std.ascii.eqlIgnoreCase(tokens[endpoint_tokens.start].text, "STDIN")) return,
            .to => if (!std.ascii.eqlIgnoreCase(tokens[endpoint_tokens.start].text, "STDOUT")) return,
        }
    }

    var option_items = GeneratedSqlListAst{};
    defer option_items.deinit(alloc);
    var force_quote_columns = GeneratedSqlListAst{};
    defer force_quote_columns.deinit(alloc);
    var force_not_null_columns = GeneratedSqlListAst{};
    defer force_not_null_columns.deinit(alloc);
    var force_null_columns = GeneratedSqlListAst{};
    defer force_null_columns.deinit(alloc);

    var format_tokens: ?GeneratedSqlTokenRange = null;
    var header = false;
    var freeze = false;
    var on_error: GeneratedSqlBulkIoOnErrorPolicy = .stop;
    var reject_limit_tokens: ?GeneratedSqlTokenRange = null;
    var log_verbosity: GeneratedSqlBulkIoLogVerbosity = .default;
    var force_quote_all = false;
    var delimiter_tokens: ?GeneratedSqlTokenRange = null;
    var quote_tokens: ?GeneratedSqlTokenRange = null;
    var escape_tokens: ?GeneratedSqlTokenRange = null;
    var null_tokens: ?GeneratedSqlTokenRange = null;
    var default_tokens: ?GeneratedSqlTokenRange = null;
    var encoding_tokens: ?GeneratedSqlTokenRange = null;

    if (consumeGeneratedBulkIoKeywordText(tokens, &index, end, "with")) {
        if (index >= end or tokens[index].kind != .lparen) return;
        const options_close = findMatchingParen(tokens, index, end) orelse return;
        option_items = try buildTopLevelTokenListAst(alloc, tokens, .{ .start = index + 1, .end = options_close });
        if (option_items.count == 0 or option_items.count != option_items.items.len) return;
        for (option_items.items) |item| {
            var option_index = item.start;
            if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "format")) {
                if (format_tokens != null) return;
                format_tokens = generatedSingleTokenRangeIfIdentifier(tokens, option_index, item.end) orelse return;
                if (format_tokens.?.end != item.end) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "header")) {
                header = generatedBulkIoBool(tokens, &option_index, item.end) orelse return;
                if (option_index != item.end) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "freeze")) {
                freeze = generatedBulkIoBool(tokens, &option_index, item.end) orelse return;
                if (option_index != item.end) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "on_error")) {
                const value = generatedSingleTokenRangeIfIdentifier(tokens, option_index, item.end) orelse return;
                if (std.ascii.eqlIgnoreCase(tokens[value.start].text, "stop")) {
                    on_error = .stop;
                } else if (std.ascii.eqlIgnoreCase(tokens[value.start].text, "ignore")) {
                    on_error = .ignore;
                } else return;
                if (value.end != item.end) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "reject_limit")) {
                if (reject_limit_tokens != null) return;
                reject_limit_tokens = generatedBulkIoPositiveIntegerRange(tokens, option_index, item.end) orelse return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "log_verbosity")) {
                const value = generatedSingleTokenRangeIfIdentifier(tokens, option_index, item.end) orelse return;
                if (std.ascii.eqlIgnoreCase(tokens[value.start].text, "default")) {
                    log_verbosity = .default;
                } else if (std.ascii.eqlIgnoreCase(tokens[value.start].text, "verbose")) {
                    log_verbosity = .verbose;
                } else if (std.ascii.eqlIgnoreCase(tokens[value.start].text, "terse")) {
                    log_verbosity = .terse;
                } else return;
                if (value.end != item.end) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "force_quote")) {
                if (force_quote_all or force_quote_columns.count != 0) return;
                if (option_index < item.end and tokens[option_index].kind == .star) {
                    force_quote_all = true;
                    option_index += 1;
                    if (option_index != item.end) return;
                } else if (option_index < item.end and tokens[option_index].kind == .lparen) {
                    const close = findMatchingParen(tokens, option_index, item.end) orelse return;
                    if (close + 1 != item.end) return;
                    force_quote_columns = try buildTopLevelTokenListAst(alloc, tokens, .{ .start = option_index + 1, .end = close });
                    if (!generatedBulkIoIdentifierListIsValid(tokens, force_quote_columns)) return;
                } else return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "force_not_null")) {
                if (force_not_null_columns.count != 0 or option_index >= item.end or tokens[option_index].kind != .lparen) return;
                const close = findMatchingParen(tokens, option_index, item.end) orelse return;
                if (close + 1 != item.end) return;
                force_not_null_columns = try buildTopLevelTokenListAst(alloc, tokens, .{ .start = option_index + 1, .end = close });
                if (!generatedBulkIoIdentifierListIsValid(tokens, force_not_null_columns)) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "force_null")) {
                if (force_null_columns.count != 0 or option_index >= item.end or tokens[option_index].kind != .lparen) return;
                const close = findMatchingParen(tokens, option_index, item.end) orelse return;
                if (close + 1 != item.end) return;
                force_null_columns = try buildTopLevelTokenListAst(alloc, tokens, .{ .start = option_index + 1, .end = close });
                if (!generatedBulkIoIdentifierListIsValid(tokens, force_null_columns)) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "delimiter")) {
                if (delimiter_tokens != null) return;
                delimiter_tokens = generatedBulkIoOneByteStringRange(tokens, option_index, item.end) orelse return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "quote")) {
                if (quote_tokens != null) return;
                quote_tokens = generatedBulkIoOneByteStringRange(tokens, option_index, item.end) orelse return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "escape")) {
                if (escape_tokens != null) return;
                escape_tokens = generatedBulkIoOneByteStringRange(tokens, option_index, item.end) orelse return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "null")) {
                if (null_tokens != null) return;
                null_tokens = generatedSingleTokenRangeIfKind(tokens, option_index, item.end, .string) orelse return;
                if (null_tokens.?.end != item.end) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "default")) {
                if (default_tokens != null) return;
                default_tokens = generatedSingleTokenRangeIfKind(tokens, option_index, item.end, .string) orelse return;
                if (default_tokens.?.end != item.end) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "encoding")) {
                if (encoding_tokens != null) return;
                encoding_tokens = generatedSingleTokenRangeIfKind(tokens, option_index, item.end, .string) orelse return;
                if (encoding_tokens.?.end != item.end or tokens[encoding_tokens.?.start].text.len == 0) return;
            } else if (consumeGeneratedBulkIoKeywordText(tokens, &option_index, item.end, "oids")) {
                const oids = generatedBulkIoBool(tokens, &option_index, item.end) orelse return;
                if (oids or option_index != item.end) return;
            } else return;
        }
        index = options_close + 1;
    }

    if (freeze and direction != .from) return;
    if (on_error != .stop and direction != .from) return;
    if (reject_limit_tokens != null and direction != .from) return;
    if (reject_limit_tokens != null and on_error != .ignore) return;
    if (log_verbosity != .default and direction != .from) return;
    if (log_verbosity != .default and on_error != .ignore) return;
    if (default_tokens != null and direction != .from) return;
    if ((force_quote_all or force_quote_columns.count != 0) and direction != .to) return;
    if (force_not_null_columns.count != 0 and direction != .from) return;
    if (force_null_columns.count != 0 and direction != .from) return;

    var where_tokens: ?GeneratedSqlTokenRange = null;
    if (consumeGeneratedBulkIoKeywordText(tokens, &index, end, "where")) {
        if (index >= end) return;
        where_tokens = .{ .start = index - 1, .end = end };
        index = end;
    }
    if (index != subject.end or subject.end != end) return;

    ast.bulk_table_tokens = table_name;
    ast.bulk_column_items = columns;
    columns = .{};
    ast.bulk_direction = direction;
    ast.bulk_endpoint_kind = endpoint_kind;
    ast.bulk_endpoint_tokens = endpoint_tokens;
    ast.bulk_option_items = option_items;
    option_items = .{};
    ast.bulk_format_tokens = format_tokens;
    ast.bulk_header = header;
    ast.bulk_freeze = freeze;
    ast.bulk_on_error = on_error;
    ast.bulk_reject_limit_tokens = reject_limit_tokens;
    ast.bulk_log_verbosity = log_verbosity;
    ast.bulk_force_quote_all = force_quote_all;
    ast.bulk_force_quote_column_items = force_quote_columns;
    force_quote_columns = .{};
    ast.bulk_force_not_null_column_items = force_not_null_columns;
    force_not_null_columns = .{};
    ast.bulk_force_null_column_items = force_null_columns;
    force_null_columns = .{};
    ast.bulk_delimiter_tokens = delimiter_tokens;
    ast.bulk_quote_tokens = quote_tokens;
    ast.bulk_escape_tokens = escape_tokens;
    ast.bulk_null_tokens = null_tokens;
    ast.bulk_default_tokens = default_tokens;
    ast.bulk_encoding_tokens = encoding_tokens;
    ast.bulk_where_tokens = where_tokens;
}

fn consumeGeneratedBulkIoKeywordText(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
    keyword: []const u8,
) bool {
    if (index.* >= end or !tokens[index.*].matchesKeyword(keyword)) return false;
    index.* += 1;
    return true;
}

fn generatedSingleTokenRangeIfKind(
    tokens: []const token_mod.Token,
    index: usize,
    end: usize,
    kind: token_mod.TokenKind,
) ?GeneratedSqlTokenRange {
    if (index >= end or tokens[index].kind != kind) return null;
    return .{ .start = index, .end = index + 1 };
}

fn generatedBulkIoBool(tokens: []const token_mod.Token, index: *usize, end: usize) ?bool {
    const value = generatedSingleTokenRangeIfIdentifier(tokens, index.*, end) orelse return null;
    index.* = value.end;
    if (std.ascii.eqlIgnoreCase(tokens[value.start].text, "true")) return true;
    if (std.ascii.eqlIgnoreCase(tokens[value.start].text, "false")) return false;
    return null;
}

fn generatedBulkIoPositiveIntegerRange(tokens: []const token_mod.Token, index: usize, end: usize) ?GeneratedSqlTokenRange {
    const value = generatedSingleTokenRangeIfKind(tokens, index, end, .number) orelse return null;
    if (value.end != end or std.mem.indexOfScalar(u8, tokens[value.start].text, '.') != null) return null;
    const parsed = std.fmt.parseInt(usize, tokens[value.start].text, 10) catch return null;
    return if (parsed == 0) null else value;
}

fn generatedBulkIoOneByteStringRange(tokens: []const token_mod.Token, index: usize, end: usize) ?GeneratedSqlTokenRange {
    const value = generatedSingleTokenRangeIfKind(tokens, index, end, .string) orelse return null;
    if (value.end != end or tokens[value.start].text.len != 1) return null;
    return value;
}

fn generatedBulkIoIdentifierListIsValid(tokens: []const token_mod.Token, list: GeneratedSqlListAst) bool {
    if (list.count == 0 or list.count != list.items.len or list.first_tokens == null or list.last_tokens == null) return false;
    for (list.items) |item| {
        if (item.end != item.start + 1 or item.end > tokens.len or tokens[item.start].kind != .identifier) return false;
    }
    return true;
}

fn populateGeneratedUnsupportedTriggerAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) void {
    switch (ast.kind) {
        .create_trigger => populateGeneratedUnsupportedCreateTriggerAst(tokens, end, ast),
        .drop_trigger => populateGeneratedUnsupportedDropTriggerAst(tokens, end, ast),
        else => {},
    }
}

fn populateGeneratedUnsupportedCreateTriggerAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    const trigger_name = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
    index += 1;
    if (!consumeGeneratedTriggerKeyword(tokens, &index, end, .before)) return;
    const trigger_event = consumeGeneratedTriggerEvent(tokens, &index, end) orelse return;
    if (trigger_event == .update and consumeGeneratedTriggerKeyword(tokens, &index, end, .of)) return;
    if (!consumeGeneratedTriggerKeyword(tokens, &index, end, .on)) return;
    const trigger_table = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
    index += 1;
    if (consumeGeneratedTriggerKeyword(tokens, &index, end, .@"for")) {
        if (!consumeGeneratedTriggerKeyword(tokens, &index, end, .each)) return;
        if (!consumeGeneratedTriggerKeyword(tokens, &index, end, .row)) return;
    }
    if (!consumeGeneratedTriggerKeyword(tokens, &index, end, .execute)) return;
    if (!(consumeGeneratedTriggerKeyword(tokens, &index, end, .function) or consumeGeneratedTriggerKeyword(tokens, &index, end, .procedure))) return;
    const trigger_function = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
    index += 1;
    if (index >= end or tokens[index].kind != .lparen) return;
    index += 1;
    var trigger_argument: ?GeneratedSqlTokenRange = null;
    if (index < end and tokens[index].kind == .rparen) {
        index += 1;
        if (index != end) return;
        ast.trigger_name_tokens = trigger_name;
        ast.trigger_table_tokens = trigger_table;
        ast.trigger_function_tokens = trigger_function;
        ast.trigger_event = trigger_event;
        return;
    }
    if (index >= end or (tokens[index].kind != .identifier and tokens[index].kind != .string)) return;
    trigger_argument = .{ .start = index, .end = index + 1 };
    index += 1;
    if (index >= end or tokens[index].kind != .rparen) return;
    index += 1;
    if (index != end) return;
    ast.trigger_name_tokens = trigger_name;
    ast.trigger_table_tokens = trigger_table;
    ast.trigger_function_tokens = trigger_function;
    ast.trigger_argument_tokens = trigger_argument;
    ast.trigger_event = trigger_event;
}

fn populateGeneratedUnsupportedDropTriggerAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    const trigger_if_exists = consumeGeneratedIfExists(tokens, &index, end);
    const trigger_name = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
    index += 1;
    if (!consumeGeneratedTriggerKeyword(tokens, &index, end, .on)) return;
    _ = consumeGeneratedTriggerKeyword(tokens, &index, end, .only);
    const trigger_table = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
    index += 1;
    var trigger_cascade = false;
    if (index < end and consumeGeneratedTriggerKeyword(tokens, &index, end, .cascade)) {
        trigger_cascade = true;
    } else if (index < end) {
        _ = consumeGeneratedTriggerKeyword(tokens, &index, end, .restrict);
    }
    if (index != end) return;
    ast.trigger_name_tokens = trigger_name;
    ast.trigger_table_tokens = trigger_table;
    ast.trigger_if_exists = trigger_if_exists;
    ast.trigger_cascade = trigger_cascade;
}

fn consumeGeneratedTriggerKeyword(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
    keyword: token_mod.TokenKeyword,
) bool {
    if (index.* >= end or !tokens[index.*].matchesKeywordTag(keyword)) return false;
    index.* += 1;
    return true;
}

fn consumeGeneratedTriggerEvent(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
) ?GeneratedSqlTriggerEvent {
    if (consumeGeneratedTriggerKeyword(tokens, index, end, .insert)) return .insert;
    if (consumeGeneratedTriggerKeyword(tokens, index, end, .update)) return .update;
    if (consumeGeneratedTriggerKeyword(tokens, index, end, .delete)) return .delete;
    return null;
}

fn populateGeneratedUnsupportedNotificationAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    switch (ast.kind) {
        .listen => {
            const channel = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
            index = channel.end;
            if (index != subject.end or subject.end != end) return;
            ast.notification_channel_tokens = channel;
        },
        .notify => {
            const channel = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
            index = channel.end;
            ast.notification_channel_tokens = channel;
            if (index == subject.end and subject.end == end) return;
            if (index >= end or tokens[index].kind != .comma) {
                ast.notification_channel_tokens = null;
                return;
            }
            index += 1;
            if (index >= subject.end) {
                ast.notification_channel_tokens = null;
                return;
            }
            ast.notification_payload_tokens = .{ .start = index, .end = subject.end };
        },
        .unlisten => {
            if (index < end and tokens[index].kind == .star) {
                index += 1;
                if (index != subject.end or subject.end != end) return;
                ast.notification_unlisten_all = true;
                return;
            }
            const channel = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
            index = channel.end;
            if (index != subject.end or subject.end != end) return;
            ast.notification_channel_tokens = channel;
        },
        else => {},
    }
}

fn populateGeneratedUnsupportedTableLockAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    _ = consumeGeneratedLockKeyword(tokens, &index, end, .table);

    var table_items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    defer table_items.deinit(alloc);
    while (true) {
        const table = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
        try table_items.append(alloc, table);
        index = table.end;
        if (index < end and tokens[index].kind == .comma) {
            index += 1;
            continue;
        }
        break;
    }
    if (table_items.items.len == 0) return;
    if (!consumeGeneratedLockKeyword(tokens, &index, end, .in)) return;
    const mode = consumeGeneratedTableLockMode(tokens, &index, end) orelse return;
    if (index >= end or !tokens[index].matchesKeyword("mode")) return;
    index += 1;
    if (index != subject.end or subject.end != end) return;

    const owned = try table_items.toOwnedSlice(alloc);
    ast.table_lock_table_items = .{
        .first_tokens = owned[0],
        .last_tokens = owned[owned.len - 1],
        .items = owned,
        .count = owned.len,
    };
    ast.table_lock_mode = mode;
}

fn consumeGeneratedTableLockMode(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
) ?GeneratedSqlTableLockMode {
    if (consumeGeneratedLockKeyword(tokens, index, end, .access)) {
        if (consumeGeneratedLockKeyword(tokens, index, end, .share)) return .access_share;
        if (index.* < end and tokens[index.*].matchesKeyword("exclusive")) {
            index.* += 1;
            return .access_exclusive;
        }
        return null;
    }
    if (consumeGeneratedLockKeyword(tokens, index, end, .row)) {
        if (consumeGeneratedLockKeyword(tokens, index, end, .share)) return .row_share;
        if (index.* < end and tokens[index.*].matchesKeyword("exclusive")) {
            index.* += 1;
            return .row_exclusive;
        }
        return null;
    }
    if (consumeGeneratedLockKeyword(tokens, index, end, .share)) {
        if (consumeGeneratedLockKeyword(tokens, index, end, .update)) {
            if (index.* >= end or !tokens[index.*].matchesKeyword("exclusive")) return null;
            index.* += 1;
            return .share_update_exclusive;
        }
        if (consumeGeneratedLockKeyword(tokens, index, end, .row)) {
            if (index.* >= end or !tokens[index.*].matchesKeyword("exclusive")) return null;
            index.* += 1;
            return .share_row_exclusive;
        }
        return .share;
    }
    if (index.* < end and tokens[index.*].matchesKeyword("exclusive")) {
        index.* += 1;
        return .exclusive;
    }
    return null;
}

fn consumeGeneratedLockKeyword(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
    keyword: token_mod.TokenKeyword,
) bool {
    if (index.* >= end or !tokens[index.*].matchesKeywordTag(keyword)) return false;
    index.* += 1;
    return true;
}

fn populateGeneratedUnsupportedMaintenanceAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    switch (ast.kind) {
        .vacuum => populateGeneratedUnsupportedVacuumAst(tokens, end, ast),
        .analyze => try populateGeneratedUnsupportedAnalyzeAst(alloc, tokens, end, ast),
        .reindex => populateGeneratedUnsupportedReindexAst(tokens, end, ast),
        .cluster => populateGeneratedUnsupportedClusterAst(tokens, end, ast),
        else => {},
    }
}

fn populateGeneratedUnsupportedVacuumAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    var full = false;
    var freeze = false;
    var verbose = false;
    var analyze = false;
    if (index < end and tokens[index].kind == .lparen) {
        index += 1;
        while (true) {
            if (!consumeGeneratedVacuumOption(tokens, &index, end, &full, &freeze, &verbose, &analyze)) return;
            if (index < end and tokens[index].kind == .comma) {
                index += 1;
                continue;
            }
            break;
        }
        if (index >= end or tokens[index].kind != .rparen) return;
        index += 1;
    } else {
        while (consumeGeneratedVacuumOption(tokens, &index, end, &full, &freeze, &verbose, &analyze)) {}
    }
    const table_name = generatedQualifiedNameRange(tokens, index, end) orelse return;
    index = table_name.end;
    if (index != subject.end or subject.end != end) return;
    ast.maintenance_name_tokens = table_name;
    ast.maintenance_vacuum_full = full;
    ast.maintenance_vacuum_freeze = freeze;
    ast.maintenance_verbose = verbose;
    ast.maintenance_vacuum_analyze = analyze;
}

fn consumeGeneratedVacuumOption(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
    full: *bool,
    freeze: *bool,
    verbose: *bool,
    analyze: *bool,
) bool {
    if (consumeGeneratedMaintenanceKeyword(tokens, index, end, .full)) {
        full.* = true;
        return true;
    }
    if (consumeGeneratedMaintenanceKeyword(tokens, index, end, .freeze)) {
        freeze.* = true;
        return true;
    }
    if (consumeGeneratedMaintenanceKeyword(tokens, index, end, .verbose)) {
        verbose.* = true;
        return true;
    }
    if (consumeGeneratedMaintenanceKeyword(tokens, index, end, .analyze)) {
        analyze.* = true;
        return true;
    }
    return false;
}

fn populateGeneratedUnsupportedAnalyzeAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    const verbose = consumeGeneratedMaintenanceKeyword(tokens, &index, end, .verbose);
    const table_name = generatedQualifiedNameRange(tokens, index, end) orelse return;
    index = table_name.end;
    var column_items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    defer column_items.deinit(alloc);
    if (index < end and tokens[index].kind == .lparen) {
        index += 1;
        while (true) {
            const column = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return;
            try column_items.append(alloc, column);
            index = column.end;
            if (index < end and tokens[index].kind == .comma) {
                index += 1;
                continue;
            }
            break;
        }
        if (index >= end or tokens[index].kind != .rparen) return;
        index += 1;
    }
    if (index != subject.end or subject.end != end) return;
    ast.maintenance_name_tokens = table_name;
    ast.maintenance_verbose = verbose;
    if (column_items.items.len > 0) {
        const owned = try column_items.toOwnedSlice(alloc);
        ast.maintenance_column_items = .{
            .first_tokens = owned[0],
            .last_tokens = owned[owned.len - 1],
            .items = owned,
            .count = owned.len,
        };
    }
}

fn populateGeneratedUnsupportedReindexAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    const target = consumeGeneratedReindexTarget(tokens, &index, end) orelse return;
    const concurrently = if (index < end and tokens[index].matchesKeyword("concurrently")) blk: {
        index += 1;
        break :blk true;
    } else false;
    const name = generatedQualifiedNameRange(tokens, index, end) orelse return;
    index = name.end;
    if (index != subject.end or subject.end != end) return;
    ast.maintenance_reindex_target = target;
    ast.maintenance_name_tokens = name;
    ast.maintenance_concurrently = concurrently;
}

fn consumeGeneratedReindexTarget(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
) ?GeneratedSqlReindexTarget {
    if (consumeGeneratedMaintenanceKeyword(tokens, index, end, .index)) return .index;
    if (consumeGeneratedMaintenanceKeyword(tokens, index, end, .table)) return .table;
    if (consumeGeneratedMaintenanceKeyword(tokens, index, end, .schema)) return .schema;
    if (consumeGeneratedMaintenanceKeyword(tokens, index, end, .database)) return .database;
    if (consumeGeneratedMaintenanceKeyword(tokens, index, end, .system)) return .system;
    return null;
}

fn populateGeneratedUnsupportedClusterAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    const verbose = consumeGeneratedMaintenanceKeyword(tokens, &index, end, .verbose);
    const table_name = generatedQualifiedNameRange(tokens, index, end) orelse return;
    index = table_name.end;
    var index_name: ?GeneratedSqlTokenRange = null;
    if (consumeGeneratedMaintenanceKeyword(tokens, &index, end, .using)) {
        index_name = generatedQualifiedNameRange(tokens, index, end) orelse return;
        index = index_name.?.end;
    }
    if (index != subject.end or subject.end != end) return;
    ast.maintenance_name_tokens = table_name;
    ast.maintenance_secondary_name_tokens = index_name;
    ast.maintenance_verbose = verbose;
}

fn consumeGeneratedMaintenanceKeyword(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
    keyword: token_mod.TokenKeyword,
) bool {
    if (index.* >= end or !tokens[index.*].matchesKeywordTag(keyword)) return false;
    index.* += 1;
    return true;
}

fn populateGeneratedUnsupportedGraphQueryAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    const subject = ast.subject_tokens orelse return;
    if (subject.start != 1 or subject.end != end) return;
    const return_index = findTopLevelKeyword(tokens, subject.start, subject.end, .@"return") orelse return;
    if (return_index + 1 >= subject.end) return;

    const where_index = findTopLevelKeyword(tokens, subject.start, return_index, .where);
    const source_tail_end = where_index orelse return_index;
    const source_with_index = findTopLevelKeyword(tokens, subject.start, source_tail_end, .with);
    const path_end = source_with_index orelse source_tail_end;
    const path_metadata = generatedGraphPathMetadata(tokens, .{ .start = subject.start, .end = path_end }) orelse return;

    ast.graph_path_tokens = .{ .start = subject.start, .end = path_end };
    ast.graph_path_kind = path_metadata.kind;
    ast.graph_source_alias_tokens = path_metadata.source_alias_tokens;
    ast.graph_relationship_tokens = path_metadata.relationship_tokens;
    ast.graph_relationship_label_tokens = path_metadata.relationship_label_tokens;
    ast.graph_target_alias_tokens = path_metadata.target_alias_tokens;
    if (source_with_index) |with| {
        const source_metadata = generatedGraphSourceBindingMetadata(tokens, .{ .start = with, .end = source_tail_end }) orelse return;
        ast.graph_source_binding_tokens = .{ .start = with, .end = source_tail_end };
        ast.graph_source_graph_tokens = source_metadata.graph_tokens;
        ast.graph_source_index_tokens = source_metadata.index_tokens;
        ast.graph_source_table_tokens = source_metadata.table_tokens;
        ast.graph_source_start_tokens = source_metadata.start_tokens;
    }
    if (where_index) |where| {
        if (where < path_end or where + 1 >= return_index) return;
        ast.graph_where_tokens = .{ .start = where, .end = return_index };
        try buildGeneratedExpressionAstInto(alloc, tokens, .{ .start = where + 1, .end = return_index }, &ast.graph_where_expression);
    }
    ast.graph_return_tokens = .{ .start = return_index, .end = return_index + 1 };
    ast.graph_return_tail_tokens = .{ .start = return_index + 1, .end = subject.end };
    try populateGeneratedUnsupportedGraphReturnTailAst(alloc, tokens, ast.graph_return_tail_tokens.?, path_metadata, ast);
}

fn populateGeneratedUnsupportedGraphReturnTailAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    tail: GeneratedSqlTokenRange,
    path_metadata: GeneratedGraphPathMetadata,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    const order_index = findTopLevelKeyword(tokens, tail.start, tail.end, .order);
    const limit_index = findTopLevelKeyword(tokens, tail.start, tail.end, .limit);
    const offset_index = findTopLevelKeyword(tokens, tail.start, tail.end, .offset);
    const projection_end = firstOptionalIndex(&[_]?usize{ order_index, limit_index, offset_index }) orelse tail.end;
    if (tail.start < projection_end) {
        const projection_tokens = GeneratedSqlTokenRange{ .start = tail.start, .end = projection_end };
        ast.graph_return_projection_tokens = projection_tokens;
        ast.graph_return_projection_items = try buildTopLevelListAst(alloc, tokens, projection_tokens, .{});
        ast.graph_return_path_alias_projection_roles = try buildGeneratedGraphReturnPathAliasProjectionRolesAlloc(alloc, tokens, ast.graph_return_projection_items, path_metadata);
        ast.graph_return_path_alias_projection_count = generatedGraphReturnPathAliasProjectionCount(ast.graph_return_path_alias_projection_roles);
    }
    if (order_index) |idx| {
        const order_start = if (idx + 1 < tail.end and tokens[idx + 1].matchesKeywordTag(.by)) idx + 2 else idx + 1;
        const order_end = firstOptionalIndex(&[_]?usize{ limit_index, offset_index }) orelse tail.end;
        if (order_start < order_end) {
            const order_tokens = GeneratedSqlTokenRange{ .start = order_start, .end = order_end };
            ast.graph_order_tokens = order_tokens;
            ast.graph_order_items = try buildTopLevelListAst(alloc, tokens, order_tokens, .{ .order_modifiers = true });
        }
    }
    if (limit_index) |idx| {
        const limit_end = firstOptionalIndex(&[_]?usize{offset_index}) orelse tail.end;
        if (idx + 1 < limit_end) {
            const limit_tokens = GeneratedSqlTokenRange{ .start = idx + 1, .end = limit_end };
            ast.graph_limit_tokens = limit_tokens;
            try buildGeneratedExpressionAstInto(alloc, tokens, limit_tokens, &ast.graph_limit_expression);
        }
    }
    if (offset_index) |idx| {
        if (idx + 1 < tail.end) {
            const offset_tokens = GeneratedSqlTokenRange{ .start = idx + 1, .end = tail.end };
            ast.graph_offset_tokens = offset_tokens;
            try buildGeneratedExpressionAstInto(alloc, tokens, offset_tokens, &ast.graph_offset_expression);
        }
    }
}

fn generatedGraphReturnPathAliasProjectionCount(
    roles: []const ?GeneratedSqlGraphPathAliasRole,
) usize {
    var count: usize = 0;
    for (roles) |role| {
        if (role != null) count += 1;
    }
    return count;
}

fn buildGeneratedGraphReturnPathAliasProjectionRolesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    projection_items: GeneratedSqlListAst,
    path_metadata: GeneratedGraphPathMetadata,
) ![]?GeneratedSqlGraphPathAliasRole {
    if (projection_items.count == 0) return &.{};
    const roles = try alloc.alloc(?GeneratedSqlGraphPathAliasRole, projection_items.count);
    errdefer alloc.free(roles);
    for (projection_items.expression_items, 0..) |expression, index| {
        roles[index] = generatedGraphExpressionPathAliasRole(tokens, expression, path_metadata);
    }
    return roles;
}

fn generatedGraphExpressionPathAliasRole(
    tokens: []const token_mod.Token,
    expression: GeneratedSqlTokenRange,
    path_metadata: GeneratedGraphPathMetadata,
) ?GeneratedSqlGraphPathAliasRole {
    if (expression.end != expression.start + 1 or expression.end > tokens.len) return null;
    if (generatedGraphTokenTextMatchesAlias(tokens, expression.start, path_metadata.source_alias_tokens)) return .source;
    if (path_metadata.target_alias_tokens) |target| {
        if (generatedGraphTokenTextMatchesAlias(tokens, expression.start, target)) return .target;
    }
    return null;
}

fn generatedGraphTokenTextMatchesAlias(
    tokens: []const token_mod.Token,
    token_index: usize,
    alias: GeneratedSqlTokenRange,
) bool {
    if (alias.end != alias.start + 1 or alias.end > tokens.len) return false;
    if (tokens[token_index].kind != .identifier or tokens[alias.start].kind != .identifier) return false;
    return std.mem.eql(u8, tokens[token_index].text, tokens[alias.start].text);
}

const GeneratedGraphPathMetadata = struct {
    kind: GeneratedSqlGraphPathKind,
    source_alias_tokens: GeneratedSqlTokenRange,
    relationship_tokens: ?GeneratedSqlTokenRange = null,
    relationship_label_tokens: ?GeneratedSqlTokenRange = null,
    target_alias_tokens: ?GeneratedSqlTokenRange = null,
};

const GeneratedGraphSourceBindingMetadata = struct {
    graph_tokens: GeneratedSqlTokenRange,
    index_tokens: GeneratedSqlTokenRange,
    table_tokens: GeneratedSqlTokenRange,
    start_tokens: GeneratedSqlTokenRange,
};

const GeneratedGraphRelationshipMetadata = struct {
    label_tokens: ?GeneratedSqlTokenRange = null,
};

fn generatedGraphPathTokensAreValid(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) bool {
    return generatedGraphPathMetadata(tokens, range) != null;
}

fn generatedGraphSourceBindingMetadata(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedGraphSourceBindingMetadata {
    if (range.end != range.start + 7 or range.end > tokens.len) return null;
    if (!tokens[range.start].matchesKeywordTag(.with)) return null;
    if (!tokens[range.start + 1].matchesKeywordTag(.graph)) return null;
    if (!generatedGraphBindingValueToken(tokens[range.start + 2])) return null;
    if (!tokens[range.start + 3].matchesKeywordTag(.on)) return null;
    if (!generatedGraphBindingValueToken(tokens[range.start + 4])) return null;
    if (!tokens[range.start + 5].matchesKeywordTag(.start)) return null;
    if (!generatedGraphBindingValueToken(tokens[range.start + 6])) return null;
    return .{
        .graph_tokens = .{ .start = range.start + 1, .end = range.start + 2 },
        .index_tokens = .{ .start = range.start + 2, .end = range.start + 3 },
        .table_tokens = .{ .start = range.start + 4, .end = range.start + 5 },
        .start_tokens = .{ .start = range.start + 6, .end = range.start + 7 },
    };
}

fn generatedGraphBindingValueToken(token: token_mod.Token) bool {
    return token.kind == .identifier or token.kind == .string;
}

fn generatedGraphPathMetadata(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedGraphPathMetadata {
    var index = range.start;
    const source_alias = consumeGeneratedGraphNode(tokens, &index, range.end) orelse return null;
    if (index == range.end) {
        return .{
            .kind = .node,
            .source_alias_tokens = source_alias,
        };
    }
    const relationship_start = index;
    var direction: GeneratedSqlGraphPathKind = undefined;
    var label: ?GeneratedSqlTokenRange = null;
    if (consumeGeneratedGraphOutRelationship(tokens, &index, range.end)) |relationship| {
        direction = .outgoing;
        label = relationship.label_tokens;
    } else if (consumeGeneratedGraphInRelationship(tokens, &index, range.end)) |relationship| {
        direction = .incoming;
        label = relationship.label_tokens;
    } else {
        return null;
    }
    const target_alias = consumeGeneratedGraphNode(tokens, &index, range.end) orelse return null;
    if (index != range.end) return null;
    return .{
        .kind = direction,
        .source_alias_tokens = source_alias,
        .relationship_tokens = .{ .start = relationship_start, .end = target_alias.start - 1 },
        .relationship_label_tokens = label,
        .target_alias_tokens = target_alias,
    };
}

fn consumeGeneratedGraphNode(tokens: []const token_mod.Token, index: *usize, end: usize) ?GeneratedSqlTokenRange {
    if (index.* + 2 >= end) return null;
    if (tokens[index.*].kind != .lparen) return null;
    if (tokens[index.* + 1].kind != .identifier) return null;
    if (tokens[index.* + 2].kind != .rparen) return null;
    const alias = GeneratedSqlTokenRange{ .start = index.* + 1, .end = index.* + 2 };
    index.* += 3;
    return alias;
}

fn consumeGeneratedGraphOutRelationship(tokens: []const token_mod.Token, index: *usize, end: usize) ?GeneratedGraphRelationshipMetadata {
    if (index.* + 2 >= end) return null;
    if (tokens[index.*].kind != .minus or tokens[index.* + 1].kind != .lbracket) return null;
    index.* += 2;
    const label = consumeGeneratedGraphRelationshipLabelOpt(tokens, index, end) orelse return null;
    if (index.* + 1 >= end) return null;
    if (tokens[index.*].kind != .rbracket or tokens[index.* + 1].kind != .arrow_json) return null;
    index.* += 2;
    return .{ .label_tokens = if (label.start < label.end) label else null };
}

fn consumeGeneratedGraphInRelationship(tokens: []const token_mod.Token, index: *usize, end: usize) ?GeneratedGraphRelationshipMetadata {
    if (index.* + 3 >= end) return null;
    if (tokens[index.*].kind != .lt or tokens[index.* + 1].kind != .minus or tokens[index.* + 2].kind != .lbracket) return null;
    index.* += 3;
    const label = consumeGeneratedGraphRelationshipLabelOpt(tokens, index, end) orelse return null;
    if (index.* + 1 >= end) return null;
    if (tokens[index.*].kind != .rbracket or tokens[index.* + 1].kind != .minus) return null;
    index.* += 2;
    return .{ .label_tokens = if (label.start < label.end) label else null };
}

fn consumeGeneratedGraphRelationshipLabelOpt(tokens: []const token_mod.Token, index: *usize, end: usize) ?GeneratedSqlTokenRange {
    if (index.* < end and tokens[index.*].kind == .colon) {
        if (index.* + 1 >= end or tokens[index.* + 1].kind != .identifier) return null;
        const label = GeneratedSqlTokenRange{ .start = index.* + 1, .end = index.* + 2 };
        index.* += 2;
        return label;
    }
    return .{ .start = index.*, .end = index.* };
}

fn generatedUnsupportedAlterTableOperationKind(kind: GeneratedSqlUnsupportedKind) bool {
    return switch (kind) {
        .alter_table_access_method,
        .alter_table_cluster,
        .alter_table_column_statistics,
        .alter_table_column_storage,
        .alter_table_inheritance,
        .alter_table_owner,
        .alter_table_persistence,
        .alter_table_replica_identity,
        .alter_table_set_schema,
        .alter_table_storage_parameters,
        .alter_table_tablespace,
        .alter_table_trigger_state,
        .alter_table_exclusion_constraint,
        => true,
        else => false,
    };
}

fn populateGeneratedUnsupportedAlterTableAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) void {
    if (end <= 3 or !tokens[0].matchesKeywordTag(.alter) or !tokens[1].matchesKeywordTag(.table)) return;
    var index: usize = 2;
    _ = consumeGeneratedIfExists(tokens, &index, end);
    if (index < end and tokens[index].matchesKeywordTag(.only)) index += 1;
    const table_range = generatedQualifiedNameRange(tokens, index, end) orelse return;
    if (table_range.end >= end) return;
    ast.alter_table_name_tokens = table_range;
    ast.alter_table_operation_tokens = .{ .start = table_range.end, .end = end };
    ast.alter_table_operation_kind = ast.kind;
    ast.alter_table_operation_subject_tokens = generatedUnsupportedAlterTableOperationSubjectRange(tokens, ast.alter_table_operation_tokens.?, ast.kind);
}

fn generatedUnsupportedAlterTableOperationSubjectRange(
    tokens: []const token_mod.Token,
    operation: GeneratedSqlTokenRange,
    kind: GeneratedSqlUnsupportedKind,
) ?GeneratedSqlTokenRange {
    const start = operation.start;
    const end = operation.end;
    if (end > tokens.len or start >= end) return null;
    const subject_index: ?usize = switch (kind) {
        .alter_table_access_method,
        .alter_table_owner,
        .alter_table_set_schema,
        .alter_table_tablespace,
        => if (end == start + 3 or end == start + 4) end - 1 else null,
        .alter_table_cluster => if (end == start + 3 and tokens[start].matchesKeywordTag(.cluster)) start + 2 else null,
        .alter_table_inheritance => if (tokens[start].matchesKeyword("inherit") and end == start + 2)
            start + 1
        else if (tokens[start].matchesKeywordTag(.no) and end == start + 3)
            start + 2
        else
            null,
        else => null,
    };
    const index = subject_index orelse return null;
    if (index >= end or tokens[index].kind != .identifier) return null;
    return .{ .start = index, .end = index + 1 };
}

fn populateGeneratedUnsupportedAlterRoutineAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    if (end <= 3 or !tokens[0].matchesKeywordTag(.alter)) return;
    const expected: token_mod.TokenKeyword = switch (ast.kind) {
        .alter_function => .function,
        .alter_procedure => .procedure,
        else => return,
    };
    if (!tokens[1].matchesKeywordTag(expected)) return;
    const routine_range = generatedQualifiedNameRange(tokens, 2, end) orelse return;
    if (routine_range.end >= end or tokens[routine_range.end].kind != .lparen) return;
    const signature_close = findMatchingParen(tokens, routine_range.end, end) orelse return;
    if (signature_close + 1 >= end) return;
    ast.routine_name_tokens = routine_range;
    ast.routine_operation_tokens = .{ .start = signature_close + 1, .end = end };
    ast.routine_metadata = try buildGeneratedRoutineAstPtr(
        alloc,
        tokens,
        .{ .start = routine_range.end + 1, .end = signature_close },
        signature_close + 1,
        signature_close + 1,
    );
}

fn populateGeneratedUnsupportedProcedureCallAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) void {
    const subject = ast.subject_tokens orelse return;
    var index = subject.start;
    const routine_range = generatedQualifiedNameRange(tokens, index, end) orelse return;
    index = routine_range.end;
    if (index >= end or tokens[index].kind != .lparen) return;
    index += 1;
    if (index >= end or tokens[index].kind != .rparen) return;
    index += 1;
    if (index != subject.end or subject.end != end) return;
    ast.routine_name_tokens = routine_range;
}

fn generatedUnsupportedSubjectStart(tokens: []const token_mod.Token, kind: GeneratedSqlUnsupportedKind, end: usize) ?usize {
    const start: usize = switch (kind) {
        .create_trigger => if (end > 3 and
            tokens[1].matchesKeywordTag(.@"or") and
            tokens[2].matchesKeywordTag(.replace) and
            tokens[3].matchesKeywordTag(.trigger))
            4
        else if (end > 2 and
            tokens[1].matchesKeywordTag(.constraint) and
            tokens[2].matchesKeywordTag(.trigger))
            3
        else
            2,
        .drop_trigger => 2,
        else => 1,
    };
    return if (end > start) start else null;
}

fn populateGeneratedExplainUnsupportedAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    if (end <= 1 or end > tokens.len) return;
    var index: usize = 1;
    if (tokens[index].matchesKeywordTag(.analyze)) {
        ast.explain_analyze = true;
        index += 1;
    } else if (tokens[index].kind == .lparen) {
        const close = findMatchingParen(tokens, index, end) orelse {
            ast.explain_options_valid = false;
            return;
        };
        ast.explain_options_tokens = .{ .start = index, .end = close + 1 };
        parseGeneratedExplainOptionList(tokens, index + 1, close, ast) catch {
            ast.explain_options_valid = false;
        };
        index = close + 1;
    }
    if (index < end) {
        const subject = GeneratedSqlTokenRange{ .start = index, .end = end };
        ast.subject_tokens = subject;
        if (tokens[index].matchesKeywordTag(.select) or tokens[index].matchesKeywordTag(.with)) {
            if (try buildGeneratedDmlAstForRangeAlloc(alloc, tokens, subject)) |dml| {
                ast.explain_subject_dml_ast = dml;
            } else {
                ast.explain_subject_read_ast = try buildGeneratedReadAstForRangeAlloc(alloc, tokens, subject);
            }
        } else if (try buildGeneratedDmlAstForRangeAlloc(alloc, tokens, subject)) |dml| {
            ast.explain_subject_dml_ast = dml;
        }
    }
}

fn parseGeneratedExplainOptionList(
    tokens: []const token_mod.Token,
    start: usize,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    var index = start;
    while (index < end) {
        try parseGeneratedExplainOption(tokens, &index, end, ast);
        if (index == end) return;
        if (tokens[index].kind != .comma) return error.UnsupportedSqlShape;
        index += 1;
        if (index >= end) return error.UnsupportedSqlShape;
    }
    if (start == end) return error.UnsupportedSqlShape;
}

fn parseGeneratedExplainOption(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
    ast: *GeneratedSqlUnsupportedAst,
) !void {
    if (index.* >= end) return error.UnsupportedSqlShape;
    const name = tokens[index.*];
    index.* += 1;
    if (name.matchesKeywordTag(.format)) {
        if (index.* >= end) return error.UnsupportedSqlShape;
        if (tokens[index.*].matchesKeywordTag(.json)) {
            ast.explain_format = .json;
        } else if (tokens[index.*].matchesKeywordTag(.text)) {
            ast.explain_format = .text;
        } else {
            return error.UnsupportedSqlShape;
        }
        index.* += 1;
        return;
    }

    if (name.matchesKeywordTag(.analyze)) {
        ast.explain_analyze = parseGeneratedExplainOptionalBool(tokens, index, end, true);
    } else if (name.matchesKeywordTag(.verbose)) {
        ast.explain_verbose = parseGeneratedExplainOptionalBool(tokens, index, end, true);
    } else if (name.matchesKeywordTag(.costs)) {
        ast.explain_costs = parseGeneratedExplainOptionalBool(tokens, index, end, true);
    } else if (name.matchesKeywordTag(.buffers)) {
        ast.explain_buffers = parseGeneratedExplainOptionalBool(tokens, index, end, true);
    } else if (name.matchesKeywordTag(.timing)) {
        ast.explain_timing = parseGeneratedExplainOptionalBool(tokens, index, end, true);
    } else if (name.matchesKeywordTag(.summary)) {
        ast.explain_summary = parseGeneratedExplainOptionalBool(tokens, index, end, true);
    } else if (name.matchesKeywordTag(.settings)) {
        ast.explain_settings = parseGeneratedExplainOptionalBool(tokens, index, end, true);
    } else if (name.matchesKeywordTag(.wal)) {
        ast.explain_wal = parseGeneratedExplainOptionalBool(tokens, index, end, true);
    } else {
        return error.UnsupportedSqlShape;
    }
}

fn parseGeneratedExplainOptionalBool(
    tokens: []const token_mod.Token,
    index: *usize,
    end: usize,
    default_value: bool,
) bool {
    const before = index.*;
    if (index.* < end and
        (tokens[index.*].matchesKeywordTag(.true) or
            tokens[index.*].matchesKeywordTag(.on) or
            tokens[index.*].matchesKeywordTag(.yes)))
    {
        index.* += 1;
        return true;
    }
    index.* = before;
    if (index.* < end and
        (tokens[index.*].matchesKeywordTag(.false) or
            tokens[index.*].matchesKeywordTag(.off) or
            tokens[index.*].matchesKeywordTag(.no)))
    {
        index.* += 1;
        return false;
    }
    index.* = before;
    return default_value;
}

fn buildGeneratedAst(alloc: std.mem.Allocator, tokens: []const token_mod.Token, statement: GeneratedSqlStatement) anyerror!?GeneratedSqlAst {
    const end = statementTokenEnd(tokens);
    if (end == 0) return null;
    const statement_span = sourceSpanForTokenRange(tokens, .{ .start = 0, .end = end }) orelse return null;
    const command_start = generatedCommandStartIndex(tokens, statement) orelse 0;
    const command_span = tokens[command_start].sourceSpan();
    return switch (statement) {
        .session => |kind| .{ .session = buildSessionAst(tokens, end, kind, statement_span, command_span) },
        .transaction => |kind| .{ .transaction = try buildTransactionAstAlloc(alloc, tokens, end, kind, statement_span, command_span) },
        .prepared => |kind| .{ .prepared = try buildPreparedAstAlloc(alloc, tokens, end, kind, statement_span, command_span) },
        .prepared_transaction => |kind| .{ .prepared_transaction = buildPreparedTransactionAst(end, kind, statement_span, command_span) },
        .ddl => |kind| .{ .ddl = try buildDdlAst(alloc, tokens, end, kind, statement_span, command_span) },
        .dml => |kind| .{ .dml = try buildDmlAst(alloc, tokens, command_start, end, kind, statement_span, command_span) },
        .read => |kind| {
            const read_ast = try alloc.create(GeneratedSqlReadAst);
            errdefer alloc.destroy(read_ast);
            try buildReadAstInPlace(alloc, tokens, end, kind, statement_span, command_span, read_ast);
            return .{ .read = read_ast };
        },
        .extension_index => |kind| .{ .extension_index = try buildDdlAst(alloc, tokens, end, ddlKindFromExtensionIndexKind(kind), statement_span, command_span) },
        .graph => |kind| .{ .graph = buildGraphAst(tokens, end, kind, statement_span, command_span) },
        .cursor => |kind| .{ .cursor = try buildCursorAstAlloc(alloc, tokens, end, kind, statement_span, command_span) },
        .unsupported => |kind| .{ .unsupported = try buildUnsupportedAst(alloc, tokens, end, kind, statement_span, command_span) },
        else => null,
    };
}

fn buildTransactionAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    kind: GeneratedSqlTransactionKind,
    statement_span: token_mod.SourceSpan,
    command_span: token_mod.SourceSpan,
) !GeneratedSqlTransactionAst {
    var ast = GeneratedSqlTransactionAst{
        .kind = kind,
        .statement_span = statement_span,
        .command_span = command_span,
    };
    errdefer ast.deinit(alloc);
    switch (kind) {
        .set_transaction => ast.mode_tokens = if (end > 1) .{ .start = 1, .end = end } else null,
        .constraint_mode => {
            ast.mode_tokens = if (end > 1) .{ .start = 1, .end = end } else null;
            try buildGeneratedConstraintModeMetadataAlloc(alloc, tokens, end, &ast);
        },
        .start_transaction => {
            if (end == 2) {
                ast.boundary_tail_tokens = .{ .start = 1, .end = 2 };
            } else if (end > 2) {
                ast.mode_tokens = .{ .start = 1, .end = end };
            }
        },
        .begin => {
            if (generatedBeginHasModeTail(tokens, end)) {
                ast.mode_tokens = .{ .start = 1, .end = end };
            } else if (end > 1) {
                ast.boundary_tail_tokens = .{ .start = 1, .end = end };
            }
        },
        .commit, .rollback => {
            if (end > 1) ast.boundary_tail_tokens = .{ .start = 1, .end = end };
        },
        .savepoint => {
            if (end > 1) ast.name_tokens = .{ .start = 1, .end = end };
        },
        .release_savepoint => {
            ast.name_tokens = generatedSavepointNameRange(tokens, end, 1);
        },
        .rollback_to_savepoint => {
            ast.name_tokens = generatedSavepointNameRange(tokens, end, 2);
        },
    }
    return ast;
}

fn generatedSavepointNameRange(tokens: []const token_mod.Token, end: usize, start: usize) ?GeneratedSqlTokenRange {
    if (start >= end or end > tokens.len) return null;
    const name_start = if (tokens[start].matchesKeywordTag(.savepoint)) start + 1 else start;
    return if (name_start < end) .{ .start = name_start, .end = end } else null;
}

fn buildCursorAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    kind: GeneratedSqlCursorKind,
    statement_span: token_mod.SourceSpan,
    command_span: token_mod.SourceSpan,
) !GeneratedSqlCursorAst {
    var ast = GeneratedSqlCursorAst{
        .kind = kind,
        .statement_span = statement_span,
        .command_span = command_span,
        .tail_tokens = if (end > 1) .{ .start = 1, .end = end } else null,
    };
    errdefer ast.deinit(alloc);
    if (kind == .declare) {
        const metadata = generatedDeclareCursorMetadata(tokens, end) orelse return ast;
        ast.portal_name_tokens = metadata.portal_name;
        ast.scroll_mode = metadata.scroll_mode;
        ast.binary = metadata.binary;
        ast.hold = metadata.hold;
        ast.subject_tokens = metadata.subject;
        ast.subject_ast = try buildPreparedInnerAstAlloc(alloc, tokens[metadata.subject.start..metadata.subject.end]);
    } else if (kind == .fetch or kind == .move) {
        const metadata = generatedFetchCursorMetadata(tokens, end) orelse return ast;
        ast.portal_name_tokens = metadata.portal_name;
        ast.fetch_direction = metadata.direction;
        ast.fetch_count = metadata.count;
    } else if (kind == .close) {
        const metadata = generatedCloseCursorMetadata(tokens, end) orelse return ast;
        ast.portal_name_tokens = metadata.portal_name;
        ast.close_all = metadata.all;
    }
    return ast;
}

const GeneratedDeclareCursorMetadata = struct {
    portal_name: GeneratedSqlTokenRange,
    scroll_mode: GeneratedSqlCursorScrollMode = .default,
    binary: bool = false,
    hold: bool = false,
    subject: GeneratedSqlTokenRange,
};

fn generatedDeclareCursorMetadata(tokens: []const token_mod.Token, end: usize) ?GeneratedDeclareCursorMetadata {
    if (end < 5 or !tokens[0].matchesKeywordTag(.declare)) return null;
    var index: usize = 1;
    if (index >= end or tokens[index].kind != .identifier) return null;
    const portal_name = GeneratedSqlTokenRange{ .start = index, .end = index + 1 };
    index += 1;
    var scroll_mode: GeneratedSqlCursorScrollMode = .default;
    var binary = false;
    while (index < end) {
        if (tokens[index].matchesKeyword("binary")) {
            binary = true;
            index += 1;
        } else if (tokens[index].matchesKeyword("scroll")) {
            scroll_mode = .scroll;
            index += 1;
        } else if (index + 1 < end and tokens[index].matchesKeyword("no") and tokens[index + 1].matchesKeyword("scroll")) {
            scroll_mode = .no_scroll;
            index += 2;
        } else {
            break;
        }
    }
    if (index >= end or !tokens[index].matchesKeyword("cursor")) return null;
    index += 1;
    var hold = false;
    if (index + 1 < end and (tokens[index].matchesKeyword("with") or tokens[index].matchesKeyword("without"))) {
        if (!tokens[index + 1].matchesKeyword("hold")) return null;
        hold = tokens[index].matchesKeyword("with");
        index += 2;
    }
    if (index >= end or !tokens[index].matchesKeyword("for")) return null;
    index += 1;
    if (index >= end) return null;
    return .{
        .portal_name = portal_name,
        .scroll_mode = scroll_mode,
        .binary = binary,
        .hold = hold,
        .subject = .{ .start = index, .end = end },
    };
}

const GeneratedFetchCursorMetadata = struct {
    portal_name: GeneratedSqlTokenRange,
    direction: GeneratedSqlCursorFetchDirection = .next,
    count: ?i64 = null,
};

fn generatedFetchCursorMetadata(tokens: []const token_mod.Token, end: usize) ?GeneratedFetchCursorMetadata {
    if (end <= 1 or end > tokens.len) return null;
    var index: usize = 1;
    var direction: GeneratedSqlCursorFetchDirection = .next;
    var count: ?i64 = null;
    if (tokens[index].matchesKeyword("next")) {
        direction = .next;
        index += 1;
    } else if (tokens[index].matchesKeyword("prior")) {
        direction = .prior;
        index += 1;
    } else if (tokens[index].matchesKeyword("first")) {
        direction = .first;
        index += 1;
    } else if (tokens[index].matchesKeyword("last")) {
        direction = .last;
        index += 1;
    } else if (tokens[index].matchesKeyword("all")) {
        direction = .all;
        index += 1;
    } else if (tokens[index].matchesKeyword("forward")) {
        direction = .forward;
        index += 1;
        count = generatedOptionalCursorFetchCount(tokens, &index, end) orelse return null;
    } else if (tokens[index].matchesKeyword("backward")) {
        direction = .backward;
        index += 1;
        count = generatedOptionalCursorFetchCount(tokens, &index, end) orelse return null;
    } else if (tokens[index].matchesKeyword("absolute")) {
        direction = .absolute;
        index += 1;
        count = generatedCursorFetchCount(tokens, &index, end) orelse return null;
    } else if (tokens[index].matchesKeyword("relative")) {
        direction = .relative;
        index += 1;
        count = generatedCursorFetchCount(tokens, &index, end) orelse return null;
    } else if (generatedPeekCursorFetchCount(tokens, index, end)) {
        direction = .forward;
        count = generatedCursorFetchCount(tokens, &index, end) orelse return null;
    }
    if (index < end and (tokens[index].matchesKeyword("from") or tokens[index].matchesKeyword("in"))) index += 1;
    if (index + 1 != end or tokens[index].kind != .identifier) return null;
    return .{
        .portal_name = .{ .start = index, .end = index + 1 },
        .direction = direction,
        .count = count,
    };
}

fn generatedOptionalCursorFetchCount(tokens: []const token_mod.Token, index: *usize, end: usize) ??i64 {
    if (index.* >= end) return null;
    if (tokens[index.*].matchesKeyword("from") or tokens[index.*].matchesKeyword("in")) return null;
    if (tokens[index.*].matchesKeyword("all")) {
        index.* += 1;
        return @as(?i64, null);
    }
    if (!generatedPeekCursorFetchCount(tokens, index.*, end)) return @as(?i64, null);
    return generatedCursorFetchCount(tokens, index, end) orelse null;
}

fn generatedPeekCursorFetchCount(tokens: []const token_mod.Token, index: usize, end: usize) bool {
    if (index >= end) return false;
    if (tokens[index].kind == .number) return true;
    return tokens[index].kind == .minus and index + 1 < end and tokens[index + 1].kind == .number;
}

fn generatedCursorFetchCount(tokens: []const token_mod.Token, index: *usize, end: usize) ?i64 {
    if (index.* >= end) return null;
    const negative = tokens[index.*].kind == .minus;
    if (negative) index.* += 1;
    if (index.* >= end or tokens[index.*].kind != .number) return null;
    var count = std.fmt.parseInt(i64, tokens[index.*].text, 10) catch return null;
    if (negative) count = -count;
    index.* += 1;
    return count;
}

const GeneratedCloseCursorMetadata = struct {
    portal_name: ?GeneratedSqlTokenRange = null,
    all: bool = false,
};

fn generatedCloseCursorMetadata(tokens: []const token_mod.Token, end: usize) ?GeneratedCloseCursorMetadata {
    if (end != 2 or end > tokens.len) return null;
    if (tokens[1].matchesKeyword("all")) return .{ .all = true };
    if (tokens[1].kind != .identifier) return null;
    return .{ .portal_name = .{ .start = 1, .end = 2 } };
}

fn buildGraphAst(
    tokens: []const token_mod.Token,
    end: usize,
    kind: GeneratedSqlGraphKind,
    statement_span: token_mod.SourceSpan,
    command_span: token_mod.SourceSpan,
) GeneratedSqlGraphAst {
    var ast = GeneratedSqlGraphAst{
        .kind = kind,
        .statement_span = statement_span,
        .command_span = command_span,
    };
    switch (kind) {
        .create_index, .create_metric => {
            var index: usize = 3;
            if (kind == .create_index) ast.if_not_exists = consumeGeneratedIfNotExists(tokens, &index, end);
            ast.object_name_tokens = generatedSingleTokenRangeIfIdentifier(tokens, index, end);
            if (findKeyword(tokens, index + 1, end, .on)) |on_index| {
                ast.source_name_tokens = generatedQualifiedNameRange(tokens, on_index + 1, end);
                if (ast.source_name_tokens) |source| {
                    if (kind == .create_index) {
                        buildGraphIndexEdgeAst(tokens, end, &ast, source.end);
                        if (ast.edge_tokens == null) buildGraphIndexExtractionAst(tokens, end, &ast, source.end);
                    } else if (source.end < end) {
                        ast.option_tokens = .{ .start = source.end, .end = end };
                    }
                }
            }
        },
        .alter_metric => {
            ast.source_name_tokens = generatedSingleTokenRangeIfIdentifier(tokens, 3, end);
            if (findTopLevelKeywordSequence(tokens, 4, end, .add, .metric)) |add_metric_index| {
                ast.object_name_tokens = generatedSingleTokenRangeIfIdentifier(tokens, add_metric_index + 2, end);
                if (findKeyword(tokens, add_metric_index + 3, end, .using)) |using_index| {
                    ast.algorithm_tokens = generatedSingleTokenRangeIfIdentifier(tokens, using_index + 1, end);
                    if (ast.algorithm_tokens) |algorithm| {
                        if (algorithm.end < end) ast.option_tokens = .{ .start = algorithm.end, .end = end };
                    }
                }
            }
        },
    }
    return ast;
}

fn buildGeneratedConstraintModeMetadataAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlTransactionAst,
) !void {
    if (end <= 3 or !tokens[1].matchesKeyword("constraints")) return error.UnsupportedSqlShape;

    var index: usize = 2;
    if (tokens[index].matchesKeyword("all")) {
        ast.constraint_all = true;
        index += 1;
    } else {
        var items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
        errdefer items.deinit(alloc);
        while (true) {
            const item = generatedSingleTokenRangeIfIdentifier(tokens, index, end) orelse return error.UnsupportedSqlShape;
            try items.append(alloc, item);
            index = item.end;
            if (index >= end) return error.UnsupportedSqlShape;
            if (tokens[index].kind != .comma) break;
            index += 1;
            if (index >= end) return error.UnsupportedSqlShape;
        }
        ast.constraint_name_items = try items.toOwnedSlice(alloc);
    }

    if (index + 1 != end) return error.UnsupportedSqlShape;
    ast.constraint_mode = if (tokens[index].matchesKeyword("immediate"))
        .immediate
    else if (tokens[index].matchesKeyword("deferred"))
        .deferred
    else
        return error.UnsupportedSqlShape;
}

fn buildGraphIndexEdgeAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlGraphAst,
    start: usize,
) void {
    if (start >= end or !tokens[start].matchesKeyword("edge")) return;
    if (start + 1 >= end or tokens[start + 1].kind != .lparen) return;
    const close = findMatchingParen(tokens, start + 1, end) orelse return;
    const arrow = findGraphEdgeArrow(tokens, start + 2, close) orelse return;
    ast.edge_tokens = .{ .start = start, .end = close + 1 };
    ast.edge_source_tokens = .{ .start = start + 2, .end = arrow };
    ast.edge_target_tokens = .{ .start = arrow + 1, .end = close };

    var index = close + 1;
    while (index < end) {
        if (tokens[index].matchesKeywordTag(.with)) {
            ast.option_tokens = .{ .start = index, .end = end };
            break;
        }
        if (tokens[index].matchesKeywordTag(.type)) {
            if (index + 1 < end) {
                const value_end = graphIndexFieldTailEnd(tokens, index + 1, end);
                if (value_end > index + 1) ast.edge_type_tokens = .{ .start = index + 1, .end = value_end };
                index = value_end;
                continue;
            }
            break;
        }
        if (tokens[index].matchesKeywordTag(.weight)) {
            if (index + 1 < end) {
                const value_end = graphIndexFieldTailEnd(tokens, index + 1, end);
                if (value_end > index + 1) ast.edge_weight_tokens = .{ .start = index + 1, .end = value_end };
                index = value_end;
                continue;
            }
            break;
        }
        break;
    }
}

fn buildGraphIndexExtractionAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlGraphAst,
    start: usize,
) void {
    var index = start;
    if (index >= end or !tokens[index].matchesKeywordTag(.source)) return;
    index += 1;
    if (index >= end or !tokens[index].matchesKeyword("enrichment")) return;
    index += 1;
    ast.extraction_enrichment_tokens = generatedQualifiedNameRange(tokens, index, end) orelse return;
    index = ast.extraction_enrichment_tokens.?.end;
    if (index >= end or !tokens[index].matchesKeywordTag(.from)) return;
    index += 1;
    const input_end = graphIndexFieldTailEnd(tokens, index, end);
    if (input_end <= index) return;
    ast.extraction_input_tokens = .{ .start = index, .end = input_end };
    index = input_end;
    if (index >= end or !tokens[index].matchesKeywordTag(.using)) return;
    index += 1;
    if (index >= end or !tokens[index].matchesKeyword("extractor")) return;
    index += 1;
    if (index >= end or !tokens[index].matchesKeyword("model")) return;
    index += 1;
    if (index >= end or (tokens[index].kind != .string and tokens[index].kind != .identifier)) return;
    ast.extraction_model_tokens = .{ .start = index, .end = index + 1 };
    index += 1;
    if (index >= end or !tokens[index].matchesKeyword("edges")) return;
    index += 1;
    if (index >= end or !tokens[index].matchesKeyword("json_path")) return;
    index += 1;
    if (index >= end or tokens[index].kind != .string) return;
    ast.extraction_edges_path_tokens = .{ .start = index, .end = index + 1 };
    index += 1;
    if (index >= end or !tokens[index].matchesKeywordTag(.source)) return;
    index += 1;
    const source_end = graphIndexFieldTailEnd(tokens, index, end);
    if (source_end <= index) return;
    ast.extraction_source_tokens = .{ .start = index, .end = source_end };
    index = source_end;
    if (index >= end or !tokens[index].matchesKeyword("target")) return;
    index += 1;
    const target_end = graphIndexFieldTailEnd(tokens, index, end);
    if (target_end <= index) return;
    ast.extraction_target_tokens = .{ .start = index, .end = target_end };
    index = target_end;

    while (index < end) {
        if (tokens[index].matchesKeywordTag(.with)) {
            ast.option_tokens = .{ .start = index, .end = end };
            break;
        }
        if (tokens[index].matchesKeywordTag(.type)) {
            if (index + 1 < end) {
                const value_end = graphIndexFieldTailEnd(tokens, index + 1, end);
                if (value_end > index + 1) ast.extraction_type_tokens = .{ .start = index + 1, .end = value_end };
                index = value_end;
                continue;
            }
            break;
        }
        if (tokens[index].matchesKeywordTag(.weight)) {
            if (index + 1 < end) {
                const value_end = graphIndexFieldTailEnd(tokens, index + 1, end);
                if (value_end > index + 1) ast.extraction_weight_tokens = .{ .start = index + 1, .end = value_end };
                index = value_end;
                continue;
            }
            break;
        }
        break;
    }
}

fn findGraphEdgeArrow(tokens: []const token_mod.Token, start: usize, end: usize) ?usize {
    var depth: usize = 0;
    var index = start;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .arrow_json => if (depth == 0 and index > start) return index,
            else => {},
        }
    }
    return null;
}

fn graphIndexFieldTailEnd(tokens: []const token_mod.Token, start: usize, end: usize) usize {
    var depth: usize = 0;
    var index = start;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return index;
                depth -= 1;
            },
            .comma, .semicolon => if (depth == 0) return index,
            else => if (depth == 0 and index > start and
                (tokens[index].matchesKeywordTag(.type) or
                    tokens[index].matchesKeywordTag(.weight) or
                    tokens[index].matchesKeywordTag(.using) or
                    tokens[index].matchesKeywordTag(.source) or
                    tokens[index].matchesKeyword("target") or
                    tokens[index].matchesKeyword("model") or
                    tokens[index].matchesKeyword("edges") or
                    tokens[index].matchesKeywordTag(.with)))
            {
                return index;
            },
        }
    }
    return end;
}

fn generatedBeginHasModeTail(tokens: []const token_mod.Token, end: usize) bool {
    if (end <= 1 or end > tokens.len) return false;
    if (end == 2 and (tokens[1].matchesKeyword("work") or tokens[1].matchesKeyword("transaction"))) return false;
    return true;
}

fn generatedCommandStartIndex(tokens: []const token_mod.Token, statement: GeneratedSqlStatement) ?usize {
    return switch (statement) {
        .dml => if (tokens.len > 0 and tokens[0].matchesKeywordTag(.with))
            generatedWithFinalStatementIndex(tokens, .{ .allow_recursive = true })
        else
            0,
        .read => if (tokens.len > 0 and tokens[0].matchesKeywordTag(.with))
            findTopLevelKeyword(tokens, 0, statementTokenEnd(tokens), .select)
        else
            0,
        else => 0,
    };
}

const GeneratedWithFinalStatementOptions = struct {
    allow_recursive: bool = false,
};

fn generatedWithFinalStatementIndex(tokens: []const token_mod.Token, options: GeneratedWithFinalStatementOptions) ?usize {
    if (tokens.len == 0 or !tokens[0].matchesKeywordTag(.with)) return null;
    var index: usize = 1;
    if (index < tokens.len and tokens[index].matchesKeywordTag(.recursive)) {
        if (!options.allow_recursive) return null;
        index += 1;
    }

    while (true) {
        if (index >= tokens.len or tokens[index].kind != .identifier) return null;
        index += 1;
        if (index < tokens.len and tokens[index].kind == .lparen) {
            index = (findMatchingParen(tokens, index, tokens.len) orelse return null) + 1;
        }
        if (index >= tokens.len or !tokens[index].matchesKeywordTag(.as)) return null;
        index += 1;
        if (index < tokens.len and tokens[index].matchesKeywordTag(.materialized)) {
            index += 1;
        } else if (index + 1 < tokens.len and tokens[index].matchesKeywordTag(.not) and tokens[index + 1].matchesKeywordTag(.materialized)) {
            index += 2;
        }
        if (index >= tokens.len or tokens[index].kind != .lparen) return null;
        index = (findMatchingParen(tokens, index, tokens.len) orelse return null) + 1;
        if (index < tokens.len and tokens[index].kind == .comma) {
            index += 1;
            continue;
        }
        break;
    }

    if (index >= tokens.len or tokens[index].kind != .identifier) return null;
    return index;
}

fn ddlKindFromExtensionIndexKind(kind: GeneratedSqlExtensionIndexKind) GeneratedSqlDdlKind {
    return switch (kind) {
        .create_index => .create_index,
        .drop_index => .drop_index,
        .create_extension => .create_extension,
        .drop_extension => .drop_extension,
    };
}

fn buildSessionAst(
    tokens: []const token_mod.Token,
    end: usize,
    kind: GeneratedSqlSessionKind,
    statement_span: token_mod.SourceSpan,
    command_span: token_mod.SourceSpan,
) GeneratedSqlSessionAst {
    var ast = GeneratedSqlSessionAst{
        .kind = kind,
        .statement_span = statement_span,
        .command_span = command_span,
    };
    switch (kind) {
        .set => {
            const name_start = findSetNameStart(tokens, end);
            const value_start = findSetValueStart(tokens, end, name_start) orelse end;
            if (value_start > name_start) ast.name_tokens = .{ .start = name_start, .end = value_start - 1 };
            if (value_start < end) ast.value_tokens = .{ .start = value_start, .end = end };
        },
        .reset, .show => {
            if (end > 1) ast.name_tokens = .{ .start = 1, .end = end };
        },
        .discard_all => {},
    }
    return ast;
}

fn findSetNameStart(tokens: []const token_mod.Token, end: usize) usize {
    if (end > 2 and tokens[1].matchesKeyword("local")) return 2;
    if (end > 2 and tokens[1].matchesKeyword("session")) {
        if (end > 3 and tokens[2].matchesKeyword("characteristics")) return 1;
        return 2;
    }
    return 1;
}

fn findSetValueStart(tokens: []const token_mod.Token, end: usize, name_start: usize) ?usize {
    if (name_start + 2 < end and
        tokens[name_start].matchesKeyword("session") and
        tokens[name_start + 1].matchesKeyword("characteristics") and
        tokens[name_start + 2].matchesKeywordTag(.as))
    {
        return null;
    }
    var index: usize = name_start;
    while (index < end) : (index += 1) {
        if (tokens[index].kind == .eq or tokens[index].matchesKeywordTag(.to)) return index + 1;
    }
    return if (end > name_start + 1) name_start + 1 else null;
}

fn buildPreparedAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    kind: GeneratedSqlPreparedKind,
    statement_span: token_mod.SourceSpan,
    command_span: token_mod.SourceSpan,
) anyerror!GeneratedSqlPreparedAst {
    var ast = GeneratedSqlPreparedAst{
        .kind = kind,
        .statement_span = statement_span,
        .command_span = command_span,
    };
    errdefer ast.deinit(alloc);
    switch (kind) {
        .prepare => {
            if (end > 1) ast.name_tokens = .{ .start = 1, .end = 2 };
            if (findKeyword(tokens, 2, end, .as)) |as_index| {
                if (as_index > 2) ast.parameter_tokens = .{ .start = 2, .end = as_index };
                if (as_index + 1 < end) {
                    ast.inner_statement_tokens = .{ .start = as_index + 1, .end = end };
                    ast.inner_statement_ast = try buildPreparedInnerAstAlloc(alloc, tokens[as_index + 1 .. end]);
                }
            }
        },
        .execute => {
            if (end > 1) ast.name_tokens = .{ .start = 1, .end = 2 };
            if (end > 2) ast.argument_tokens = .{ .start = 2, .end = end };
        },
        .deallocate => {
            const name_start: usize = if (end > 2 and tokens[1].matchesKeywordTag(.prepare)) 2 else 1;
            if (end > name_start) ast.name_tokens = .{ .start = name_start, .end = end };
        },
    }
    return ast;
}

fn buildPreparedInnerAstAlloc(alloc: std.mem.Allocator, tokens: []const token_mod.Token) anyerror!?*GeneratedSqlAst {
    var parsed = parseTokensAlloc(alloc, tokens) catch |err| switch (err) {
        error.UnsupportedSqlShape => return null,
        else => return err,
    };
    defer parsed.deinit(alloc);
    const ast = parsed.ast orelse return null;
    const owned = try alloc.create(GeneratedSqlAst);
    owned.* = ast;
    parsed.ast = null;
    return owned;
}

fn buildPreparedTransactionAst(
    end: usize,
    kind: GeneratedSqlPreparedTransactionKind,
    statement_span: token_mod.SourceSpan,
    command_span: token_mod.SourceSpan,
) GeneratedSqlPreparedTransactionAst {
    return .{
        .kind = kind,
        .statement_span = statement_span,
        .command_span = command_span,
        .gid_tokens = if (end == 3) .{ .start = 2, .end = 3 } else null,
    };
}

fn buildDdlAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    kind: GeneratedSqlDdlKind,
    statement_span: token_mod.SourceSpan,
    command_span: token_mod.SourceSpan,
) !GeneratedSqlDdlAst {
    var ast = GeneratedSqlDdlAst{
        .kind = kind,
        .statement_span = statement_span,
        .command_span = command_span,
    };
    errdefer ast.deinit(alloc);
    var index: usize = 2;
    switch (kind) {
        .create_database => {
            ast.object_name_tokens = generatedSingleTokenRangeIfIdentifier(tokens, index, end);
        },
        .create_schema => {
            ast.if_not_exists = consumeGeneratedIfNotExists(tokens, &index, end);
            ast.object_name_tokens = generatedSingleTokenRangeIfIdentifier(tokens, index, end);
        },
        .create_extension => {
            ast.if_not_exists = consumeGeneratedIfNotExists(tokens, &index, end);
            ast.object_name_tokens = generatedSingleTokenRangeIfIdentifier(tokens, index, end);
            if (ast.object_name_tokens) |_| index += 1;
            if (index < end and tokens[index].matchesKeywordTag(.with)) index += 1;
            if (index + 1 < end and tokens[index].matchesKeywordTag(.schema)) {
                ast.schema_name_tokens = generatedSingleTokenRangeIfIdentifier(tokens, index + 1, end);
                index += 2;
            }
            if (index + 1 < end and tokens[index].matchesKeyword("version") and tokens[index + 1].kind == .string) {
                ast.version_tokens = .{ .start = index + 1, .end = index + 2 };
            }
        },
        .comment => {
            try populateGeneratedCommentAst(alloc, tokens, end, &ast);
        },
        .security_label => {
            try populateGeneratedSecurityLabelAst(alloc, tokens, end, &ast);
        },
        .grant => {
            try populateGeneratedPrivilegeChangeAst(alloc, tokens, end, .grant, &ast);
        },
        .revoke => {
            try populateGeneratedPrivilegeChangeAst(alloc, tokens, end, .revoke, &ast);
        },
        .alter_default_privileges => {
            try populateGeneratedDefaultPrivilegeChangeAst(alloc, tokens, end, &ast);
        },
        .create_table => {
            index = 1;
            if (index + 2 < end and tokens[index].matchesKeywordTag(.@"or") and tokens[index + 1].matchesKeywordTag(.replace)) {
                ast.replace_existing = true;
                index += 2;
            }
            consumeGeneratedRelationLifetime(tokens, &index, end);
            if (index < end and tokens[index].matchesKeywordTag(.table)) index += 1;
            consumeGeneratedOnlyPrefix(tokens, &index, end);
            ast.if_not_exists = consumeGeneratedIfNotExists(tokens, &index, end);
            ast.object_name_tokens = generatedQualifiedNameRange(tokens, index, end);
            if (ast.object_name_tokens) |table_range| {
                if (table_range.end < end and tokens[table_range.end].kind == .lparen) {
                    if (findMatchingParen(tokens, table_range.end, end)) |definition_close| {
                        ast.alter_table_operation_tokens = .{ .start = table_range.end + 1, .end = definition_close };
                        ast.alter_table_operation_items = try buildTopLevelTokenListAst(alloc, tokens, ast.alter_table_operation_tokens.?);
                        try populateGeneratedAlterTableOperationGeneratedExpressionAst(alloc, tokens, &ast);
                        try populateGeneratedCreateTableLikeAst(alloc, tokens, ast.alter_table_operation_tokens.?, &ast);
                        try populateGeneratedCreateTableDocumentAst(alloc, tokens, definition_close + 1, end, &ast);
                        try populateGeneratedCreateTablePartitionedAst(alloc, tokens, definition_close + 1, end, &ast);
                    }
                } else {
                    populateGeneratedCreateTablePartitionOfAst(tokens, table_range.end, end, &ast);
                }
            }
        },
        .create_view => {
            index = 1;
            if (index + 2 < end and tokens[index].matchesKeywordTag(.@"or") and tokens[index + 1].matchesKeywordTag(.replace)) {
                ast.replace_existing = true;
                index += 2;
            }
            if (index < end and tokens[index].matchesKeywordTag(.view)) index += 1;
            ast.if_not_exists = consumeGeneratedIfNotExists(tokens, &index, end);
            ast.object_name_tokens = generatedQualifiedNameRange(tokens, index, end);
            if (ast.object_name_tokens) |view_range| {
                if (view_range.end < end) {
                    ast.alter_table_operation_tokens = .{ .start = view_range.end, .end = end };
                    ast.view_metadata = try buildGeneratedCreateViewAstPtr(alloc, tokens, .{ .start = view_range.end, .end = end });
                }
            }
        },
        .create_materialized_view => {
            index = 1;
            if (index + 2 < end and tokens[index].matchesKeywordTag(.@"or") and tokens[index + 1].matchesKeywordTag(.replace)) {
                ast.replace_existing = true;
                index += 2;
            }
            if (index + 1 < end and tokens[index].matchesKeywordTag(.materialized) and tokens[index + 1].matchesKeywordTag(.view)) {
                index += 2;
                ast.if_not_exists = consumeGeneratedIfNotExists(tokens, &index, end);
                ast.object_name_tokens = generatedQualifiedNameRange(tokens, index, end);
                if (ast.object_name_tokens) |view_range| {
                    if (view_range.end < end) {
                        const operation_range = GeneratedSqlTokenRange{ .start = view_range.end, .end = end };
                        ast.alter_table_operation_tokens = operation_range;
                        ast.view_metadata = try buildGeneratedCreateViewAstPtr(alloc, tokens, operation_range);
                        populateGeneratedMaterializedViewDataClauseAst(tokens, operation_range.start, end, &ast);
                    }
                }
            }
        },
        .create_domain => {
            if (end > 2 and tokens[1].matchesKeywordTag(.domain)) {
                ast.object_name_tokens = generatedQualifiedNameRange(tokens, 2, end);
                if (ast.object_name_tokens) |domain_range| {
                    if (domain_range.end < end) {
                        ast.alter_table_operation_tokens = .{ .start = domain_range.end, .end = end };
                        if (tokens[domain_range.end].matchesKeywordTag(.as)) {
                            ast.domain_type_tokens = generatedQualifiedNameRange(tokens, domain_range.end + 1, end);
                            if (ast.domain_type_tokens) |type_range| {
                                if (type_range.end < end) {
                                    ast.domain_operation_items = try buildGeneratedCreateDomainOptionListAst(alloc, tokens, .{
                                        .start = type_range.end,
                                        .end = end,
                                    });
                                    try populateGeneratedCreateDomainOptionPayloadAst(alloc, tokens, &ast);
                                }
                            }
                        }
                    }
