fn generatedParenthesizedRangeAt(
    tokens: []const token_mod.Token,
    start: usize,
    end: usize,
) ?GeneratedSqlTokenRange {
    if (start >= end or start >= tokens.len or tokens[start].kind != .lparen) return null;
