) ?GeneratedSqlTokenRange {
    if (item.start >= item.end or item.end > tokens.len) return null;
    var cursor = item.start;
    if (tokens[cursor].matchesKeywordTag(.add)) {
        cursor += 1;
        if (cursor >= item.end or !tokens[cursor].matchesKeywordTag(.column)) return null;
        cursor += 1;
        if (cursor + 2 < item.end and
            tokens[cursor].matchesKeywordTag(.@"if") and
            tokens[cursor + 1].matchesKeywordTag(.not) and
            tokens[cursor + 2].matchesKeyword("exists"))
        {
            cursor += 3;
        }
    } else if (tokens[cursor].matchesKeywordTag(.alter) or
        tokens[cursor].matchesKeywordTag(.drop) or
        tokens[cursor].matchesKeywordTag(.rename) or
        tokens[cursor].matchesKeywordTag(.validate) or
        tokens[cursor].matchesKeyword("attach") or
        tokens[cursor].matchesKeyword("detach") or
        tokens[cursor].matchesKeywordTag(.constraint) or
        tokens[cursor].matchesKeyword("period") or
        tokens[cursor].matchesKeyword("primary") or
        tokens[cursor].matchesKeyword("unique") or
        tokens[cursor].matchesKeyword("foreign") or
        tokens[cursor].matchesKeyword("check"))
    {
        return null;
    }
    if (cursor >= item.end or tokens[cursor].kind != .identifier) return null;
    return .{ .start = cursor, .end = cursor + 1 };
}

fn generatedColumnDefinitionTypeRange(
    tokens: []const token_mod.Token,
    name_range: GeneratedSqlTokenRange,
    item: GeneratedSqlTokenRange,
) ?GeneratedSqlTokenRange {
    if (name_range.end > item.end) return null;
    const end = generatedColumnDefinitionTypeEnd(tokens, name_range.end, item.end) orelse return null;
    if (end <= name_range.end or end > item.end) return null;
    return .{ .start = name_range.end, .end = end };
}

fn generatedColumnDefinitionTypeEnd(
    tokens: []const token_mod.Token,
    start: usize,
    end: usize,
) ?usize {
    if (start >= end or start >= tokens.len or tokens[start].kind != .identifier) return null;
    var cursor = start + 1;
    if (tokens[start].matchesKeyword("character")) {
        if (cursor >= end or !tokens[cursor].matchesKeyword("varying")) return null;
        cursor += 1;
    } else if (tokens[start].matchesKeyword("double")) {
        if (cursor >= end or !tokens[cursor].matchesKeyword("precision")) return null;
        cursor += 1;
    } else if (tokens[start].matchesKeyword("timestamp")) {
        if (cursor < end and tokens[cursor].matchesKeyword("with")) {
            if (cursor + 2 >= end or !tokens[cursor + 1].matchesKeyword("time") or !tokens[cursor + 2].matchesKeyword("zone")) return null;
            cursor += 3;
        } else if (cursor < end and tokens[cursor].matchesKeyword("without")) {
            if (cursor + 2 >= end or !tokens[cursor + 1].matchesKeyword("time") or !tokens[cursor + 2].matchesKeyword("zone")) return null;
            cursor += 3;
        }
    }
    if (cursor < end and tokens[cursor].kind == .lparen) {
        const close_index = findMatchingParen(tokens, cursor, end) orelse return null;
        cursor = close_index + 1;
    }
    if (cursor < end and tokens[cursor].kind == .lbracket) {
        if (cursor + 1 >= end or tokens[cursor + 1].kind != .rbracket) return null;
        cursor += 2;
    }
    return cursor;
}

fn generatedColumnDefinitionNullabilityRange(
    tokens: []const token_mod.Token,
    start: usize,
    item: GeneratedSqlTokenRange,
) ?GeneratedSqlTokenRange {
    var index = start;
    var depth: usize = 0;
    while (index < item.end and index < tokens.len) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0) {
                if (tokens[index].matchesKeywordTag(.not)) {
                    if (index + 1 < item.end and tokens[index + 1].matchesKeywordTag(.null)) return .{ .start = index, .end = index + 2 };
                } else if (tokens[index].matchesKeywordTag(.null)) {
                    return .{ .start = index, .end = index + 1 };
                }
            },
        }
    }
    return null;
}

fn generatedColumnDefinitionCollationRange(
    tokens: []const token_mod.Token,
    start: usize,
    item: GeneratedSqlTokenRange,
) ?GeneratedSqlTokenRange {
    const collate_index = findTopLevelKeywordText(tokens, start, item.end, "collate") orelse return null;
    if (collate_index + 1 >= item.end or tokens[collate_index + 1].kind != .identifier) return null;
    var end = collate_index + 2;
    if (std.mem.endsWith(u8, tokens[collate_index + 1].text, ".")) {
        if (end >= item.end or tokens[end].kind != .identifier) return null;
        end += 1;
    }
    return .{ .start = collate_index, .end = end };
}

fn generatedColumnDefinitionDefaultValueRange(
    tokens: []const token_mod.Token,
    item: GeneratedSqlTokenRange,
) ?GeneratedSqlTokenRange {
    const clause = generatedColumnDefinitionDefaultClauseRange(tokens, item) orelse return null;
    return .{ .start = clause.start + 1, .end = clause.end };
}

fn generatedColumnDefinitionDefaultClauseRange(
    tokens: []const token_mod.Token,
    item: GeneratedSqlTokenRange,
) ?GeneratedSqlTokenRange {
    var search_start = item.start;
    while (findTopLevelKeyword(tokens, search_start, item.end, .default)) |default_index| {
        search_start = default_index + 1;
        if (!generatedDefaultKeywordIntroducesValue(tokens, item, default_index)) continue;
        const start = default_index + 1;
        if (start >= item.end) return null;
        const end = generatedColumnDefinitionDefaultValueEnd(tokens, start, item.end) orelse return null;
        if (end <= start or end > item.end) return null;
        return .{ .start = default_index, .end = end };
    }
    return null;
}

fn generatedDefaultKeywordIntroducesValue(
    tokens: []const token_mod.Token,
    item: GeneratedSqlTokenRange,
    default_index: usize,
) bool {
    if (default_index <= item.start) return true;
    const previous = tokens[default_index - 1];
    if (previous.matchesKeywordTag(.by) or previous.matchesKeywordTag(.drop)) return false;
    return true;
}

fn generatedColumnDefinitionDefaultValueEnd(
    tokens: []const token_mod.Token,
    start: usize,
    end: usize,
) ?usize {
    if (start >= end or start >= tokens.len) return null;
    const first = tokens[start];
    if (first.kind == .lparen) {
        const close_index = findMatchingParen(tokens, start, end) orelse return null;
        if (close_index <= start + 1) return null;
        return close_index + 1;
    }
    if (first.matchesKeyword("array")) {
        if (start + 1 >= end or tokens[start + 1].kind != .lbracket) return null;
        const close_index = findMatchingBracket(tokens, start + 1, end) orelse return null;
        return close_index + 1;
    }
    if (first.kind == .plus or first.kind == .minus) {
        if (start + 1 < end and tokens[start + 1].kind == .number) return start + 2;
        return null;
    }
    if (first.kind == .number or first.kind == .string) return start + 1;
    if (first.kind != .identifier) return null;
    if (first.matchesKeywordTag(.true) or first.matchesKeywordTag(.false) or first.matchesKeywordTag(.null)) return start + 1;
    if (first.matchesKeyword("current_date")) return start + 1;
    if (first.matchesKeyword("current_timestamp")) {
        if (start + 1 < end and tokens[start + 1].kind == .lparen) {
            const close_index = findMatchingParen(tokens, start + 1, end) orelse return null;
            return close_index + 1;
        }
        return start + 1;
    }
    if (first.matchesKeyword("gen_random_uuid") or first.matchesKeyword("uuid_generate_v4") or first.matchesKeyword("now")) {
        if (start + 1 >= end or tokens[start + 1].kind != .lparen) return null;
        const close_index = findMatchingParen(tokens, start + 1, end) orelse return null;
        return close_index + 1;
    }
    return null;
}

fn generatedAlterTableOperationRewriteExpressionRange(
    tokens: []const token_mod.Token,
    item: GeneratedSqlTokenRange,
) ?GeneratedSqlTokenRange {
    if (item.start >= item.end or !tokens[item.start].matchesKeywordTag(.alter)) return null;
    var action_index = item.start + 1;
    if (action_index < item.end and tokens[action_index].matchesKeywordTag(.column)) action_index += 1;
    if (action_index + 1 >= item.end) return null;
    action_index += 1;

    if (tokens[action_index].matchesKeywordTag(.type)) {
        action_index += 1;
    } else if (tokens[action_index].matchesKeywordTag(.set)) {
        if (action_index + 2 >= item.end or
            !tokens[action_index + 1].matchesKeywordTag(.data) or
            !tokens[action_index + 2].matchesKeywordTag(.type))
        {
            return null;
        }
        action_index += 3;
    } else {
        return null;
    }

    const using_index = findTopLevelKeyword(tokens, action_index, item.end, .using) orelse return null;
    if (using_index + 1 >= item.end) return null;
    return .{ .start = using_index + 1, .end = item.end };
}

fn populateGeneratedDdlScalarSubqueryDefaultAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlDdlAst,
) !void {
    if (end > tokens.len) return error.UnsupportedSqlShape;
    var items = std.ArrayListUnmanaged(GeneratedSqlDdlScalarSubqueryDefaultAst).empty;
    errdefer {
        for (items.items) |*item| item.deinit(alloc);
        items.deinit(alloc);
    }
    var index: usize = 0;
    while (index + 2 < end) : (index += 1) {
        if (!tokens[index].matchesKeywordTag(.default) or tokens[index + 1].kind != .lparen or !tokens[index + 2].matchesKeywordTag(.select)) continue;
        const close_index = findMatchingParen(tokens, index + 1, end) orelse return error.UnsupportedSqlShape;
        if (close_index <= index + 2) return error.UnsupportedSqlShape;
        const query_tokens = GeneratedSqlTokenRange{ .start = index + 2, .end = close_index };
        const read_ast = try buildGeneratedReadAstForRangeAlloc(alloc, tokens, query_tokens);
        var item = GeneratedSqlDdlScalarSubqueryDefaultAst{
            .default_tokens = .{ .start = index + 1, .end = close_index + 1 },
            .query_tokens = query_tokens,
            .read_ast = read_ast,
        };
        var item_transferred = false;
        errdefer if (!item_transferred) item.deinit(alloc);
        try items.append(alloc, item);
        item_transferred = true;
        index = close_index;
    }
    const owned = try items.toOwnedSlice(alloc);
    items = .empty;
    ast.scalar_subquery_default_items = owned;
    ast.scalar_subquery_default_count = owned.len;
}

fn buildGeneratedRelationPopulationSourceReadAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    end: usize,
) !?*GeneratedSqlReadAst {
    if (end == 0 or end > tokens.len) return null;
    if (tokens[0].matchesKeywordTag(.select)) {
        const ranges = generatedSelectIntoSourceRanges(tokens, 0, end) orelse return null;
        return try buildGeneratedReadAstForFlattenedRangesAlloc(alloc, tokens, &.{
            ranges.prefix,
            ranges.suffix,
        });
    }
    const range = generatedCreateTableAsSourceRange(tokens, 0, end) orelse return null;
    return try buildGeneratedReadAstForRangeAlloc(alloc, tokens, range);
}

const GeneratedSelectIntoSourceRanges = struct {
    prefix: GeneratedSqlTokenRange,
    suffix: GeneratedSqlTokenRange,
};

fn generatedSelectIntoSourceRanges(
    tokens: []const token_mod.Token,
    start: usize,
    end: usize,
) ?GeneratedSelectIntoSourceRanges {
    if (start >= end or end > tokens.len) return null;
    if (!tokens[start].matchesKeywordTag(.select)) return null;
    const into_index = findTopLevelKeyword(tokens, start + 1, end, .into) orelse return null;
    if (into_index <= start + 1) return null;
    const target = generatedSelectIntoTargetRange(tokens, start, end) orelse return null;
    if (target.end >= end or !tokens[target.end].matchesKeywordTag(.from)) return null;
    return .{
        .prefix = .{ .start = start, .end = into_index },
        .suffix = .{ .start = target.end, .end = end },
    };
}

fn generatedCreateTableAsSourceRange(
    tokens: []const token_mod.Token,
    start: usize,
    end: usize,
) ?GeneratedSqlTokenRange {
    if (start >= end or end > tokens.len) return null;
    const target = generatedCreateTableAsTargetRange(tokens, start, end) orelse return null;
    if (target.end >= end or !tokens[target.end].matchesKeywordTag(.as)) return null;
    const source_start = target.end + 1;
    var source_end = generatedRelationPopulationDataClauseStart(tokens, source_start, end) orelse end;
    while (source_end > source_start and tokens[source_end - 1].kind == .semicolon) source_end -= 1;
    if (source_start >= source_end or !tokens[source_start].matchesKeywordTag(.select)) return null;
    return .{ .start = source_start, .end = source_end };
}

fn populateGeneratedCreateTableAsAst(
    tokens: []const token_mod.Token,
    end: usize,
    ast: *GeneratedSqlDdlAst,
) void {
    const source_range = generatedCreateTableAsSourceRange(tokens, 0, end) orelse return;
    ast.relation_population_source_tokens = source_range;
    if (generatedRelationPopulationDataClause(tokens, source_range.start, end)) |clause| {
        ast.relation_population_data_clause_tokens = .{ .start = clause.start, .end = clause.end };
        ast.relation_population_populate = clause.populate;
    } else {
        ast.relation_population_populate = true;
    }
}

fn populateGeneratedMaterializedViewDataClauseAst(
    tokens: []const token_mod.Token,
    source_start: usize,
    end: usize,
    ast: *GeneratedSqlDdlAst,
) void {
    if (generatedRelationPopulationDataClause(tokens, source_start, end)) |clause| {
        ast.materialized_view_data_clause_tokens = .{ .start = clause.start, .end = clause.end };
        ast.materialized_view_populate = clause.populate;
    } else {
        ast.materialized_view_populate = true;
    }
}

const GeneratedRelationPopulationDataClause = struct {
    start: usize,
    end: usize,
    populate: bool,
};

fn generatedRelationPopulationDataClause(
    tokens: []const token_mod.Token,
    source_start: usize,
    end: usize,
) ?GeneratedRelationPopulationDataClause {
    const start = generatedRelationPopulationDataClauseStart(tokens, source_start, end) orelse return null;
    if (start + 2 == end and tokens[start].matchesKeywordTag(.with) and tokens[start + 1].matchesKeywordTag(.data)) {
        return .{ .start = start, .end = end, .populate = true };
    }
    if (start + 3 == end and
        tokens[start].matchesKeywordTag(.with) and
        tokens[start + 1].matchesKeywordTag(.no) and
        tokens[start + 2].matchesKeywordTag(.data))
    {
        return .{ .start = start, .end = end, .populate = false };
    }
    return null;
}

fn generatedRelationPopulationDataClauseStart(
    tokens: []const token_mod.Token,
    source_start: usize,
    end: usize,
) ?usize {
    if (end < source_start + 2 or end > tokens.len) return null;
    const with_data_index = end - 2;
    if (tokens[with_data_index].matchesKeywordTag(.with) and
        tokens[with_data_index + 1].matchesKeywordTag(.data) and
        topLevelTokenAt(tokens, source_start, with_data_index))
    {
        return with_data_index;
    }
    if (end < source_start + 3) return null;
    const with_no_data_index = end - 3;
    if (tokens[with_no_data_index].matchesKeywordTag(.with) and
        tokens[with_no_data_index + 1].matchesKeywordTag(.no) and
        tokens[with_no_data_index + 2].matchesKeywordTag(.data) and
        topLevelTokenAt(tokens, source_start, with_no_data_index))
    {
        return with_no_data_index;
    }
    return null;
}

fn topLevelTokenAt(
    tokens: []const token_mod.Token,
    start: usize,
    index: usize,
) bool {
    if (start > index or index > tokens.len) return false;
    var depth: usize = 0;
    var cursor = start;
    while (cursor < index) : (cursor += 1) {
        switch (tokens[cursor].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return false;
                depth -= 1;
            },
            else => {},
        }
    }
    return depth == 0;
}

fn buildDmlAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    start: usize,
    end: usize,
    kind: GeneratedSqlDmlKind,
    statement_span: token_mod.SourceSpan,
    command_span: token_mod.SourceSpan,
) !GeneratedSqlDmlAst {
    var ast: GeneratedSqlDmlAst = undefined;
    try buildDmlAstInPlace(alloc, tokens, start, end, kind, statement_span, command_span, &ast);
    return ast;
}

fn buildDmlAstInPlace(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    start: usize,
    end: usize,
    kind: GeneratedSqlDmlKind,
    statement_span: token_mod.SourceSpan,
    command_span: token_mod.SourceSpan,
    ast: *GeneratedSqlDmlAst,
) !void {
    ast.* = GeneratedSqlDmlAst{
        .kind = kind,
        .statement_span = statement_span,
        .command_span = command_span,
    };
    errdefer ast.deinit(alloc);
    if (start > 0 and tokens.len > 0 and tokens[0].matchesKeywordTag(.with)) {
        ast.cte_tokens = .{ .start = 1, .end = start };
        ast.cte_recursive = tokens.len > 1 and tokens[1].matchesKeywordTag(.recursive);
        try buildDmlCteAstAlloc(alloc, tokens, start, ast);
    }
    switch (kind) {
        .insert_values, .insert_select => try buildInsertDmlAst(alloc, tokens, start, end, ast),
        .update => try buildUpdateDmlAst(alloc, tokens, start, end, ast),
        .delete => try buildDeleteDmlAst(alloc, tokens, start, end, ast),
        .truncate => try buildTruncateDmlAst(alloc, tokens, start, end, ast),
        .merge => try buildMergeDmlAst(alloc, tokens, start, end, ast),
    }
    try buildDmlChildReadAst(alloc, tokens, ast);
}

fn buildDmlCteAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    final_statement_index: usize,
    ast: *GeneratedSqlDmlAst,
) !void {
    const cte_tokens = ast.cte_tokens orelse return;
    var index: usize = if (ast.cte_recursive) 2 else 1;
    if (index >= final_statement_index) return;
    const list_tokens = GeneratedSqlTokenRange{ .start = index, .end = final_statement_index };
    var count: usize = 0;
    var items = std.ArrayListUnmanaged(GeneratedSqlDmlCteItemAst).empty;
    errdefer deinitGeneratedDmlCteItems(alloc, items.items);
    errdefer items.deinit(alloc);
    var first_name: ?GeneratedSqlTokenRange = null;
    var first_body: ?GeneratedSqlTokenRange = null;
    var first_read: ?GeneratedSqlDmlReadBodyAst = null;
    var first_dml: ?*GeneratedSqlDmlAst = null;
    var last_name: ?GeneratedSqlTokenRange = null;
    var last_body: ?GeneratedSqlTokenRange = null;
    var last_read: ?GeneratedSqlDmlReadBodyAst = null;
    var last_dml: ?*GeneratedSqlDmlAst = null;
    while (index < final_statement_index) {
        if (tokens[index].kind != .identifier) return;
        const name_tokens = GeneratedSqlTokenRange{ .start = index, .end = index + 1 };
        index += 1;
        var column_tokens: ?GeneratedSqlTokenRange = null;
        var column_name_tokens: ?GeneratedSqlTokenRange = null;
        var column_names: GeneratedSqlListAst = .{};
        var column_names_transferred = false;
        errdefer if (!column_names_transferred) column_names.deinit(alloc);
        if (index < final_statement_index and tokens[index].kind == .lparen) {
            const column_close = findMatchingParen(tokens, index, final_statement_index) orelse return;
            if (column_close >= final_statement_index) return;
            column_tokens = .{ .start = index, .end = column_close + 1 };
            if (index + 1 < column_close) {
                column_name_tokens = .{ .start = index + 1, .end = column_close };
                column_names = try buildTopLevelListAst(alloc, tokens, column_name_tokens.?, .{});
            }
            index = column_close + 1;
        }
        if (index >= final_statement_index or !tokens[index].matchesKeywordTag(.as)) return;
        index += 1;
        var materialization_tokens: ?GeneratedSqlTokenRange = null;
        var materialization: ?GeneratedSqlCteMaterialization = null;
        if (index < final_statement_index and tokens[index].matchesKeywordTag(.materialized)) {
            materialization_tokens = .{ .start = index, .end = index + 1 };
            materialization = .materialized;
            index += 1;
        } else if (index + 1 < final_statement_index and tokens[index].matchesKeywordTag(.not) and tokens[index + 1].matchesKeywordTag(.materialized)) {
            materialization_tokens = .{ .start = index, .end = index + 2 };
            materialization = .not_materialized;
            index += 2;
        }
        if (index >= final_statement_index or tokens[index].kind != .lparen) return;
        const close = findMatchingParen(tokens, index, final_statement_index) orelse return;
        if (index + 1 >= close) return;
        const body_tokens = GeneratedSqlTokenRange{ .start = index + 1, .end = close };
        var body_read = try buildDmlReadBodyMetadata(alloc, tokens, body_tokens);
        var body_read_transferred = false;
        errdefer if (!body_read_transferred) {
            if (body_read) |*owned_body_read| owned_body_read.deinit(alloc);
        };
        const body_dml = if (body_read == null)
            try buildDataModifyingCteBodyDmlAstAlloc(alloc, tokens[body_tokens.start..body_tokens.end])
        else
            null;
        var body_dml_transferred = false;
        errdefer if (!body_dml_transferred) {
            if (body_dml) |owned_body_dml| {
                owned_body_dml.deinit(alloc);
                alloc.destroy(owned_body_dml);
            }
        };
        if (body_read == null and body_dml == null) return;
        try items.append(alloc, .{
            .name_tokens = name_tokens,
            .column_tokens = column_tokens,
            .column_name_tokens = column_name_tokens,
            .column_names = column_names,
            .materialization_tokens = materialization_tokens,
            .materialization = materialization,
            .body_tokens = body_tokens,
            .body_read = body_read,
            .body_dml = body_dml,
        });
        column_names_transferred = true;
        body_read_transferred = true;
        body_dml_transferred = true;
        if (count == 0) {
            first_name = name_tokens;
            first_body = body_tokens;
            first_read = body_read;
            first_dml = body_dml;
        }
        last_name = name_tokens;
        last_body = body_tokens;
        last_read = body_read;
        last_dml = body_dml;
        count += 1;
        index = close + 1;
        if (index < final_statement_index and tokens[index].kind == .comma) {
            index += 1;
            continue;
        }
        break;
    }
    if (count == 0 or index != final_statement_index) return;
    const owned_items = try items.toOwnedSlice(alloc);
    errdefer alloc.free(owned_items);
    ast.cte_prefix = .{
        .tokens = cte_tokens,
        .list_tokens = list_tokens,
        .first_name_tokens = first_name.?,
        .first_body_tokens = first_body.?,
        .first_body_read = first_read,
        .first_body_dml = first_dml,
        .last_name_tokens = last_name.?,
        .last_body_tokens = last_body.?,
        .last_body_read = last_read,
        .last_body_dml = last_dml,
        .items = owned_items,
        .count = count,
        .recursive = ast.cte_recursive,
    };
}

fn deinitGeneratedDmlCteItems(alloc: std.mem.Allocator, items: []GeneratedSqlDmlCteItemAst) void {
    for (items) |*item| item.deinit(alloc);
}

fn buildDataModifyingCteBodyDmlAstAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
) anyerror!?*GeneratedSqlDmlAst {
    if (tokens.len == 0) return null;
    const kind: GeneratedSqlDmlKind = if (tokens[0].matchesKeywordTag(.update))
        .update
    else if (tokens[0].matchesKeywordTag(.delete))
        .delete
    else
        return null;
    const child = try alloc.create(GeneratedSqlDmlAst);
    errdefer alloc.destroy(child);
    try buildDmlAstInPlace(
        alloc,
        tokens,
        0,
        tokens.len,
        kind,
        .{ .start = tokens[0].source_start, .end = tokens[tokens.len - 1].source_end },
        tokens[0].sourceSpan(),
        child,
    );
    return child;
}

fn buildDmlChildReadAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    ast: *GeneratedSqlDmlAst,
) !void {
    const source_tokens = ast.source_tokens orelse return;
    if (source_tokens.start >= source_tokens.end or source_tokens.end > tokens.len) return;
    switch (ast.kind) {
        .insert_select => try buildDmlSelectSourceReadAst(alloc, tokens, ast, source_tokens),
        .update, .delete, .merge => try buildDmlRelationSourceReadAst(alloc, tokens, ast, source_tokens),
        else => {},
    }
}

fn buildDmlSelectSourceReadAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    ast: *GeneratedSqlDmlAst,
    source_tokens: GeneratedSqlTokenRange,
) !void {
    ast.source_read = try buildDmlReadBodyMetadata(alloc, tokens, source_tokens) orelse return;
}

fn buildDmlReadBodyMetadata(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    source_tokens: GeneratedSqlTokenRange,
) !?GeneratedSqlDmlReadBodyAst {
    if (source_tokens.start >= source_tokens.end or source_tokens.end > tokens.len) return null;
    if (!tokens[source_tokens.start].matchesKeywordTag(.select)) return null;
    const statement_span = sourceSpanForTokenRange(tokens, source_tokens) orelse return null;
    var read_body = GeneratedSqlDmlReadBodyAst{
        .tokens = source_tokens,
        .kind = classifyReadKindInRange(tokens, source_tokens),
        .statement_span = statement_span,
        .command_span = tokens[source_tokens.start].sourceSpan(),
    };
    errdefer read_body.deinit(alloc);
    read_body.read_ast = try buildGeneratedReadAstForRangeAlloc(alloc, tokens, source_tokens);
    const body_end = firstTopLevelSetOperation(tokens, source_tokens.start + 1, source_tokens.end) orelse source_tokens.end;
    if (body_end < source_tokens.end) {
        const set_operation_tail_start = generatedSetOperationResultTailStart(tokens, .{ .start = body_end, .end = source_tokens.end }) orelse source_tokens.end;
        read_body.set_operation_tokens = .{ .start = body_end, .end = set_operation_tail_start };
    }
    var distinct_tokens: ?GeneratedSqlTokenRange = null;
    const projection_start = generatedReadProjectionStartInRange(tokens, source_tokens.start, body_end, &distinct_tokens);
    const from_index = findTopLevelKeyword(tokens, projection_start, body_end, .from);
    const where_index = findTopLevelKeyword(tokens, projection_start, body_end, .where);
    const group_index = findTopLevelKeywordSequence(tokens, projection_start, body_end, .group, .by);
    const having_index = findTopLevelKeyword(tokens, projection_start, body_end, .having);
    const window_index = findTopLevelKeyword(tokens, projection_start, body_end, .window);
    const order_index = findTopLevelKeyword(tokens, projection_start, body_end, .order);
    const limit_index = findTopLevelKeyword(tokens, projection_start, body_end, .limit);
    const offset_index = findTopLevelKeyword(tokens, projection_start, body_end, .offset);
    const fetch_index = findTopLevelKeyword(tokens, projection_start, body_end, .fetch);
    const projection_end = firstOptionalIndex(&[_]?usize{ from_index, where_index, group_index, having_index, window_index, order_index, limit_index, offset_index, fetch_index }) orelse body_end;
    if (projection_start < projection_end) read_body.projection_tokens = .{ .start = projection_start, .end = projection_end };
    if (from_index) |idx| {
        const source_end = firstOptionalIndex(&[_]?usize{ where_index, group_index, having_index, window_index, order_index, limit_index, offset_index, fetch_index }) orelse body_end;
        if (idx + 1 < source_end) {
            read_body.source_tokens = .{ .start = idx + 1, .end = source_end };
            read_body.source_antfly_function_items = try buildGeneratedAntflyTableFunctionItemsAst(alloc, tokens, read_body.source_tokens.?);
            read_body.source_antfly_function_count = read_body.source_antfly_function_items.len;
            read_body.source_graph_function_items = try buildGeneratedGraphTableFunctionItemsAst(alloc, tokens, read_body.source_antfly_function_items);
            read_body.source_graph_function_count = read_body.source_graph_function_items.len;
        }
    }
    if (where_index) |idx| {
        const where_end = firstOptionalIndex(&[_]?usize{ group_index, having_index, window_index, order_index, limit_index, offset_index, fetch_index }) orelse body_end;
        if (idx + 1 < where_end) read_body.where_tokens = .{ .start = idx + 1, .end = where_end };
    }
    buildDmlReadBodySingleSourceAst(tokens, &read_body);
    return read_body;
}

fn buildGeneratedReadAstForRangeAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) anyerror!*GeneratedSqlReadAst {
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    const child_tokens = tokens[range.start..range.end];
    const child_end = child_tokens.len;
    const select_index = findTopLevelKeyword(child_tokens, 0, child_end, .select) orelse return error.UnsupportedSqlShape;
    if (select_index != 0 and !child_tokens[0].matchesKeywordTag(.with)) return error.UnsupportedSqlShape;
    const statement_span = sourceSpanForTokenRange(tokens, range) orelse return error.UnsupportedSqlShape;
    const read = try alloc.create(GeneratedSqlReadAst);
    errdefer alloc.destroy(read);
    try buildReadAstInPlace(
        alloc,
        child_tokens,
        child_end,
        classifyReadKindInRange(child_tokens, .{ .start = 0, .end = child_end }),
        statement_span,
        child_tokens[select_index].sourceSpan(),
        read,
    );
    return read;
}

fn buildGeneratedReadAstForFlattenedRangesAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    ranges: []const GeneratedSqlTokenRange,
) anyerror!*GeneratedSqlReadAst {
    var total: usize = 0;
    for (ranges) |range| {
        if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
        total += range.end - range.start;
    }
    if (total == 0) return error.UnsupportedSqlShape;
    const flattened = try alloc.alloc(token_mod.Token, total);
    defer alloc.free(flattened);
    var index: usize = 0;
    for (ranges) |range| {
        for (tokens[range.start..range.end]) |token| {
            flattened[index] = token;
            index += 1;
        }
    }
    return try buildGeneratedReadAstForRangeAlloc(alloc, flattened, .{ .start = 0, .end = flattened.len });
}

pub fn cloneGeneratedDdlAstPtrAlloc(
    alloc: std.mem.Allocator,
    ddl: *const GeneratedSqlDdlAst,
    token_count: usize,
) anyerror!*GeneratedSqlDdlAst {
    const cloned = try alloc.create(GeneratedSqlDdlAst);
    errdefer alloc.destroy(cloned);
    cloned.* = try cloneRebasedGeneratedDdlAstAlloc(alloc, ddl.*, 0, token_count);
    return cloned;
}

