    for (calls, cloned) |call, *out| {
        out.* = .{
            .routine_name = try alloc.dupe(u8, call.routine_name),
            .argument_json = try cloneGeneratedStringSliceAlloc(alloc, call.argument_json),
        };
        initialized += 1;
    }
    return cloned;
}

