const GeneratedReadSourceAlias = struct {
    alias_tokens: GeneratedSqlTokenRange,
    alias_name_tokens: GeneratedSqlTokenRange,
    end: usize,
};

fn generatedReadSourceAlias(tokens: []const token_mod.Token, start: usize, end: usize) ?GeneratedReadSourceAlias {
    if (start >= end or end > tokens.len) return null;
    if (start + 1 < end and tokens[start].matchesKeywordTag(.as) and tokens[start + 1].kind == .identifier) {
        return .{
            .alias_tokens = .{ .start = start, .end = start + 2 },
            .alias_name_tokens = .{ .start = start + 1, .end = start + 2 },
            .end = start + 2,
        };
    }
    if (tokens[start].kind == .identifier and !generatedReadSourceTailKeyword(tokens, start)) {
        const alias_tokens = GeneratedSqlTokenRange{ .start = start, .end = start + 1 };
        return .{
            .alias_tokens = alias_tokens,
            .alias_name_tokens = alias_tokens,
            .end = start + 1,
        };
    }
    return null;
}

fn generatedReadSourceTailKeyword(tokens: []const token_mod.Token, index: usize) bool {
    if (index >= tokens.len) return false;
    const token = tokens[index];
    return token.matchesKeywordTag(.left) or
        token.matchesKeywordTag(.outer) or
        token.matchesKeywordTag(.inner) or
        token.matchesKeywordTag(.join) or
        token.matchesKeywordTag(.on) or
        token.matchesKeywordTag(.where) or
        token.matchesKeywordTag(.group) or
        token.matchesKeywordTag(.having) or
        token.matchesKeywordTag(.window) or
        token.matchesKeywordTag(.order) or
        token.matchesKeywordTag(.limit) or
        token.matchesKeywordTag(.offset) or
        token.matchesKeywordTag(.fetch) or
        token.matchesKeywordTag(.@"for") or
        token.matchesKeywordTag(.@"union") or
        token.matchesKeywordTag(.intersect) or
        token.matchesKeywordTag(.except);
}

fn buildGeneratedJoinItemsAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    source_tokens: GeneratedSqlTokenRange,
) ![]GeneratedSqlJoinAst {
    var items: std.ArrayListUnmanaged(GeneratedSqlJoinAst) = .empty;
    var items_owned = false;
    defer if (!items_owned) {
        for (items.items) |*item| item.deinit(alloc);
        items.deinit(alloc);
    };

    var scan = source_tokens.start;
    while (findTopLevelKeyword(tokens, scan, source_tokens.end, .join)) |join_index| {
        const operator = generatedJoinOperator(tokens, source_tokens, join_index) orelse return &.{};
        const conditionless = operator.kind == .cross or operator.kind == .natural;
        const condition = if (conditionless) null else generatedJoinCondition(tokens, source_tokens, join_index + 1, source_tokens.end);
        if (condition == null and !conditionless) return &.{};

        const next_join_scan = if (condition) |matched_condition| matched_condition.end else join_index + 1;
        const next_join_index = findTopLevelKeyword(tokens, next_join_scan, source_tokens.end, .join);
        const item_end = if (next_join_index) |next_join|
            (generatedJoinOperator(tokens, source_tokens, next_join) orelse return &.{}).tokens.start
        else if (condition) |matched_condition| matched_condition.end else source_tokens.end;
        const right_end = if (condition) |matched_condition| matched_condition.keyword_index else item_end;
        if (source_tokens.start >= operator.tokens.start or join_index + 1 >= right_end) return &.{};

        try items.ensureUnusedCapacity(alloc, 1);
        const tree_index = items.items.len;
        var item = GeneratedSqlJoinAst{
            .tokens = .{ .start = source_tokens.start, .end = item_end },
            .operator_tokens = operator.tokens,
            .kind = operator.kind,
            .tree_index = tree_index,
            .tree_depth = tree_index + 1,
            .left_child_index = if (tree_index == 0) null else tree_index - 1,
            .left_tokens = .{ .start = source_tokens.start, .end = operator.tokens.start },
            .right_tokens = .{ .start = join_index + 1, .end = right_end },
            .condition_kind = if (condition) |matched_condition| matched_condition.kind else .none,
            .condition_tokens = if (condition) |matched_condition| matched_condition.tokens else .{ .start = item_end, .end = item_end },
        };
        buildGeneratedJoinSideSourceAst(tokens, item.left_tokens, .left, &item);
        buildGeneratedJoinSideSourceAst(tokens, item.right_tokens, .right, &item);
        try buildGeneratedJoinRightLateralSubqueryAst(alloc, tokens, &item);
        try buildGeneratedJoinRightLateralUnnestAst(alloc, tokens, &item);
        switch (item.condition_kind) {
            .none => {},
            .on => {
                const matched_condition = condition.?;
                item.predicate_tokens = matched_condition.body_tokens;
                try buildGeneratedExpressionAstInto(alloc, tokens, matched_condition.body_tokens, &item.predicate_expression);
            },
            .using => {
                const matched_condition = condition.?;
                item.using_tokens = matched_condition.tokens;
                item.using_column_tokens = matched_condition.body_tokens;
                item.using_columns = try buildTopLevelListAst(alloc, tokens, matched_condition.body_tokens, .{});
            },
        }
        items.appendAssumeCapacity(item);

        scan = item_end;
        if (scan >= source_tokens.end) break;
    }

    if (items.items.len == 0) return &.{};
    const owned = try items.toOwnedSlice(alloc);
    items_owned = true;
    return owned;
}

fn buildGeneratedReadUnnestSourceAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    source_tokens: GeneratedSqlTokenRange,
    ast: *GeneratedSqlReadAst,
) !void {
    if (source_tokens.start >= source_tokens.end or source_tokens.end > tokens.len) return;
    if (ast.join_items.len != 0 or ast.source_antfly_function_items.len != 0) return;

    var depth: usize = 0;
    var comma_index: ?usize = null;
    var index = source_tokens.start;
    while (index < source_tokens.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return;
                depth -= 1;
            },
            .comma => if (depth == 0) {
                if (comma_index != null) return;
                comma_index = index;
            },
            else => {},
        }
    }
    if (depth != 0) return;
    const comma = comma_index orelse return;
    if (comma <= source_tokens.start or comma + 1 >= source_tokens.end) return;

    const left_source = GeneratedSqlTokenRange{ .start = source_tokens.start, .end = comma };
    var table_start = left_source.start;
    if (tokens[table_start].matchesKeywordTag(.only)) table_start += 1;
    const table_tokens = generatedSingleTokenRangeIfIdentifier(tokens, table_start, left_source.end) orelse return;
    var alias_tokens: ?GeneratedSqlTokenRange = null;
    var alias_name_tokens: ?GeneratedSqlTokenRange = null;
    var alias_end = table_tokens.end;
    if (generatedReadSourceAlias(tokens, table_tokens.end, left_source.end)) |alias| {
        alias_tokens = alias.alias_tokens;
        alias_name_tokens = alias.alias_name_tokens;
        alias_end = alias.end;
    }
    if (alias_end != left_source.end) return;

    const unnest_start = comma + 1;
    if (tokens[unnest_start].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens[unnest_start].text, "unnest")) return;
    if (unnest_start + 1 >= source_tokens.end or tokens[unnest_start + 1].kind != .lparen) return;
    const close = findMatchingParen(tokens, unnest_start + 1, source_tokens.end) orelse return;
    if (close <= unnest_start + 2 or close + 1 >= source_tokens.end) return;
    const alias = generatedReadSourceAlias(tokens, close + 1, source_tokens.end) orelse return;
    if (alias.end != source_tokens.end) return;

    const argument_tokens = GeneratedSqlTokenRange{ .start = unnest_start + 2, .end = close };
    ast.source_table_tokens = table_tokens;
    ast.source_alias_tokens = alias_tokens;
    ast.source_alias_name_tokens = alias_name_tokens;
    ast.source_unnest_tokens = .{ .start = unnest_start, .end = source_tokens.end };
    ast.source_unnest_name_tokens = .{ .start = unnest_start, .end = unnest_start + 1 };
    ast.source_unnest_argument_tokens = argument_tokens;
    ast.source_unnest_alias_tokens = alias.alias_tokens;
    ast.source_unnest_alias_name_tokens = alias.alias_name_tokens;
    try buildGeneratedExpressionAstInto(alloc, tokens, argument_tokens, &ast.source_unnest_argument_expression);
}

const GeneratedJoinSourceSide = enum { left, right };

fn buildGeneratedJoinSideSourceAst(
    tokens: []const token_mod.Token,
    source_tokens: GeneratedSqlTokenRange,
    side: GeneratedJoinSourceSide,
    item: *GeneratedSqlJoinAst,
) void {
    if (source_tokens.start >= source_tokens.end or source_tokens.end > tokens.len) return;
    var table_start = source_tokens.start;
    if (tokens[table_start].matchesKeywordTag(.only)) table_start += 1;
    const table_tokens = generatedSingleTokenRangeIfIdentifier(tokens, table_start, source_tokens.end) orelse return;
    var alias_tokens: ?GeneratedSqlTokenRange = null;
    var alias_name_tokens: ?GeneratedSqlTokenRange = null;
    var alias_end = table_tokens.end;
    if (generatedReadSourceAlias(tokens, table_tokens.end, source_tokens.end)) |alias| {
        alias_tokens = alias.alias_tokens;
        alias_name_tokens = alias.alias_name_tokens;
        alias_end = alias.end;
    }
    if (alias_end != source_tokens.end) return;
    switch (side) {
        .left => {
            item.left_table_tokens = table_tokens;
            item.left_alias_tokens = alias_tokens;
            item.left_alias_name_tokens = alias_name_tokens;
        },
        .right => {
            item.right_table_tokens = table_tokens;
            item.right_alias_tokens = alias_tokens;
            item.right_alias_name_tokens = alias_name_tokens;
        },
    }
}

fn buildGeneratedJoinRightLateralSubqueryAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    item: *GeneratedSqlJoinAst,
) anyerror!void {
    const right = item.right_tokens;
    if (right.start + 4 > right.end or right.end > tokens.len) return;
    if (!tokens[right.start].matchesKeywordTag(.lateral) or tokens[right.start + 1].kind != .lparen) return;
    const close_index = findMatchingParen(tokens, right.start + 1, right.end) orelse return;
    if (close_index + 1 >= right.end) return;
    const alias = generatedReadSourceAlias(tokens, close_index + 1, right.end) orelse return;
    if (alias.end != right.end) return;
    const body = GeneratedSqlTokenRange{ .start = right.start + 2, .end = close_index };
    if (body.start >= body.end) return;
    const child_tokens = tokens[body.start..body.end];
    const child_end = child_tokens.len;
    const child_select_index = findTopLevelKeyword(child_tokens, 0, child_end, .select) orelse return;
    const statement_span = sourceSpanForTokenRange(tokens, body) orelse return;
    const child = try alloc.create(GeneratedSqlReadAst);
    errdefer alloc.destroy(child);
    try buildReadAstInPlace(
        alloc,
        child_tokens,
        child_end,
        classifyReadKindInRange(child_tokens, .{ .start = 0, .end = child_end }),
        statement_span,
        child_tokens[child_select_index].sourceSpan(),
        child,
    );
    item.right_lateral_subquery_tokens = body;
    item.right_lateral_subquery_read_ast = child;
    item.right_lateral_alias_tokens = alias.alias_tokens;
    item.right_lateral_alias_name_tokens = alias.alias_name_tokens;
}

fn buildGeneratedJoinRightLateralUnnestAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    item: *GeneratedSqlJoinAst,
) anyerror!void {
    const right = item.right_tokens;
    if (right.start + 5 > right.end or right.end > tokens.len) return;
    if (!tokens[right.start].matchesKeywordTag(.lateral)) return;
    const unnest_start = right.start + 1;
    if (tokens[unnest_start].kind != .identifier or !std.ascii.eqlIgnoreCase(tokens[unnest_start].text, "unnest")) return;
    if (unnest_start + 1 >= right.end or tokens[unnest_start + 1].kind != .lparen) return;
    const close = findMatchingParen(tokens, unnest_start + 1, right.end) orelse return;
    if (close <= unnest_start + 2 or close + 1 >= right.end) return;
    const alias = generatedReadSourceAlias(tokens, close + 1, right.end) orelse return;
    if (alias.end != right.end) return;

    const argument_tokens = GeneratedSqlTokenRange{ .start = unnest_start + 2, .end = close };
    item.right_lateral_unnest_tokens = .{ .start = unnest_start, .end = right.end };
    item.right_lateral_unnest_name_tokens = .{ .start = unnest_start, .end = unnest_start + 1 };
    item.right_lateral_unnest_argument_tokens = argument_tokens;
    item.right_lateral_unnest_alias_tokens = alias.alias_tokens;
    item.right_lateral_unnest_alias_name_tokens = alias.alias_name_tokens;
    try buildGeneratedExpressionAstInto(alloc, tokens, argument_tokens, &item.right_lateral_unnest_argument_expression);
}

const GeneratedJoinCondition = struct {
    kind: GeneratedSqlJoinConditionKind,
    keyword_index: usize,
    tokens: GeneratedSqlTokenRange,
    body_tokens: GeneratedSqlTokenRange,
    end: usize,
};

fn generatedJoinCondition(tokens: []const token_mod.Token, source_tokens: GeneratedSqlTokenRange, start: usize, end: usize) ?GeneratedJoinCondition {
    const on_index = findTopLevelKeyword(tokens, start, end, .on);
    const using_index = findTopLevelKeyword(tokens, start, end, .using);
    const condition_index = blk: {
        if (on_index) |on| {
            if (using_index) |using| break :blk if (on < using) on else using;
            break :blk on;
        }
        break :blk using_index orelse return null;
    };
    if (tokens[condition_index].matchesKeywordTag(.on)) {
        const next_join_index = findTopLevelKeyword(tokens, condition_index + 1, end, .join);
        const condition_end = if (next_join_index) |next_join|
            (generatedJoinOperator(tokens, source_tokens, next_join) orelse return null).tokens.start
        else
            end;
        if (condition_index + 1 >= condition_end) return null;
        return .{
            .kind = .on,
            .keyword_index = condition_index,
            .tokens = .{ .start = condition_index, .end = condition_end },
            .body_tokens = .{ .start = condition_index + 1, .end = condition_end },
            .end = condition_end,
        };
    }
    if (condition_index + 2 >= end or tokens[condition_index + 1].kind != .lparen) return null;
    const close = findMatchingParen(tokens, condition_index + 1, end) orelse return null;
    if (condition_index + 2 >= close) return null;
    return .{
        .kind = .using,
        .keyword_index = condition_index,
        .tokens = .{ .start = condition_index, .end = close + 1 },
        .body_tokens = .{ .start = condition_index + 2, .end = close },
        .end = close + 1,
    };
}

const GeneratedJoinOperator = struct {
    tokens: GeneratedSqlTokenRange,
    kind: GeneratedSqlJoinKind,
};

fn generatedJoinOperator(tokens: []const token_mod.Token, source_tokens: GeneratedSqlTokenRange, join_index: usize) ?GeneratedJoinOperator {
    if (join_index >= source_tokens.end or !tokens[join_index].matchesKeywordTag(.join)) return null;
    if (join_index >= source_tokens.start + 1) {
        if (tokens[join_index - 1].matchesKeywordTag(.cross)) return .{
            .tokens = .{ .start = join_index - 1, .end = join_index + 1 },
            .kind = .cross,
        };
        if (tokens[join_index - 1].matchesKeywordTag(.natural)) return .{
            .tokens = .{ .start = join_index - 1, .end = join_index + 1 },
            .kind = .natural,
        };
    }
    if (join_index >= source_tokens.start + 2 and tokens[join_index - 1].matchesKeywordTag(.outer)) {
        if (tokens[join_index - 2].matchesKeywordTag(.left)) return .{
            .tokens = .{ .start = join_index - 2, .end = join_index + 1 },
            .kind = .left,
        };
        if (tokens[join_index - 2].matchesKeywordTag(.right)) return .{
            .tokens = .{ .start = join_index - 2, .end = join_index + 1 },
            .kind = .right,
        };
        if (tokens[join_index - 2].matchesKeywordTag(.full)) return .{
            .tokens = .{ .start = join_index - 2, .end = join_index + 1 },
            .kind = .full,
        };
    }
    if (join_index >= source_tokens.start + 1) {
        if (tokens[join_index - 1].matchesKeywordTag(.inner)) return .{
            .tokens = .{ .start = join_index - 1, .end = join_index + 1 },
            .kind = .inner,
        };
        if (tokens[join_index - 1].matchesKeywordTag(.left)) return .{
            .tokens = .{ .start = join_index - 1, .end = join_index + 1 },
            .kind = .left,
        };
        if (tokens[join_index - 1].matchesKeywordTag(.right)) return .{
            .tokens = .{ .start = join_index - 1, .end = join_index + 1 },
            .kind = .right,
        };
        if (tokens[join_index - 1].matchesKeywordTag(.full)) return .{
            .tokens = .{ .start = join_index - 1, .end = join_index + 1 },
            .kind = .full,
        };
    }
    return .{
        .tokens = .{ .start = join_index, .end = join_index + 1 },
        .kind = .inner,
    };
}

fn setGeneratedDmlReturningAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    returning_index: usize,
    end: usize,
    ast: *GeneratedSqlDmlAst,
) !void {
    if (returning_index + 1 >= end) return;
    const returning_tokens = GeneratedSqlTokenRange{ .start = returning_index + 1, .end = end };
    ast.returning_tokens = returning_tokens;
    ast.returning_items = try buildTopLevelListAst(alloc, tokens, returning_tokens, .{ .bare_alias = true });
}

fn setGeneratedDmlConflictAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    conflict_index: usize,
    conflict_end: usize,
    ast: *GeneratedSqlDmlAst,
) !void {
    if (conflict_index + 1 >= conflict_end or !tokens[conflict_index].matchesKeywordTag(.on) or !tokens[conflict_index + 1].matchesKeywordTag(.conflict)) return;
    ast.conflict_tokens = .{ .start = conflict_index + 1, .end = conflict_end };
    var cursor = conflict_index + 2;

    if (cursor < conflict_end and tokens[cursor].kind == .lparen) {
        if (findMatchingParen(tokens, cursor, conflict_end)) |close| {
            ast.conflict_target_tokens = .{ .start = cursor, .end = close + 1 };
            ast.conflict_target_kind = .inference;
            if (cursor + 1 < close) {
                ast.conflict_target_items = try buildTopLevelListAst(alloc, tokens, .{ .start = cursor + 1, .end = close }, .{});
            }
            cursor = close + 1;
        } else return;
    } else if (cursor + 2 < conflict_end and tokens[cursor].matchesKeywordTag(.on) and tokens[cursor + 1].matchesKeywordTag(.constraint) and tokens[cursor + 2].kind == .identifier) {
        ast.conflict_target_tokens = .{ .start = cursor, .end = cursor + 3 };
        ast.conflict_target_kind = .constraint;
        cursor += 3;
    } else {
        ast.conflict_target_kind = .targetless;
    }

    if (cursor < conflict_end and tokens[cursor].matchesKeywordTag(.where)) {
        const do_index = findTopLevelKeyword(tokens, cursor + 1, conflict_end, .do) orelse return;
        if (cursor + 1 < do_index) {
            ast.conflict_target_where_tokens = .{ .start = cursor + 1, .end = do_index };
            try buildGeneratedExpressionAstInPlace(alloc, tokens, ast.conflict_target_where_tokens.?, &ast.conflict_target_where_expression);
        }
        cursor = do_index;
    }
    if (cursor >= conflict_end or !tokens[cursor].matchesKeywordTag(.do) or cursor + 1 >= conflict_end) return;

    ast.conflict_action_tokens = .{ .start = cursor + 1, .end = conflict_end };
    if (tokens[cursor + 1].matchesKeywordTag(.nothing)) {
        ast.conflict_action_kind = .nothing;
    } else if (tokens[cursor + 1].matchesKeywordTag(.update) and cursor + 3 <= conflict_end and tokens[cursor + 2].matchesKeywordTag(.set)) {
        ast.conflict_action_kind = .update;
        const assignments_start = cursor + 3;
        const where_index = findTopLevelKeyword(tokens, assignments_start, conflict_end, .where);
        const assignments_end = where_index orelse conflict_end;
        if (assignments_start < assignments_end) {
            ast.conflict_assignments_tokens = .{ .start = assignments_start, .end = assignments_end };
            ast.conflict_assignment_items = try buildTopLevelListAst(alloc, tokens, ast.conflict_assignments_tokens.?, .{ .assignment_items = true });
        }
        if (where_index) |idx| {
            if (idx + 1 < conflict_end) {
                ast.conflict_action_where_tokens = .{ .start = idx + 1, .end = conflict_end };
                try buildGeneratedExpressionAstInPlace(alloc, tokens, ast.conflict_action_where_tokens.?, &ast.conflict_action_where_expression);
            }
        }
    }
}

fn buildInsertDmlAst(alloc: std.mem.Allocator, tokens: []const token_mod.Token, start: usize, end: usize, ast: *GeneratedSqlDmlAst) !void {
    if (start + 3 >= end or !tokens[start + 1].matchesKeywordTag(.into)) return;
    var target_index: usize = start + 2;
    if (target_index < end and tokens[target_index].matchesKeywordTag(.only)) target_index += 1;
    ast.target_table_tokens = generatedSingleTokenRangeIfIdentifier(tokens, target_index, end);
    var index: usize = if (ast.target_table_tokens) |target| target.end else start + 3;
    if (generatedDmlTargetAlias(tokens, index, end)) |alias| {
        ast.target_alias_tokens = alias.alias_tokens;
        ast.target_alias_name_tokens = alias.alias_name_tokens;
        index = alias.end;
    }
    if (index + 1 < end and tokens[index].matchesKeywordTag(.default) and tokens[index + 1].matchesKeywordTag(.values)) {
        ast.default_values = true;
        const conflict_index = findTopLevelInsertConflictKeyword(tokens, index + 2, end);
        const returning_index = findTopLevelKeyword(tokens, index + 2, end, .returning) orelse end;
        if (conflict_index) |idx| {
            const conflict_end = if (returning_index < end) returning_index else end;
            try setGeneratedDmlConflictAst(alloc, tokens, idx, conflict_end, ast);
        }
        if (returning_index < end) try setGeneratedDmlReturningAst(alloc, tokens, returning_index, end, ast);
        return;
    }
    if (index < end and tokens[index].kind == .lparen) {
        if (findMatchingParen(tokens, index, end)) |close| {
            ast.insert_columns_tokens = .{ .start = index, .end = close + 1 };
            if (index + 1 < close) {
                ast.insert_column_items = try buildTopLevelListAst(alloc, tokens, .{ .start = index + 1, .end = close }, .{});
            }
            index = close + 1;
        }
    }
    if (findTopLevelKeyword(tokens, index, end, .values)) |values_index| {
        const conflict_index = findTopLevelInsertConflictKeyword(tokens, values_index + 1, end);
        const returning_index = findTopLevelKeyword(tokens, values_index + 1, end, .returning) orelse end;
        const values_end = conflict_index orelse returning_index;
        ast.values_tokens = .{ .start = values_index + 1, .end = values_end };
        ast.insert_value_rows = try buildTopLevelListAst(alloc, tokens, ast.values_tokens.?, .{});
        try populateGeneratedInsertValueRowArgumentItems(alloc, tokens, &ast.insert_value_rows);
        if (conflict_index) |idx| {
            const conflict_end = if (returning_index < end) returning_index else end;
            try setGeneratedDmlConflictAst(alloc, tokens, idx, conflict_end, ast);
        }
        if (returning_index < end) try setGeneratedDmlReturningAst(alloc, tokens, returning_index, end, ast);
    } else if (findTopLevelKeyword(tokens, index, end, .select)) |select_index| {
        const conflict_index = findTopLevelInsertConflictKeyword(tokens, select_index + 1, end);
        const returning_index = findTopLevelKeyword(tokens, select_index + 1, end, .returning) orelse end;
        const source_end = conflict_index orelse returning_index;
        ast.source_tokens = .{ .start = select_index, .end = source_end };
        if (conflict_index) |idx| {
            const conflict_end = if (returning_index < end) returning_index else end;
            try setGeneratedDmlConflictAst(alloc, tokens, idx, conflict_end, ast);
        }
        if (returning_index < end) try setGeneratedDmlReturningAst(alloc, tokens, returning_index, end, ast);
    }
}

fn buildUpdateDmlAst(alloc: std.mem.Allocator, tokens: []const token_mod.Token, start: usize, end: usize, ast: *GeneratedSqlDmlAst) !void {
    var target_index: usize = start + 1;
    if (target_index < end and tokens[target_index].matchesKeywordTag(.only)) target_index += 1;
    ast.target_table_tokens = generatedSingleTokenRangeIfIdentifier(tokens, target_index, end);
    var search_start: usize = if (ast.target_table_tokens) |target| target.end else start + 2;
    if (generatedDmlTargetAlias(tokens, search_start, end)) |alias| {
        ast.target_alias_tokens = alias.alias_tokens;
        ast.target_alias_name_tokens = alias.alias_name_tokens;
        search_start = alias.end;
    }
    const set_index = findTopLevelKeyword(tokens, search_start, end, .set) orelse return;
    const from_index = findTopLevelKeyword(tokens, set_index + 1, end, .from);
    const where_index = findTopLevelKeyword(tokens, set_index + 1, end, .where);
    const returning_index = findTopLevelKeyword(tokens, set_index + 1, end, .returning);
    const tail_end = returning_index orelse end;
    const order_index = findTopLevelKeyword(tokens, set_index + 1, tail_end, .order);
    const limit_index = findTopLevelKeyword(tokens, set_index + 1, tail_end, .limit);
    const offset_index = findTopLevelKeyword(tokens, set_index + 1, tail_end, .offset);
    const fetch_index = findTopLevelKeyword(tokens, set_index + 1, tail_end, .fetch);
    const row_lock_index = generatedDmlRowLockStart(tokens, set_index + 1, tail_end);
    const first_tail_index = firstOptionalIndex(&[_]?usize{ order_index, limit_index, offset_index, fetch_index, row_lock_index });
    const assignments_end = firstOptionalIndex(&[_]?usize{ from_index, where_index, first_tail_index, returning_index }) orelse end;
    if (set_index + 1 < assignments_end) {
        ast.assignments_tokens = .{ .start = set_index + 1, .end = assignments_end };
        ast.assignment_items = try buildTopLevelListAst(alloc, tokens, ast.assignments_tokens.?, .{ .assignment_items = true });
    }
    ast.mutation_source_tail = statementHasForPortionBeforeKeyword(tokens, search_start, set_index) or statementHasMutationSourceTail(tokens, set_index + 1, end);
    if (first_tail_index) |tail_index| try buildGeneratedDmlMutationTailAst(alloc, tokens, tail_index, tail_end, ast);
    if (from_index) |idx| {
        const source_end = firstOptionalIndex(&[_]?usize{ where_index, first_tail_index, returning_index }) orelse end;
        if (idx + 1 < source_end) {
            ast.source_tokens = .{ .start = idx + 1, .end = source_end };
            ast.mutation_join_source = true;
        }
    }
    if (where_index) |idx| {
        const where_end = returning_index orelse end;
        const predicate_end = firstOptionalIndex(&[_]?usize{ first_tail_index, returning_index }) orelse end;
        if (idx + 1 < where_end) ast.where_tokens = .{ .start = idx + 1, .end = where_end };
        if (idx + 1 < predicate_end) {
            const where_expression_tokens = GeneratedSqlTokenRange{ .start = idx + 1, .end = predicate_end };
            try buildGeneratedExpressionAstInPlace(alloc, tokens, where_expression_tokens, &ast.where_expression);
        }
    }
    if (statementWhereSemijoinSourceTableTokens(tokens, set_index + 1, end)) |source_table| {
        ast.semijoin_source_table_tokens = source_table;
        ast.mutation_join_source = true;
    }
    if (returning_index) |idx| {
        try setGeneratedDmlReturningAst(alloc, tokens, idx, end, ast);
    }
}

fn buildDeleteDmlAst(alloc: std.mem.Allocator, tokens: []const token_mod.Token, start: usize, end: usize, ast: *GeneratedSqlDmlAst) !void {
    if (start + 2 >= end or !tokens[start + 1].matchesKeywordTag(.from)) return;
    var target_index = start + 2;
    if (target_index < end and tokens[target_index].matchesKeywordTag(.only)) target_index += 1;
    ast.target_table_tokens = generatedSingleTokenRangeIfIdentifier(tokens, target_index, end);
    var scan_start = if (ast.target_table_tokens) |target| target.end else target_index;
    if (generatedDmlTargetAlias(tokens, scan_start, end)) |alias| {
        ast.target_alias_tokens = alias.alias_tokens;
        ast.target_alias_name_tokens = alias.alias_name_tokens;
        scan_start = alias.end;
    }
    const using_index = findTopLevelKeyword(tokens, scan_start, end, .using);
    const where_index = findTopLevelKeyword(tokens, scan_start, end, .where);
    const returning_index = findTopLevelKeyword(tokens, scan_start, end, .returning);
    const tail_end = returning_index orelse end;
    const order_index = findTopLevelKeyword(tokens, scan_start, tail_end, .order);
    const limit_index = findTopLevelKeyword(tokens, scan_start, tail_end, .limit);
    const offset_index = findTopLevelKeyword(tokens, scan_start, tail_end, .offset);
    const fetch_index = findTopLevelKeyword(tokens, scan_start, tail_end, .fetch);
    const row_lock_index = generatedDmlRowLockStart(tokens, scan_start, tail_end);
    const first_tail_index = firstOptionalIndex(&[_]?usize{ order_index, limit_index, offset_index, fetch_index, row_lock_index });
    ast.mutation_source_tail =
        statementHasForPortionBeforeKeyword(tokens, scan_start, minOptionalIndex(where_index, returning_index) orelse end) or
        statementHasMutationSourceTail(tokens, scan_start, end);
    if (first_tail_index) |tail_index| try buildGeneratedDmlMutationTailAst(alloc, tokens, tail_index, tail_end, ast);
    if (using_index) |idx| {
        const source_end = firstOptionalIndex(&[_]?usize{ where_index, first_tail_index, returning_index }) orelse end;
        if (idx + 1 < source_end) {
            ast.source_tokens = .{ .start = idx + 1, .end = source_end };
            ast.mutation_join_source = true;
        }
    }
    if (where_index) |idx| {
        const where_end = returning_index orelse end;
        const predicate_end = firstOptionalIndex(&[_]?usize{ first_tail_index, returning_index }) orelse end;
        if (idx + 1 < where_end) ast.where_tokens = .{ .start = idx + 1, .end = where_end };
        if (idx + 1 < predicate_end) {
            const where_expression_tokens = GeneratedSqlTokenRange{ .start = idx + 1, .end = predicate_end };
            try buildGeneratedExpressionAstInPlace(alloc, tokens, where_expression_tokens, &ast.where_expression);
        }
    }
    if (statementWhereSemijoinSourceTableTokens(tokens, scan_start, end)) |source_table| {
        ast.semijoin_source_table_tokens = source_table;
        ast.mutation_join_source = true;
    }
    if (returning_index) |idx| {
        try setGeneratedDmlReturningAst(alloc, tokens, idx, end, ast);
    }
}

fn buildTruncateDmlAst(alloc: std.mem.Allocator, tokens: []const token_mod.Token, start: usize, end: usize, ast: *GeneratedSqlDmlAst) !void {
    var index: usize = start + 1;
    if (index < end and tokens[index].matchesKeywordTag(.table)) index += 1;
    if (index < end and tokens[index].matchesKeywordTag(.only)) index += 1;
    ast.target_table_tokens = generatedSingleTokenRangeIfIdentifier(tokens, index, end);
    if (ast.target_table_tokens) |target| index = target.end;

    const option_index = firstTopLevelTruncateOption(tokens, index, end) orelse end;
    if (index < option_index and tokens[index].kind == .comma) {
        ast.additional_target_tokens = .{ .start = index, .end = option_index };
        ast.additional_target_items = try buildTopLevelListAst(alloc, tokens, ast.additional_target_tokens.?, .{});
    }
    ast.restart_identity = generatedTruncateHasRestartIdentity(tokens, option_index, end);
    ast.cascade = findTopLevelKeyword(tokens, option_index, end, .cascade) != null;
}

fn buildMergeDmlAst(alloc: std.mem.Allocator, tokens: []const token_mod.Token, start: usize, end: usize, ast: *GeneratedSqlDmlAst) !void {
    if (start + 3 >= end or !tokens[start + 1].matchesKeywordTag(.into)) return;
    var target_index: usize = start + 2;
    if (target_index < end and tokens[target_index].matchesKeywordTag(.only)) target_index += 1;
    ast.target_table_tokens = generatedSingleTokenRangeIfIdentifier(tokens, target_index, end);
    var search_start: usize = if (ast.target_table_tokens) |target| target.end else start + 3;
    if (generatedDmlTargetAlias(tokens, search_start, end)) |alias| {
        ast.target_alias_tokens = alias.alias_tokens;
        ast.target_alias_name_tokens = alias.alias_name_tokens;
        search_start = alias.end;
    }
    if (findTopLevelKeyword(tokens, search_start, end, .using)) |using_index| {
        const on_index = findTopLevelKeyword(tokens, using_index + 1, end, .on) orelse end;
        if (using_index + 1 < on_index) ast.source_tokens = .{ .start = using_index + 1, .end = on_index };
        if (on_index + 1 < end) ast.where_tokens = .{ .start = on_index + 1, .end = end };
        const returning_index = findTopLevelKeyword(tokens, on_index + 1, end, .returning);
        const merge_body_end = returning_index orelse end;
        if (findTopLevelKeyword(tokens, on_index + 1, merge_body_end, .when)) |first_when| {
            if (on_index + 1 < first_when) {
                try buildGeneratedExpressionAstInPlace(
                    alloc,
                    tokens,
                    .{ .start = on_index + 1, .end = first_when },
                    &ast.where_expression,
                );
            }
        }
        if (on_index + 1 < merge_body_end) try setGeneratedMergeArmsAst(alloc, tokens, on_index + 1, merge_body_end, ast);
        if (returning_index) |idx| {
            try setGeneratedDmlReturningAst(alloc, tokens, idx, end, ast);
        }
    }
}

fn setGeneratedMergeArmsAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    body_start: usize,
    body_end: usize,
    ast: *GeneratedSqlDmlAst,
) !void {
    const first_when = findTopLevelKeyword(tokens, body_start, body_end, .when) orelse return;
    var arms = std.ArrayListUnmanaged(GeneratedSqlMergeArmAst).empty;
    errdefer {
        for (arms.items) |*arm| arm.deinit(alloc);
        arms.deinit(alloc);
    }
    var cursor = first_when;
    while (cursor < body_end) {
        if (!tokens[cursor].matchesKeywordTag(.when)) return;
        const next_when = findTopLevelKeyword(tokens, cursor + 1, body_end, .when);
        const arm_end = next_when orelse body_end;
        var arm = (try buildGeneratedMergeArmAst(alloc, tokens, cursor, arm_end)) orelse return;
        var arm_transferred = false;
        errdefer if (!arm_transferred) arm.deinit(alloc);
        try arms.append(alloc, arm);
        arm_transferred = true;
        cursor = next_when orelse break;
    }
    const owned = try arms.toOwnedSlice(alloc);
    ast.merge_arms.items = owned;
    ast.merge_arms.count = owned.len;
    if (owned.len > 0) {
        ast.merge_arms.first_tokens = owned[0].tokens;
        ast.merge_arms.last_tokens = owned[owned.len - 1].tokens;
    }
    for (owned) |arm| {
        if (arm.matched) {
            ast.merge_arms.matched_count += 1;
        } else {
            ast.merge_arms.not_matched_count += 1;
        }
    }
}

fn buildGeneratedMergeArmAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    arm_start: usize,
    arm_end: usize,
) !?GeneratedSqlMergeArmAst {
    if (arm_start + 3 >= arm_end or !tokens[arm_start].matchesKeywordTag(.when)) return null;
    var cursor = arm_start + 1;
    const matched = if (tokens[cursor].matchesKeywordTag(.matched)) blk: {
        cursor += 1;
        break :blk true;
    } else blk: {
        if (cursor + 1 >= arm_end or !tokens[cursor].matchesKeywordTag(.not) or !tokens[cursor + 1].matchesKeywordTag(.matched)) return null;
        cursor += 2;
        break :blk false;
    };

    const then_index = findTopLevelKeyword(tokens, cursor, arm_end, .then) orelse return null;
    const predicate_tokens = if (cursor < then_index) blk: {
        if (!tokens[cursor].matchesKeywordTag(.@"and") or cursor + 1 >= then_index) return null;
        break :blk GeneratedSqlTokenRange{ .start = cursor + 1, .end = then_index };
    } else null;
    const action_start = then_index + 1;
    if (action_start >= arm_end) return null;
    var arm = GeneratedSqlMergeArmAst{
        .tokens = .{ .start = arm_start, .end = arm_end },
        .predicate_tokens = predicate_tokens,
        .action_tokens = .{ .start = action_start, .end = arm_end },
        .action_kind = .do_nothing,
        .matched = matched,
    };
    if (predicate_tokens) |range| {
        try buildGeneratedExpressionAstInto(alloc, tokens, range, &arm.predicate_expression);
    }
    if (tokens[action_start].matchesKeywordTag(.update)) {
        if (!matched or action_start + 2 >= arm_end or !tokens[action_start + 1].matchesKeywordTag(.set)) return null;
        arm.action_kind = .update;
        arm.assignments_tokens = .{ .start = action_start + 2, .end = arm_end };
        arm.assignment_items = try buildTopLevelListAst(alloc, tokens, arm.assignments_tokens.?, .{ .assignment_items = true });
        return arm;
    }
    if (tokens[action_start].matchesKeywordTag(.delete)) {
        if (!matched or action_start + 1 != arm_end) return null;
        arm.action_kind = .delete;
        return arm;
    }
    if (tokens[action_start].matchesKeywordTag(.do)) {
        if (action_start + 2 != arm_end or !tokens[action_start + 1].matchesKeywordTag(.nothing)) return null;
        arm.action_kind = .do_nothing;
        return arm;
    }
    if (tokens[action_start].matchesKeywordTag(.insert)) {
        if (matched) return null;
        arm.action_kind = .insert;
        var values_search_start = action_start + 1;
        if (values_search_start < arm_end and tokens[values_search_start].kind == .lparen) {
            const close = findMatchingParen(tokens, values_search_start, arm_end) orelse return null;
            arm.insert_columns_tokens = .{ .start = values_search_start, .end = close + 1 };
            if (values_search_start + 1 < close) {
                arm.insert_column_items = try buildTopLevelListAst(alloc, tokens, .{ .start = values_search_start + 1, .end = close }, .{});
            }
            values_search_start = close + 1;
        }
        const values_index = findTopLevelKeyword(tokens, values_search_start, arm_end, .values) orelse return null;
        if (values_index + 1 >= arm_end) return null;
        arm.insert_values_tokens = .{ .start = values_index + 1, .end = arm_end };
        if (tokens[values_index + 1].kind != .lparen) return null;
        const value_close = findMatchingParen(tokens, values_index + 1, arm_end) orelse return null;
        if (value_close + 1 != arm_end) return null;
        if (values_index + 2 < value_close) {
            arm.insert_value_items = try buildTopLevelListAst(alloc, tokens, .{ .start = values_index + 2, .end = value_close }, .{});
        }
        return arm;
    }
    return null;
}

const GeneratedDmlTargetAlias = struct {
    alias_tokens: GeneratedSqlTokenRange,
    alias_name_tokens: GeneratedSqlTokenRange,
    end: usize,
};

fn generatedDmlTargetAlias(tokens: []const token_mod.Token, start: usize, end: usize) ?GeneratedDmlTargetAlias {
    if (start >= end or end > tokens.len) return null;
    if (start + 1 < end and tokens[start].matchesKeywordTag(.as) and tokens[start + 1].kind == .identifier) {
        return .{
            .alias_tokens = .{ .start = start, .end = start + 2 },
            .alias_name_tokens = .{ .start = start + 1, .end = start + 2 },
            .end = start + 2,
        };
    }
    if (tokens[start].kind == .identifier and !generatedDmlTargetTailKeyword(tokens, start)) {
        const alias_tokens = GeneratedSqlTokenRange{ .start = start, .end = start + 1 };
        return .{
            .alias_tokens = alias_tokens,
            .alias_name_tokens = alias_tokens,
            .end = start + 1,
        };
    }
    return null;
}

fn generatedDmlTargetTailKeyword(tokens: []const token_mod.Token, index: usize) bool {
    if (index >= tokens.len) return false;
    const token = tokens[index];
    return token.matchesKeywordTag(.default) or
        token.matchesKeywordTag(.values) or
        token.matchesKeywordTag(.conflict) or
        token.matchesKeywordTag(.set) or
        token.matchesKeywordTag(.from) or
        token.matchesKeywordTag(.using) or
        token.matchesKeywordTag(.where) or
        token.matchesKeywordTag(.@"for") or
        token.matchesKeywordTag(.returning) or
        token.matchesKeywordTag(.order) or
        token.matchesKeywordTag(.limit) or
        token.matchesKeywordTag(.offset) or
        token.matchesKeywordTag(.fetch);
}

fn firstTopLevelTruncateOption(tokens: []const token_mod.Token, start: usize, end: usize) ?usize {
    var best: ?usize = null;
    const candidates = [_]token_mod.TokenKeyword{ .restart, .@"continue", .identity, .cascade, .restrict };
    for (candidates) |keyword| {
        if (findTopLevelKeyword(tokens, start, end, keyword)) |idx| {
            if (best == null or idx < best.?) best = idx;
        }
    }
    return best;
}

fn generatedTruncateHasRestartIdentity(tokens: []const token_mod.Token, start: usize, end: usize) bool {
    return start + 1 < end and
        tokens[start].matchesKeywordTag(.restart) and
        tokens[start + 1].matchesKeywordTag(.identity);
}

fn firstTopLevelSetOperation(tokens: []const token_mod.Token, start: usize, end: usize) ?usize {
    var best: ?usize = null;
    const candidates = [_]token_mod.TokenKeyword{ .@"union", .intersect, .except };
    for (candidates) |keyword| {
        if (findTopLevelKeyword(tokens, start, end, keyword)) |idx| {
            if (best == null or idx < best.?) best = idx;
        }
    }
    return best;
}

fn firstTopLevelKeywordIndex(tokens: []const token_mod.Token, start: usize, end: usize, keywords: []const token_mod.TokenKeyword) ?usize {
    var best: ?usize = null;
    for (keywords) |keyword| {
        if (findTopLevelKeyword(tokens, start, end, keyword)) |idx| {
            if (best == null or idx < best.?) best = idx;
        }
    }
    return best;
}

fn statementHasForPortionBeforeKeyword(tokens: []const token_mod.Token, start: usize, stop: usize) bool {
    var index = start;
    while (index + 1 < stop) : (index += 1) {
        if (tokens[index].matchesKeywordTag(.@"for") and tokens[index + 1].matchesKeywordTag(.portion)) return true;
    }
    return false;
}

fn statementHasMutationSourceTail(tokens: []const token_mod.Token, start: usize, end: usize) bool {
    if (firstTopLevelKeywordIndex(tokens, start, end, &.{ .order, .limit, .offset, .fetch }) != null) return true;
    var index = start;
    while (index + 1 < end) : (index += 1) {
        if (!tokens[index].matchesKeywordTag(.@"for")) continue;
        if (tokens[index + 1].matchesKeywordTag(.update) or
            tokens[index + 1].matchesKeywordTag(.no) or
            tokens[index + 1].matchesKeywordTag(.share) or
            tokens[index + 1].matchesKeywordTag(.key))
        {
            return true;
        }
    }
    return false;
}

fn statementWhereSemijoinSourceTableTokens(tokens: []const token_mod.Token, start: usize, end: usize) ?GeneratedSqlTokenRange {
    const where_index = findTopLevelKeyword(tokens, start, end, .where) orelse return null;
    const stop = firstTopLevelKeywordIndex(tokens, where_index + 1, end, &.{ .order, .limit, .offset, .fetch, .@"for", .returning }) orelse end;
    return tokenRangeSemijoinSourceTableTokens(tokens, where_index + 1, stop);
}

fn tokenRangeSemijoinSourceTableTokens(tokens: []const token_mod.Token, start: usize, end: usize) ?GeneratedSqlTokenRange {
    var depth: usize = 0;
    var index = start;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth > 0) depth -= 1;
            },
            .identifier => if (depth == 0) {
                if (tokens[index].matchesKeywordTag(.in) or tokens[index].matchesKeywordTag(.exists)) {
                    if (nextParenSelectSourceTableTokens(tokens, index + 1, end)) |source_table| return source_table;
                }
            },
            else => {},
        }
    }
    return null;
}

fn nextParenSelectSourceTableTokens(tokens: []const token_mod.Token, start: usize, end: usize) ?GeneratedSqlTokenRange {
    var index = start;
    while (index < end and tokens[index].kind == .comma) : (index += 1) {}
    if (index >= end or tokens[index].kind != .lparen) return null;
    if (index + 1 >= end or !tokens[index + 1].matchesKeywordTag(.select)) return null;
    const close_index = findMatchingParen(tokens, index, end) orelse return null;
    const from_index = findTopLevelKeyword(tokens, index + 2, close_index, .from) orelse return null;
    var source_index = from_index + 1;
    if (source_index < close_index and tokens[source_index].matchesKeywordTag(.only)) source_index += 1;
    return generatedSingleTokenRangeIfIdentifier(tokens, source_index, close_index);
}

fn consumeGeneratedIfNotExists(tokens: []const token_mod.Token, index: *usize, end: usize) bool {
    if (index.* + 2 >= end) return false;
    if (!tokens[index.*].matchesKeywordTag(.@"if") or
        !tokens[index.* + 1].matchesKeywordTag(.not) or
        !tokens[index.* + 2].matchesKeywordTag(.exists))
    {
        return false;
    }
    index.* += 3;
    return true;
}

fn consumeGeneratedIfExists(tokens: []const token_mod.Token, index: *usize, end: usize) bool {
    if (index.* + 1 >= end) return false;
    if (!tokens[index.*].matchesKeywordTag(.@"if") or
        !tokens[index.* + 1].matchesKeywordTag(.exists))
    {
        return false;
    }
    index.* += 2;
    return true;
}

fn generatedSingleTokenRangeIfIdentifier(tokens: []const token_mod.Token, index: usize, end: usize) ?GeneratedSqlTokenRange {
    if (index >= end or tokens[index].kind != .identifier) return null;
    return .{ .start = index, .end = index + 1 };
}

fn generatedQualifiedNameRange(tokens: []const token_mod.Token, index: usize, end: usize) ?GeneratedSqlTokenRange {
    return generatedSingleTokenRangeIfIdentifier(tokens, index, end);
}

fn generatedIdentifierNameRange(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedSqlTokenRange {
    if (range.start >= range.end or range.end > tokens.len) return null;
    var index = range.start;
    var last_identifier: ?GeneratedSqlTokenRange = null;
    while (index < range.end) {
        if (tokens[index].kind != .identifier) return null;
        last_identifier = .{ .start = index, .end = index + 1 };
        index += 1;
        if (index == range.end) return last_identifier;
        if (!tokens[index].matchesKeywordTag(.period)) return null;
        index += 1;
        if (index == range.end) return null;
    }
    return null;
}

fn generatedIdentifierIsQualified(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) bool {
    if (range.start >= range.end or range.end > tokens.len) return false;
    if (range.end == range.start + 1 and tokens[range.start].kind == .identifier) {
        return std.mem.indexOfScalar(u8, tokens[range.start].text, '.') != null;
    }
    var index = range.start;
    var saw_period = false;
    while (index < range.end) {
        if (tokens[index].kind != .identifier) return false;
        index += 1;
        if (index == range.end) return saw_period;
        if (!tokens[index].matchesKeywordTag(.period)) return false;
        saw_period = true;
        index += 1;
        if (index == range.end) return false;
    }
    return false;
}

const GeneratedSqlListOptions = struct {
    bare_alias: bool = false,
    order_modifiers: bool = false,
    index_collation_modifier: bool = false,
    assignment_items: bool = false,
};

fn buildTopLevelListAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
    options: GeneratedSqlListOptions,
) !GeneratedSqlListAst {
    var ast = GeneratedSqlListAst{};
    if (range.start >= range.end or range.end > tokens.len) return ast;

    var items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    errdefer items.deinit(alloc);
    var item_start = range.start;
    var depth: usize = 0;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) {
                    items.deinit(alloc);
                    return ast;
                }
                depth -= 1;
            },
            .comma => if (depth == 0) {
                try recordGeneratedListItem(alloc, &items, &ast, .{ .start = item_start, .end = index });
                item_start = index + 1;
            },
            else => {},
        }
    }
    try recordGeneratedListItem(alloc, &items, &ast, .{ .start = item_start, .end = range.end });
    ast.items = try items.toOwnedSlice(alloc);
    errdefer {
        alloc.free(ast.items);
        ast.items = &.{};
    }
    if (ast.items.len > 0) {
        ast.identifier_name_items = try alloc.alloc(?GeneratedSqlTokenRange, ast.items.len);
        errdefer {
            alloc.free(ast.identifier_name_items);
            ast.identifier_name_items = &.{};
        }
        ast.expression_items = try alloc.alloc(GeneratedSqlTokenRange, ast.items.len);
        errdefer {
            alloc.free(ast.expression_items);
            ast.expression_items = &.{};
        }
        ast.alias_items = try alloc.alloc(?GeneratedSqlTokenRange, ast.items.len);
        errdefer {
            alloc.free(ast.alias_items);
            ast.alias_items = &.{};
        }
        ast.alias_name_items = try alloc.alloc(?GeneratedSqlTokenRange, ast.items.len);
        errdefer {
            alloc.free(ast.alias_name_items);
            ast.alias_name_items = &.{};
        }
        ast.direction_items = try alloc.alloc(?GeneratedSqlTokenRange, ast.items.len);
        errdefer {
            alloc.free(ast.direction_items);
            ast.direction_items = &.{};
        }
        ast.directions = try alloc.alloc(?GeneratedSqlOrderDirection, ast.items.len);
        errdefer {
            alloc.free(ast.directions);
            ast.directions = &.{};
        }
        ast.order_using_operator_items = try alloc.alloc(?GeneratedSqlTokenRange, ast.items.len);
        errdefer {
            alloc.free(ast.order_using_operator_items);
            ast.order_using_operator_items = &.{};
        }
        ast.nulls_order_items = try alloc.alloc(?GeneratedSqlTokenRange, ast.items.len);
        errdefer {
            alloc.free(ast.nulls_order_items);
            ast.nulls_order_items = &.{};
        }
        ast.nulls_orders = try alloc.alloc(?GeneratedSqlNullsOrder, ast.items.len);
        errdefer {
            alloc.free(ast.nulls_orders);
            ast.nulls_orders = &.{};
        }
        for (ast.items, 0..) |item, item_index| {
            const aliased = generatedAliasedListItem(tokens, item, options);
            ast.identifier_name_items[item_index] = generatedIdentifierNameRange(tokens, aliased.expression_tokens);
            ast.expression_items[item_index] = aliased.expression_tokens;
            ast.alias_items[item_index] = aliased.alias_tokens;
            ast.alias_name_items[item_index] = aliased.alias_name_tokens;
            ast.direction_items[item_index] = aliased.direction_tokens;
            ast.directions[item_index] = aliased.direction;
            ast.order_using_operator_items[item_index] = aliased.order_using_operator_tokens;
            ast.nulls_order_items[item_index] = aliased.nulls_order_tokens;
            ast.nulls_orders[item_index] = aliased.nulls_order;
        }
        ast.expressions = try alloc.alloc(GeneratedSqlExpressionAst, ast.items.len);
        var expression_count: usize = 0;
        errdefer {
            for (ast.expressions[0..expression_count]) |*expression| expression.deinit(alloc);
            alloc.free(ast.expressions);
            ast.expressions = &.{};
        }
        for (ast.expression_items) |item| {
            if (options.assignment_items) {
                try buildGeneratedAssignmentExpressionAstInPlace(alloc, tokens, item, &ast.expressions[expression_count]);
            } else {
                try buildGeneratedExpressionAstInPlace(alloc, tokens, item, &ast.expressions[expression_count]);
            }
            expression_count += 1;
        }
    }
    return ast;
}

fn buildTopLevelTokenListAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) !GeneratedSqlListAst {
    var ast = GeneratedSqlListAst{};
    if (range.start >= range.end or range.end > tokens.len) return ast;

    var items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    errdefer items.deinit(alloc);
    var item_start = range.start;
    var depth: usize = 0;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) {
                    items.deinit(alloc);
                    return ast;
                }
                depth -= 1;
            },
            .comma => if (depth == 0) {
                try recordGeneratedListItem(alloc, &items, &ast, .{ .start = item_start, .end = index });
                item_start = index + 1;
            },
            else => {},
        }
    }
    try recordGeneratedListItem(alloc, &items, &ast, .{ .start = item_start, .end = range.end });
    ast.items = try items.toOwnedSlice(alloc);
    errdefer {
        alloc.free(ast.items);
        ast.items = &.{};
    }
    if (ast.items.len > 0) {
        ast.identifier_name_items = try alloc.alloc(?GeneratedSqlTokenRange, ast.items.len);
        errdefer {
            alloc.free(ast.identifier_name_items);
            ast.identifier_name_items = &.{};
        }
        for (ast.items, 0..) |item, item_index| {
            ast.identifier_name_items[item_index] = generatedIdentifierNameRange(tokens, item);
        }
    }
    return ast;
}

fn populateGeneratedCreateTableLikeAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    definition: GeneratedSqlTokenRange,
    ast: *GeneratedSqlDdlAst,
) !void {
    if (definition.start >= definition.end or definition.end > tokens.len) return;
    if (!tokens[definition.start].matchesKeywordTag(.like)) return;
    const source_range = generatedQualifiedNameRange(tokens, definition.start + 1, definition.end) orelse return;
    ast.create_table_like_source_tokens = source_range;
    if (source_range.end < definition.end) {
        ast.create_table_like_option_items = try buildGeneratedCreateTableLikeOptionListAst(alloc, tokens, .{
            .start = source_range.end,
            .end = definition.end,
        });
        try populateGeneratedCreateTableLikeOptionPayloadAst(alloc, tokens, ast);
    }
}

fn populateGeneratedCreateTableLikeOptionPayloadAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    ast: *GeneratedSqlDdlAst,
) !void {
    const items = ast.create_table_like_option_items.items;
    ast.create_table_like_option_action_items = try alloc.alloc(GeneratedSqlTokenRange, items.len);
    errdefer {
        alloc.free(ast.create_table_like_option_action_items);
        ast.create_table_like_option_action_items = &.{};
    }
    ast.create_table_like_option_name_items = try alloc.alloc(GeneratedSqlTokenRange, items.len);
    errdefer {
        alloc.free(ast.create_table_like_option_name_items);
        ast.create_table_like_option_name_items = &.{};
    }
    for (items, 0..) |item, index| {
        const payload = generatedCreateTableLikeOptionPayloadRanges(tokens, item) orelse continue;
        ast.create_table_like_option_action_items[index] = payload.action;
        ast.create_table_like_option_name_items[index] = payload.name;
    }
}

const GeneratedCreateTableLikeOptionPayloadRanges = struct {
    action: GeneratedSqlTokenRange,
    name: GeneratedSqlTokenRange,
};

fn generatedCreateTableLikeOptionPayloadRanges(
    tokens: []const token_mod.Token,
    item: GeneratedSqlTokenRange,
) ?GeneratedCreateTableLikeOptionPayloadRanges {
    if (item.start >= item.end or item.end > tokens.len) return null;
    if (!(tokens[item.start].matchesKeyword("including") or tokens[item.start].matchesKeyword("excluding"))) return null;
    const name_start = item.start + 1;
    if (name_start >= item.end) return null;
    const name_end = if (tokens[name_start].matchesKeyword("update")) blk: {
        if (name_start + 2 != item.end or !tokens[name_start + 1].matchesKeyword("policies")) return null;
        break :blk item.end;
    } else blk: {
        if (name_start + 1 != item.end) return null;
        break :blk item.end;
    };
    return .{
        .action = .{ .start = item.start, .end = item.start + 1 },
        .name = .{ .start = name_start, .end = name_end },
    };
}

fn buildGeneratedCreateTableLikeOptionListAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) !GeneratedSqlListAst {
    var ast = GeneratedSqlListAst{};
    if (range.start >= range.end or range.end > tokens.len) return ast;

    var items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    errdefer items.deinit(alloc);

    var index = range.start;
    while (index < range.end) {
        const item_start = index;
        if (!(tokens[index].matchesKeyword("including") or tokens[index].matchesKeyword("excluding"))) return error.UnsupportedSqlShape;
        index += 1;
        if (index >= range.end) return error.UnsupportedSqlShape;
        if (tokens[index].matchesKeyword("update")) {
            if (index + 1 >= range.end or !tokens[index + 1].matchesKeyword("policies")) return error.UnsupportedSqlShape;
            index += 2;
        } else {
            index += 1;
        }
        try recordGeneratedListItem(alloc, &items, &ast, .{ .start = item_start, .end = index });
    }
    ast.items = try items.toOwnedSlice(alloc);
    return ast;
}

fn populateGeneratedCreateTableDocumentAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    index: usize,
    end: usize,
    ast: *GeneratedSqlDdlAst,
) !void {
    var cursor = index;
    if (cursor + 2 < end and tokens[cursor].matchesKeywordTag(.with) and tokens[cursor + 1].kind == .lparen) {
        const storage_close = findMatchingParen(tokens, cursor + 1, end) orelse return;
        ast.create_table_storage_parameter_tokens = .{ .start = cursor + 2, .end = storage_close };
        ast.create_table_storage_parameter_items = try buildTopLevelTokenListAst(alloc, tokens, ast.create_table_storage_parameter_tokens.?);
        try populateGeneratedCreateTableStorageParameterPayloadAst(alloc, tokens, ast);
        cursor = storage_close + 1;
    }
    if (cursor >= end) return;

    var schema_items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    var schema_names: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    var schema_formats: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    var schema_json_values: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    errdefer schema_items.deinit(alloc);
    errdefer schema_names.deinit(alloc);
    errdefer schema_formats.deinit(alloc);
    errdefer schema_json_values.deinit(alloc);

    while (cursor < end) {
        if (cursor + 2 < end and
            tokens[cursor].matchesKeywordTag(.with) and
            tokens[cursor + 1].matchesKeywordTag(.system) and
            tokens[cursor + 2].matchesKeyword("versioning"))
        {
            ast.create_table_system_versioned_tokens = .{ .start = cursor, .end = cursor + 3 };
            cursor += 3;
            continue;
        }
        if (cursor + 5 < end and
            tokens[cursor].matchesKeyword("document") and
            tokens[cursor + 1].matchesKeywordTag(.schema) and
            tokens[cursor + 3].matchesKeywordTag(.as) and
            tokens[cursor + 4].matchesKeywordTag(.json) and
            tokens[cursor + 5].kind == .string)
        {
            try schema_items.append(alloc, .{ .start = cursor, .end = cursor + 6 });
            try schema_names.append(alloc, .{ .start = cursor + 2, .end = cursor + 3 });
            try schema_formats.append(alloc, .{ .start = cursor + 4, .end = cursor + 5 });
            try schema_json_values.append(alloc, .{ .start = cursor + 5, .end = cursor + 6 });
            cursor += 6;
            continue;
        }
        return;
    }

    ast.create_table_document_schema_items.items = try schema_items.toOwnedSlice(alloc);
    ast.create_table_document_schema_items.count = ast.create_table_document_schema_items.items.len;
    if (ast.create_table_document_schema_items.items.len > 0) {
        ast.create_table_document_schema_items.first_tokens = ast.create_table_document_schema_items.items[0];
        ast.create_table_document_schema_items.last_tokens = ast.create_table_document_schema_items.items[ast.create_table_document_schema_items.items.len - 1];
    }
    ast.create_table_document_schema_name_items = try schema_names.toOwnedSlice(alloc);
    ast.create_table_document_schema_format_items = try schema_formats.toOwnedSlice(alloc);
    ast.create_table_document_schema_json_items = try schema_json_values.toOwnedSlice(alloc);
}

fn populateGeneratedCreateTableStorageParameterPayloadAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    ast: *GeneratedSqlDdlAst,
) !void {
    const items = ast.create_table_storage_parameter_items.items;
    ast.create_table_storage_parameter_name_items = try alloc.alloc(GeneratedSqlTokenRange, items.len);
    errdefer {
        alloc.free(ast.create_table_storage_parameter_name_items);
        ast.create_table_storage_parameter_name_items = &.{};
    }
    ast.create_table_storage_parameter_value_items = try alloc.alloc(GeneratedSqlTokenRange, items.len);
    errdefer {
        alloc.free(ast.create_table_storage_parameter_value_items);
        ast.create_table_storage_parameter_value_items = &.{};
    }
    for (items, 0..) |item, index| {
        const payload = generatedCreateTableStorageParameterPayloadRanges(tokens, item) orelse GeneratedCreateTableStorageParameterPayloadRanges{
            .name = item,
            .value = item,
        };
        ast.create_table_storage_parameter_name_items[index] = payload.name;
        ast.create_table_storage_parameter_value_items[index] = payload.value;
    }
}

const GeneratedCreateTableStorageParameterPayloadRanges = struct {
    name: GeneratedSqlTokenRange,
    value: GeneratedSqlTokenRange,
};

fn generatedCreateTableStorageParameterPayloadRanges(
    tokens: []const token_mod.Token,
    item: GeneratedSqlTokenRange,
) ?GeneratedCreateTableStorageParameterPayloadRanges {
    if (item.end != item.start + 3 or item.end > tokens.len) return null;
    if (tokens[item.start].kind != .identifier or tokens[item.start + 1].kind != .eq) return null;
    return .{
        .name = .{ .start = item.start, .end = item.start + 1 },
        .value = .{ .start = item.start + 2, .end = item.start + 3 },
    };
}

fn populateGeneratedCreateTablePartitionedAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    index: usize,
    end: usize,
    ast: *GeneratedSqlDdlAst,
) !void {
    if (index + 4 >= end) return;
    if (!tokens[index].matchesKeywordTag(.partition) or !tokens[index + 1].matchesKeywordTag(.by)) return;
    const method_index = index + 2;
    const keys_open = method_index + 1;
    if (tokens[keys_open].kind != .lparen) return;
    const keys_close = findMatchingParen(tokens, keys_open, end) orelse return;
    ast.create_table_partition_tokens = .{ .start = index, .end = keys_close + 1 };
    ast.create_table_partition_method_tokens = .{ .start = method_index, .end = method_index + 1 };
    ast.create_table_partition_key_tokens = .{ .start = keys_open + 1, .end = keys_close };
    ast.create_table_partition_key_items = try buildTopLevelTokenListAst(alloc, tokens, ast.create_table_partition_key_tokens.?);
    ast.create_table_partition_key_name_items = try alloc.alloc(GeneratedSqlTokenRange, ast.create_table_partition_key_items.items.len);
    errdefer {
        alloc.free(ast.create_table_partition_key_name_items);
        ast.create_table_partition_key_name_items = &.{};
    }
    for (ast.create_table_partition_key_items.items, 0..) |item, item_index| {
        ast.create_table_partition_key_name_items[item_index] = if (item.end == item.start + 1 and item.end <= tokens.len and tokens[item.start].kind == .identifier)
            item
        else
            .{ .start = item.start, .end = item.start };
    }
}

fn populateGeneratedCreateTablePartitionOfAst(
    tokens: []const token_mod.Token,
    index: usize,
    end: usize,
    ast: *GeneratedSqlDdlAst,
) void {
    if (index + 8 >= end) return;
    if (!tokens[index].matchesKeywordTag(.partition) or !tokens[index + 1].matchesKeywordTag(.of)) return;
    const parent_range = generatedQualifiedNameRange(tokens, index + 2, end) orelse return;
    if (parent_range.end + 3 >= end) return;
    if (!tokens[parent_range.end].matchesKeywordTag(.@"for") or
        !tokens[parent_range.end + 1].matchesKeywordTag(.values) or
        !tokens[parent_range.end + 2].matchesKeywordTag(.from) or
        tokens[parent_range.end + 3].kind != .lparen)
    {
        return;
    }
    const lower_open = parent_range.end + 3;
    const lower_close = findMatchingParen(tokens, lower_open, end) orelse return;
    if (lower_close + 3 >= end or !tokens[lower_close + 1].matchesKeywordTag(.to) or tokens[lower_close + 2].kind != .lparen) return;
    const upper_open = lower_close + 2;
    const upper_close = findMatchingParen(tokens, upper_open, end) orelse return;
    if (upper_close + 1 != end) return;

    ast.create_table_partition_of_parent_tokens = parent_range;
    ast.create_table_partition_bound_tokens = .{ .start = parent_range.end, .end = end };
    ast.create_table_partition_lower_bound_tokens = .{ .start = lower_open + 1, .end = lower_close };
    ast.create_table_partition_upper_bound_tokens = .{ .start = upper_open + 1, .end = upper_close };
}

const GeneratedTopLevelTokenItemSummary = struct {
    first_item: ?GeneratedSqlTokenRange = null,
    last_item: ?GeneratedSqlTokenRange = null,
    count: usize = 0,
};

fn generatedTopLevelTokenItemSummary(
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) GeneratedTopLevelTokenItemSummary {
    var summary = GeneratedTopLevelTokenItemSummary{};
    if (range.start >= range.end or range.end > tokens.len) return summary;
    var item_start = range.start;
    var depth: usize = 0;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return .{};
                depth -= 1;
            },
            .comma => if (depth == 0) {
                if (item_start < index) {
                    const item = GeneratedSqlTokenRange{ .start = item_start, .end = index };
                    if (summary.count == 0) summary.first_item = item;
                    summary.last_item = item;
                    summary.count += 1;
                }
                item_start = index + 1;
            },
            else => {},
        }
    }
    if (depth != 0) return .{};
    if (item_start < range.end) {
        const item = GeneratedSqlTokenRange{ .start = item_start, .end = range.end };
        if (summary.count == 0) summary.first_item = item;
        summary.last_item = item;
        summary.count += 1;
    }
    return summary;
}

fn buildGeneratedRoutineAstPtr(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    argument_range: GeneratedSqlTokenRange,
    tail_start: usize,
    tail_end: usize,
) !*GeneratedSqlRoutineAst {
    const ptr = try alloc.create(GeneratedSqlRoutineAst);
    errdefer alloc.destroy(ptr);
    ptr.* = .{};
    errdefer ptr.deinit(alloc);
    ptr.argument_items = try buildTopLevelTokenListAst(alloc, tokens, argument_range);
    try populateGeneratedRoutineTailAst(alloc, tokens, tail_start, tail_end, ptr);
    return ptr;
}

fn populateGeneratedRoutineTailAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    tail_start: usize,
    tail_end: usize,
    ast: *GeneratedSqlRoutineAst,
) !void {
    var setting_items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    defer setting_items.deinit(alloc);
    var index = tail_start;
    while (index < tail_end) {
        if (tokens[index].matchesKeyword("returns")) {
            if (index + 4 < tail_end and
                tokens[index + 1].matchesKeywordTag(.null) and
                tokens[index + 2].matchesKeywordTag(.on) and
                tokens[index + 3].matchesKeywordTag(.null) and
                tokens[index + 4].matchesKeyword("input"))
            {
                ast.null_input_tokens = .{ .start = index, .end = index + 5 };
                index += 5;
                continue;
            }
            ast.returns_type_tokens = generatedQualifiedNameRange(tokens, index + 1, tail_end);
            index += 2;
            continue;
        }
        if (tokens[index].matchesKeyword("language")) {
            ast.language_tokens = generatedSingleTokenRangeIfIdentifier(tokens, index + 1, tail_end);
            index += 2;
            continue;
        }
        if (tokens[index].matchesKeyword("immutable") or
            tokens[index].matchesKeyword("stable") or
            tokens[index].matchesKeyword("volatile"))
        {
            ast.volatility_tokens = .{ .start = index, .end = index + 1 };
            index += 1;
            continue;
        }
        if (tokens[index].matchesKeyword("external") and
            index + 2 < tail_end and
            tokens[index + 1].matchesKeyword("security") and
            (tokens[index + 2].matchesKeyword("definer") or tokens[index + 2].matchesKeyword("invoker")))
        {
            ast.security_tokens = .{ .start = index, .end = index + 3 };
            index += 3;
            continue;
        }
        if (tokens[index].matchesKeyword("security") and
            index + 1 < tail_end and
            (tokens[index + 1].matchesKeyword("definer") or tokens[index + 1].matchesKeyword("invoker")))
        {
            ast.security_tokens = .{ .start = index, .end = index + 2 };
            index += 2;
            continue;
        }
        if (tokens[index].matchesKeyword("called") and
            index + 3 < tail_end and
            tokens[index + 1].matchesKeyword("on") and
            tokens[index + 2].matchesKeyword("null") and
            tokens[index + 3].matchesKeyword("input"))
        {
            ast.null_input_tokens = .{ .start = index, .end = index + 4 };
            index += 4;
            continue;
        }
        if (tokens[index].matchesKeyword("strict")) {
            ast.null_input_tokens = .{ .start = index, .end = index + 1 };
            index += 1;
            continue;
        }
        if (tokens[index].matchesKeyword("parallel") and
            index + 1 < tail_end and
            (tokens[index + 1].matchesKeyword("safe") or
                tokens[index + 1].matchesKeyword("restricted") or
                tokens[index + 1].matchesKeyword("unsafe")))
        {
            ast.parallel_safety_tokens = .{ .start = index, .end = index + 2 };
            index += 2;
            continue;
        }
        if (tokens[index].matchesKeyword("leakproof")) {
            ast.leakproof_tokens = .{ .start = index, .end = index + 1 };
            index += 1;
            continue;
        }
        if (tokens[index].matchesKeyword("window")) {
            ast.window_tokens = .{ .start = index, .end = index + 1 };
            index += 1;
            continue;
        }
        if (tokens[index].matchesKeyword("support")) {
            ast.support_function_tokens = generatedQualifiedNameRange(tokens, index + 1, tail_end);
            index += 2;
            continue;
        }
        if (tokens[index].matchesKeyword("transform") and
            index + 2 < tail_end and
            tokens[index + 1].matchesKeyword("for") and
            tokens[index + 2].matchesKeyword("type"))
        {
            const list_start = index + 3;
            const list_end = generatedRoutineOptionBoundary(tokens, list_start, tail_end);
            ast.transform_type_items.deinit(alloc);
            ast.transform_type_items = try buildTopLevelTokenListAst(alloc, tokens, .{ .start = list_start, .end = list_end });
            index = list_end;
            continue;
        }
        if (tokens[index].matchesKeyword("set")) {
            const setting_end = generatedRoutineOptionBoundary(tokens, index + 1, tail_end);
            try recordGeneratedListItem(alloc, &setting_items, &ast.setting_items, .{ .start = index, .end = setting_end });
            index = setting_end;
            continue;
        }
        if (tokens[index].matchesKeyword("cost")) {
            if (index + 1 < tail_end and tokens[index + 1].kind == .number) {
                ast.cost_tokens = .{ .start = index + 1, .end = index + 2 };
            }
            index += 2;
            continue;
        }
        if (tokens[index].matchesKeyword("rows")) {
            if (index + 1 < tail_end and tokens[index + 1].kind == .number) {
                ast.rows_tokens = .{ .start = index + 1, .end = index + 2 };
            }
            index += 2;
            continue;
        }
        if (tokens[index].matchesKeyword("as")) {
            if (index + 1 < tail_end and tokens[index + 1].kind == .string) {
                ast.body_tokens = .{ .start = index + 1, .end = index + 2 };
                try populateGeneratedRoutineBodyMetadata(alloc, tokens, tokens[index + 1].text, ast);
            }
            index += 2;
            continue;
        }
        index += 1;
    }
    ast.setting_items.items = try setting_items.toOwnedSlice(alloc);
}

const GeneratedRoutineBodyMetadata = struct {
    kind: GeneratedSqlRoutineBodyKind,
    hook: GeneratedSqlRoutineExecutionHook,
    body_tokens: []token_mod.Token = &.{},
    body_expression_tokens: ?GeneratedSqlTokenRange = null,
    body_expression: GeneratedSqlExpressionAst = .{},
    perform_call_count: usize = 0,
    perform_calls: []GeneratedSqlRoutinePerformCallAst = &.{},

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        freeGeneratedOwnedTokens(alloc, self.body_tokens);
        self.body_expression.deinit(alloc);
        for (self.perform_calls) |*call| call.deinit(alloc);
        if (self.perform_calls.len > 0) alloc.free(self.perform_calls);
        self.* = undefined;
    }
};

fn populateGeneratedRoutineBodyMetadata(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    body_text: []const u8,
    ast: *GeneratedSqlRoutineAst,
) !void {
    var metadata = try generatedRoutineBodyMetadataAlloc(alloc, tokens, body_text, ast) orelse return;
    var metadata_transferred = false;
    defer if (!metadata_transferred) metadata.deinit(alloc);
    ast.body_kind = metadata.kind;
    ast.body_hook = metadata.hook;
    ast.body_sql_tokens = metadata.body_tokens;
    ast.body_expression_tokens = metadata.body_expression_tokens;
    ast.body_expression = metadata.body_expression;
    ast.body_perform_call_count = metadata.perform_call_count;
    ast.body_perform_calls = metadata.perform_calls;
    metadata.body_tokens = &.{};
    metadata.body_expression = .{};
    metadata.perform_calls = &.{};
    metadata_transferred = true;
}

fn generatedRoutineBodyMetadataAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    body_text: []const u8,
    ast: *const GeneratedSqlRoutineAst,
) !?GeneratedRoutineBodyMetadata {
    const language = ast.language_tokens orelse return null;
    if (language.end != language.start + 1 or language.end > tokens.len) return null;
    if (ast.body_tokens == null) return null;
    const lang_text = tokens[language.start].text;
    if (std.ascii.eqlIgnoreCase(lang_text, "sql")) {
        const trimmed = std.mem.trim(u8, body_text, " \t\r\n");
        if (!std.ascii.startsWithIgnoreCase(trimmed, "select ")) return null;
        var expression = std.mem.trim(u8, trimmed["select ".len..], " \t\r\n");
        if (std.mem.endsWith(u8, expression, ";")) {
            expression = std.mem.trim(u8, expression[0 .. expression.len - 1], " \t\r\n");
        }
        if (expression.len == 0) return null;
        var body_tokens = try lexer.tokenizeAlloc(alloc, expression);
        errdefer lexer.freeTokens(alloc, &body_tokens);
        if (body_tokens.items.len == 0) return null;
        var owned_tokens = try cloneGeneratedOwnedTokensAlloc(alloc, body_tokens.items);
        errdefer freeGeneratedOwnedTokens(alloc, owned_tokens);
        const expression_tokens = GeneratedSqlTokenRange{ .start = 0, .end = owned_tokens.len };
        var expression_ast = try buildGeneratedExpressionAst(alloc, owned_tokens, expression_tokens);
        errdefer expression_ast.deinit(alloc);
        lexer.freeTokens(alloc, &body_tokens);
        const out = GeneratedRoutineBodyMetadata{
            .kind = .sql_expression,
            .hook = .expression,
            .body_tokens = owned_tokens,
            .body_expression_tokens = expression_tokens,
            .body_expression = expression_ast,
        };
        owned_tokens = &.{};
        expression_ast = .{};
        return out;
    }
    if (!std.ascii.eqlIgnoreCase(lang_text, "plpgsql")) return null;
    var body_tokens = try lexer.tokenizeAlloc(alloc, body_text);
    defer lexer.freeTokens(alloc, &body_tokens);
    const returns_trigger = generatedRoutineReturnsTrigger(tokens, ast);
    var metadata = if (returns_trigger) blk: {
        break :blk try generatedPlpgsqlTriggerBodyMetadata(alloc, body_tokens.items);
    } else blk: {
        if (ast.returns_type_tokens != null) return null;
        break :blk try generatedPlpgsqlProcedureBodyMetadata(alloc, body_tokens.items);
    };
    if (metadata) |*body_metadata| {
        errdefer body_metadata.deinit(alloc);
        body_metadata.body_tokens = try cloneGeneratedOwnedTokensAlloc(alloc, body_tokens.items);
    }
    return metadata;
}

fn generatedRoutineReturnsTrigger(tokens: []const token_mod.Token, ast: *const GeneratedSqlRoutineAst) bool {
    const returns = ast.returns_type_tokens orelse return false;
    return returns.end == returns.start + 1 and returns.end <= tokens.len and tokens[returns.start].matchesKeyword("trigger");
}

fn generatedPlpgsqlTriggerBodyMetadata(alloc: std.mem.Allocator, tokens: []const token_mod.Token) !?GeneratedRoutineBodyMetadata {
    if (tokens.len < 5 or !tokens[0].matchesKeyword("begin")) return null;
    var index: usize = 1;
    const perform_calls = (try generatedConsumeBenignPlpgsqlStatementsAlloc(alloc, tokens, &index)) orelse return null;
    var perform_calls_transferred = false;
    defer if (!perform_calls_transferred) freeGeneratedRoutinePerformCalls(alloc, perform_calls);
    if (index + 3 > tokens.len or !tokens[index].matchesKeyword("return")) return null;
    index += 1;
    const hook: GeneratedSqlRoutineExecutionHook = if (tokens[index].matchesKeyword("new"))
        .trigger_return_new
    else if (tokens[index].matchesKeyword("old"))
        .trigger_return_old
    else if (tokens[index].matchesKeyword("null"))
        .trigger_return_null
    else
        return null;
    index += 1;
    if (index >= tokens.len or tokens[index].kind != .semicolon) return null;
    index += 1;
    if (index >= tokens.len or !tokens[index].matchesKeyword("end")) return null;
    index += 1;
    if (index < tokens.len and tokens[index].kind == .semicolon) index += 1;
    if (index != tokens.len) return null;
    perform_calls_transferred = true;
    return .{ .kind = .plpgsql_trigger, .hook = hook, .perform_call_count = perform_calls.len, .perform_calls = perform_calls };
}

fn generatedPlpgsqlProcedureBodyMetadata(alloc: std.mem.Allocator, tokens: []const token_mod.Token) !?GeneratedRoutineBodyMetadata {
    if (tokens.len < 2 or !tokens[0].matchesKeyword("begin")) return null;
    var index: usize = 1;
    const perform_calls = (try generatedConsumeBenignPlpgsqlStatementsAlloc(alloc, tokens, &index)) orelse return null;
    var perform_calls_transferred = false;
    defer if (!perform_calls_transferred) freeGeneratedRoutinePerformCalls(alloc, perform_calls);
    if (index < tokens.len and tokens[index].matchesKeyword("null")) {
        index += 1;
        if (index >= tokens.len or tokens[index].kind != .semicolon) return null;
        index += 1;
    }
    if (index >= tokens.len or !tokens[index].matchesKeyword("end")) return null;
    index += 1;
    if (index < tokens.len and tokens[index].kind == .semicolon) index += 1;
    if (index != tokens.len) return null;
    perform_calls_transferred = true;
    return .{ .kind = .plpgsql_procedure, .hook = .procedure_noop, .perform_call_count = perform_calls.len, .perform_calls = perform_calls };
}

fn generatedConsumeBenignPlpgsqlStatementsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    index: *usize,
) !?[]GeneratedSqlRoutinePerformCallAst {
    var perform_calls = std.ArrayListUnmanaged(GeneratedSqlRoutinePerformCallAst).empty;
    var perform_calls_transferred = false;
    defer if (!perform_calls_transferred) {
        freeGeneratedRoutinePerformCallItems(alloc, perform_calls.items);
        perform_calls.deinit(alloc);
    };
    while (index.* < tokens.len) {
        if (tokens[index.*].matchesKeyword("raise")) {
            index.* += 1;
            if (index.* >= tokens.len or !tokens[index.*].matchesKeyword("notice")) return null;
            index.* += 1;
            if (index.* >= tokens.len or tokens[index.*].kind != .string) return null;
            index.* += 1;
            if (index.* >= tokens.len or tokens[index.*].kind != .semicolon) return null;
            index.* += 1;
            continue;
        }
        if (tokens[index.*].matchesKeyword("perform")) {
            index.* += 1;
            if (index.* >= tokens.len or tokens[index.*].kind != .identifier) return null;
            const routine_name = try alloc.dupe(u8, tokens[index.*].text);
            var routine_name_transferred = false;
            defer if (!routine_name_transferred) alloc.free(routine_name);
            index.* += 1;
            if (index.* >= tokens.len or tokens[index.*].kind != .lparen) return null;
            const close = findMatchingParen(tokens, index.*, tokens.len) orelse return null;
            var argument_json = std.ArrayListUnmanaged([]const u8).empty;
            var arguments_transferred = false;
            defer if (!arguments_transferred) {
                for (argument_json.items) |argument| alloc.free(argument);
                argument_json.deinit(alloc);
            };
            var arg_pos = index.* + 1;
            while (arg_pos < close) {
                const value_json = try sql_value.parseJsonValueAlloc(alloc, tokens, &arg_pos, &.{});
                var value_transferred = false;
                errdefer if (!value_transferred) alloc.free(value_json);
                try argument_json.append(alloc, value_json);
                value_transferred = true;
                if (arg_pos == close) break;
                if (tokens[arg_pos].kind != .comma) return null;
                arg_pos += 1;
            }
            if (arg_pos != close) return null;
            const owned_arguments = try argument_json.toOwnedSlice(alloc);
            arguments_transferred = true;
            var owned_arguments_transferred = false;
            defer if (!owned_arguments_transferred) {
                for (owned_arguments) |argument| alloc.free(argument);
                alloc.free(owned_arguments);
            };
            try perform_calls.append(alloc, .{
                .routine_name = routine_name,
                .argument_json = owned_arguments,
            });
            routine_name_transferred = true;
            owned_arguments_transferred = true;
            index.* = close + 1;
            if (index.* >= tokens.len or tokens[index.*].kind != .semicolon) return null;
            index.* += 1;
            continue;
        }
        break;
    }
    const owned_calls = try perform_calls.toOwnedSlice(alloc);
    perform_calls_transferred = true;
    return owned_calls;
}

fn freeGeneratedRoutinePerformCalls(alloc: std.mem.Allocator, calls: []const GeneratedSqlRoutinePerformCallAst) void {
    freeGeneratedRoutinePerformCallItems(alloc, calls);
    if (calls.len > 0) alloc.free(@constCast(calls));
}

fn freeGeneratedRoutinePerformCallItems(alloc: std.mem.Allocator, calls: []const GeneratedSqlRoutinePerformCallAst) void {
    for (calls) |*call_const| {
        var call = call_const.*;
        call.deinit(alloc);
    }
}

fn generatedRoutineOptionBoundary(tokens: []const token_mod.Token, start: usize, end: usize) usize {
    var depth: usize = 0;
    var index = start;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return index;
                depth -= 1;
            },
            else => {},
        }
        if (depth == 0 and generatedRoutineOptionStartsAt(tokens, index, end)) return index;
    }
    return end;
}

fn generatedRoutineOptionStartsAt(tokens: []const token_mod.Token, index: usize, end: usize) bool {
    if (index >= end) return false;
    if (tokens[index].matchesKeyword("external")) {
        return index + 1 < end and tokens[index + 1].matchesKeyword("security");
    }
    return tokens[index].matchesKeyword("returns") or
        tokens[index].matchesKeyword("language") or
        tokens[index].matchesKeyword("immutable") or
        tokens[index].matchesKeyword("stable") or
        tokens[index].matchesKeyword("volatile") or
        tokens[index].matchesKeyword("security") or
        tokens[index].matchesKeyword("called") or
        tokens[index].matchesKeyword("strict") or
        tokens[index].matchesKeyword("parallel") or
        tokens[index].matchesKeyword("leakproof") or
        tokens[index].matchesKeyword("window") or
        tokens[index].matchesKeyword("support") or
        tokens[index].matchesKeyword("transform") or
        tokens[index].matchesKeyword("set") or
        tokens[index].matchesKeyword("cost") or
        tokens[index].matchesKeyword("rows") or
        tokens[index].matchesKeyword("as");
}

fn buildGeneratedCreateViewAstPtr(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    operation_range: GeneratedSqlTokenRange,
) !*GeneratedSqlViewAst {
    const ptr = try alloc.create(GeneratedSqlViewAst);
    errdefer alloc.destroy(ptr);
    ptr.* = .{};
    errdefer ptr.deinit(alloc);
    const as_index = findTopLevelKeyword(tokens, operation_range.start, operation_range.end, .as) orelse return ptr;
    if (operation_range.start < as_index and tokens[operation_range.start].kind == .lparen) {
        if (findMatchingParen(tokens, operation_range.start, as_index + 1)) |columns_close| {
            if (columns_close == as_index - 1) {
                ptr.column_items = try buildTopLevelTokenListAst(alloc, tokens, .{ .start = operation_range.start + 1, .end = columns_close });
            }
        }
    }
    if (as_index + 1 < operation_range.end) {
        const query_start = as_index + 1;
        const query_end = if (generatedRelationPopulationDataClause(tokens, query_start, operation_range.end)) |clause|
            clause.start
        else
            operation_range.end;
        if (query_start < query_end) {
            ptr.query_tokens = .{ .start = query_start, .end = query_end };
            ptr.query_read = try buildGeneratedReadAstForRangeAlloc(alloc, tokens, ptr.query_tokens.?);
        }
    }
    return ptr;
}

fn buildGeneratedSequenceOperationListAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) !GeneratedSqlListAst {
    var ast = GeneratedSqlListAst{};
    if (range.start >= range.end or range.end > tokens.len) return ast;

    var items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    errdefer items.deinit(alloc);
    var index = range.start;
    while (index < range.end) {
        const operation_end = generatedSequenceOperationEnd(tokens, index, range.end) orelse {
            ast.deinit(alloc);
            items.deinit(alloc);
            return .{};
        };
        try recordGeneratedListItem(alloc, &items, &ast, .{ .start = index, .end = operation_end });
        index = operation_end;
    }
    ast.items = try items.toOwnedSlice(alloc);
    return ast;
}

fn generatedSequenceOperationEnd(tokens: []const token_mod.Token, start: usize, end: usize) ?usize {
    if (start >= end) return null;
    if (tokens[start].matchesKeyword("as")) {
        if (start + 2 <= end) return start + 2;
        return null;
    }
    if (tokens[start].matchesKeyword("owned")) {
        if (start + 3 <= end and tokens[start + 1].matchesKeyword("by")) return start + 3;
        return null;
    }
    if (tokens[start].matchesKeyword("restart")) {
        if (start + 1 < end and tokens[start + 1].matchesKeyword("with")) {
            if (start + 3 <= end) return start + 3;
            return null;
        }
        return start + 1;
    }
    if (tokens[start].matchesKeyword("start")) {
        if (start + 1 < end and tokens[start + 1].matchesKeyword("with")) {
            if (start + 3 <= end) return start + 3;
            return null;
        }
        if (start + 2 <= end) return start + 2;
        return null;
    }
    if (tokens[start].matchesKeyword("increment")) {
        if (start + 1 < end and tokens[start + 1].matchesKeyword("by")) {
            if (start + 3 <= end) return start + 3;
            return null;
        }
        if (start + 2 <= end) return start + 2;
        return null;
    }
    if (tokens[start].matchesKeyword("minvalue") or tokens[start].matchesKeyword("maxvalue") or tokens[start].matchesKeyword("cache")) {
        if (start + 2 <= end) return start + 2;
        return null;
    }
    if (tokens[start].matchesKeyword("cycle")) return start + 1;
    if (tokens[start].matchesKeyword("no")) {
        if (start + 2 <= end and
            (tokens[start + 1].matchesKeyword("minvalue") or
                tokens[start + 1].matchesKeyword("maxvalue") or
                tokens[start + 1].matchesKeyword("cycle")))
        {
            return start + 2;
        }
        return null;
    }
    return null;
}

fn populateGeneratedCreateDomainOptionPayloadAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    ast: *GeneratedSqlDdlAst,
) !void {
    const items = ast.domain_operation_items.items;
    ast.domain_operation_kind_items = try alloc.alloc(GeneratedSqlTokenRange, items.len);
    errdefer {
        alloc.free(ast.domain_operation_kind_items);
        ast.domain_operation_kind_items = &.{};
    }
    ast.domain_operation_constraint_name_items = try alloc.alloc(?GeneratedSqlTokenRange, items.len);
    @memset(ast.domain_operation_constraint_name_items, null);
    errdefer {
        alloc.free(ast.domain_operation_constraint_name_items);
        ast.domain_operation_constraint_name_items = &.{};
    }
    ast.domain_operation_default_value_items = try alloc.alloc(?GeneratedSqlTokenRange, items.len);
    @memset(ast.domain_operation_default_value_items, null);
    errdefer {
        alloc.free(ast.domain_operation_default_value_items);
        ast.domain_operation_default_value_items = &.{};
    }
    ast.domain_operation_check_payload_items = try alloc.alloc(?GeneratedSqlTokenRange, items.len);
    @memset(ast.domain_operation_check_payload_items, null);
    errdefer {
        alloc.free(ast.domain_operation_check_payload_items);
        ast.domain_operation_check_payload_items = &.{};
    }
    ast.domain_operation_check_payload_expressions = try alloc.alloc(GeneratedSqlExpressionAst, items.len);
    @memset(ast.domain_operation_check_payload_expressions, .{});
    var check_expression_count: usize = 0;
    errdefer {
        for (ast.domain_operation_check_payload_expressions[0..check_expression_count]) |*expression| expression.deinit(alloc);
        alloc.free(ast.domain_operation_check_payload_expressions);
        ast.domain_operation_check_payload_expressions = &.{};
    }

    for (items, 0..) |item, index| {
        const payload = generatedCreateDomainOptionPayloadRanges(tokens, item) orelse continue;
        ast.domain_operation_kind_items[index] = payload.kind;
        ast.domain_operation_constraint_name_items[index] = payload.constraint_name;
        ast.domain_operation_default_value_items[index] = payload.default_value;
        ast.domain_operation_check_payload_items[index] = payload.check_payload;
        if (payload.check_payload) |check_payload| {
            try buildGeneratedExpressionAstInPlace(alloc, tokens, check_payload, &ast.domain_operation_check_payload_expressions[index]);
            check_expression_count = index + 1;
        }
    }
}

const GeneratedCreateDomainOptionPayloadRanges = struct {
    kind: GeneratedSqlTokenRange,
    constraint_name: ?GeneratedSqlTokenRange = null,
    default_value: ?GeneratedSqlTokenRange = null,
    check_payload: ?GeneratedSqlTokenRange = null,
};

fn generatedCreateDomainOptionPayloadRanges(
    tokens: []const token_mod.Token,
    item: GeneratedSqlTokenRange,
) ?GeneratedCreateDomainOptionPayloadRanges {
    if (item.start >= item.end or item.end > tokens.len) return null;
    if (tokens[item.start].matchesKeyword("default")) {
        if (item.start + 1 >= item.end) return null;
        return .{
            .kind = .{ .start = item.start, .end = item.start + 1 },
            .default_value = .{ .start = item.start + 1, .end = item.end },
        };
    }
    if (tokens[item.start].matchesKeyword("not")) {
        if (item.start + 2 != item.end or !tokens[item.start + 1].matchesKeyword("null")) return null;
        return .{ .kind = item };
    }
    if (tokens[item.start].matchesKeyword("null")) {
        if (item.start + 1 != item.end) return null;
        return .{ .kind = item };
    }
    if (tokens[item.start].matchesKeyword("constraint")) {
        if (item.start + 4 > item.end or tokens[item.start + 1].kind != .identifier or !tokens[item.start + 2].matchesKeyword("check")) return null;
        return .{
            .kind = .{ .start = item.start + 2, .end = item.start + 3 },
            .constraint_name = .{ .start = item.start + 1, .end = item.start + 2 },
            .check_payload = .{ .start = item.start + 3, .end = item.end },
        };
    }
    if (tokens[item.start].matchesKeyword("check")) {
        if (item.start + 2 > item.end) return null;
        return .{
            .kind = .{ .start = item.start, .end = item.start + 1 },
            .check_payload = .{ .start = item.start + 1, .end = item.end },
        };
    }
    return null;
}

fn buildGeneratedCreateDomainOptionListAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) !GeneratedSqlListAst {
    var ast = GeneratedSqlListAst{};
    if (range.start >= range.end or range.end > tokens.len) return ast;

    var items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    errdefer items.deinit(alloc);
    var index = range.start;
    while (index < range.end) {
        const option_end = generatedCreateDomainOptionEnd(tokens, index, range.end) orelse {
            ast.deinit(alloc);
            items.deinit(alloc);
            return .{};
        };
        try recordGeneratedListItem(alloc, &items, &ast, .{ .start = index, .end = option_end });
        index = option_end;
    }
    ast.items = try items.toOwnedSlice(alloc);
    return ast;
}

fn generatedCreateDomainOptionEnd(tokens: []const token_mod.Token, start: usize, end: usize) ?usize {
    if (start >= end) return null;
    if (tokens[start].matchesKeyword("not")) {
        if (start + 2 <= end and tokens[start + 1].matchesKeyword("null")) return start + 2;
        return null;
    }
    if (tokens[start].matchesKeyword("null")) return start + 1;
    if (tokens[start].matchesKeyword("check")) {
        if (start + 1 >= end or tokens[start + 1].kind != .lparen) return null;
        const close_index = findMatchingParen(tokens, start + 1, end) orelse return null;
        if (close_index + 1 <= end) return close_index + 1;
        return null;
    }
    if (tokens[start].matchesKeyword("constraint")) {
        if (start + 4 > end or tokens[start + 1].kind != .identifier or !tokens[start + 2].matchesKeyword("check") or tokens[start + 3].kind != .lparen) return null;
        const close_index = findMatchingParen(tokens, start + 3, end) orelse return null;
        if (close_index + 1 <= end) return close_index + 1;
        return null;
    }
    if (tokens[start].matchesKeyword("default")) {
        if (start + 1 >= end) return null;
        var index = start + 2;
        var depth: usize = 0;
        while (index < end) : (index += 1) {
            switch (tokens[index].kind) {
                .lparen, .lbracket => depth += 1,
                .rparen, .rbracket => {
                    if (depth == 0) return null;
                    depth -= 1;
                },
                else => if (depth == 0 and generatedCreateDomainOptionStarts(tokens, index, end)) return index,
            }
        }
        return end;
    }
    return null;
}

fn generatedCreateDomainOptionStarts(tokens: []const token_mod.Token, index: usize, end: usize) bool {
    if (index >= end) return false;
    if (tokens[index].matchesKeyword("default") or tokens[index].matchesKeyword("null") or tokens[index].matchesKeyword("check")) return true;
    if (tokens[index].matchesKeyword("not")) return index + 1 < end and tokens[index + 1].matchesKeyword("null");
    if (tokens[index].matchesKeyword("constraint")) return index + 3 < end and tokens[index + 2].matchesKeyword("check") and tokens[index + 3].kind == .lparen;
    return false;
}

fn generatedCreatePublicationAllTables(tokens: []const token_mod.Token, operation_start: usize, end: usize) bool {
    const tail_end = generatedPublicationWithIndex(tokens, operation_start, end) orelse end;
    return operation_start + 3 == tail_end and
        tokens[operation_start].matchesKeyword("for") and
        tokens[operation_start + 1].matchesKeyword("all") and
        tokens[operation_start + 2].matchesKeyword("tables");
}

fn generatedPublicationTableListRange(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?GeneratedSqlTokenRange {
    const tail_end = generatedPublicationWithIndex(tokens, operation_start, end) orelse end;
    if (operation_start + 3 > tail_end) return null;
    if (tokens[operation_start].matchesKeyword("for")) {
        if (!tokens[operation_start + 1].matchesKeyword("table")) return null;
        return .{ .start = operation_start + 2, .end = tail_end };
    }
    if (tokens[operation_start].matchesKeyword("add") or
        tokens[operation_start].matchesKeyword("drop") or
        tokens[operation_start].matchesKeyword("set"))
    {
        if (!tokens[operation_start + 1].matchesKeyword("table")) return null;
        return .{ .start = operation_start + 2, .end = tail_end };
    }
    return null;
}

fn generatedPublicationOptionListRange(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?GeneratedSqlTokenRange {
    const with_index = generatedPublicationWithIndex(tokens, operation_start, end) orelse return null;
    if (with_index + 1 >= end or tokens[with_index + 1].kind != .lparen) return null;
    const close_index = findMatchingParen(tokens, with_index + 1, end) orelse return null;
    if (close_index + 1 != end) return null;
    return .{ .start = with_index + 2, .end = close_index };
}

fn generatedAlterPublicationSetOptionListRange(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?GeneratedSqlTokenRange {
    if (operation_start + 3 > end or !tokens[operation_start].matchesKeywordTag(.set)) return null;
    if (tokens[operation_start + 1].kind != .lparen) return null;
    const close_index = findMatchingParen(tokens, operation_start + 1, end) orelse return null;
    if (close_index + 1 != end) return null;
    return .{ .start = operation_start + 2, .end = close_index };
}

fn generatedPublicationWithIndex(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?usize {
    return findTopLevelKeyword(tokens, operation_start, end, .with);
}

fn generatedSubscriptionConnectionValueRange(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?GeneratedSqlTokenRange {
    if (operation_start + 4 > end or !tokens[operation_start].matchesKeyword("connection")) return null;
    const publication_index = findKeyword(tokens, operation_start + 1, end, .publication) orelse return null;
    if (publication_index <= operation_start + 1 or publication_index + 1 >= end) return null;
    return .{ .start = operation_start + 1, .end = publication_index };
}

fn generatedAlterSubscriptionConnectionValueRange(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?GeneratedSqlTokenRange {
    if (operation_start + 2 != end or !tokens[operation_start].matchesKeyword("connection")) return null;
    return .{ .start = operation_start + 1, .end = end };
}

fn generatedSubscriptionPublicationListRange(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?GeneratedSqlTokenRange {
    const publication_index = findKeyword(tokens, operation_start, end, .publication) orelse return null;
    const tail_end = generatedSubscriptionWithIndex(tokens, publication_index + 1, end) orelse end;
    if (publication_index + 1 >= tail_end) return null;
    return .{ .start = publication_index + 1, .end = tail_end };
}

fn generatedSubscriptionOptionListRange(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?GeneratedSqlTokenRange {
    const with_index = generatedSubscriptionWithIndex(tokens, operation_start, end) orelse return null;
    if (with_index + 1 >= end or tokens[with_index + 1].kind != .lparen) return null;
    const close_index = findMatchingParen(tokens, with_index + 1, end) orelse return null;
    if (close_index + 1 != end) return null;
    return .{ .start = with_index + 2, .end = close_index };
}

fn generatedSubscriptionSetOptionListRange(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?GeneratedSqlTokenRange {
    if (operation_start + 2 >= end or !tokens[operation_start].matchesKeyword("set")) return null;
    if (tokens[operation_start + 1].kind != .lparen) return null;
    const close_index = findMatchingParen(tokens, operation_start + 1, end) orelse return null;
    if (close_index + 1 != end) return null;
    return .{ .start = operation_start + 2, .end = close_index };
}

fn generatedSubscriptionSkipOptionListRange(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?GeneratedSqlTokenRange {
    if (operation_start + 2 >= end or !tokens[operation_start].matchesKeywordTag(.skip)) return null;
    if (tokens[operation_start + 1].kind != .lparen) return null;
    const close_index = findMatchingParen(tokens, operation_start + 1, end) orelse return null;
    if (close_index + 1 != end) return null;
    return .{ .start = operation_start + 2, .end = close_index };
}

fn generatedSubscriptionWithIndex(tokens: []const token_mod.Token, operation_start: usize, end: usize) ?usize {
    return findTopLevelKeyword(tokens, operation_start, end, .with);
}

fn populateGeneratedPolicyTailAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    operation: GeneratedSqlTokenRange,
    ast: *GeneratedSqlDdlAst,
) !void {
    if (findTopLevelKeyword(tokens, operation.start, operation.end, .as)) |as_index| {
        if (as_index + 1 < operation.end and generatedPolicyModeToken(tokens[as_index + 1])) {
            ast.policy_mode_tokens = .{ .start = as_index + 1, .end = as_index + 2 };
        }
    }
    if (findTopLevelKeyword(tokens, operation.start, operation.end, .@"for")) |for_index| {
        if (for_index + 1 < operation.end and generatedPolicyCommandToken(tokens[for_index + 1])) {
            ast.policy_command_tokens = .{ .start = for_index + 1, .end = for_index + 2 };
        }
    }
    if (findTopLevelKeyword(tokens, operation.start, operation.end, .to)) |to_index| {
        ast.policy_role_targets_present = true;
        ast.policy_role_targets_public = generatedPolicyRoleTargetsPublic(tokens, to_index, operation.end);
        if (generatedPolicyRoleTargetsRange(tokens, to_index, operation.end)) |role_range| {
            ast.policy_role_target_items = try buildTopLevelTokenListAst(alloc, tokens, role_range);
        }
    }
    if (findTopLevelKeyword(tokens, operation.start, operation.end, .using)) |using_index| {
        ast.policy_using_predicate_tokens = generatedPolicyPredicateRange(tokens, using_index, operation.end, false);
    }
    if (findTopLevelKeywordSequence(tokens, operation.start, operation.end, .with, .check)) |with_index| {
        ast.policy_check_predicate_tokens = generatedPolicyPredicateRange(tokens, with_index, operation.end, true);
    }
}

fn generatedPolicyModeToken(token: token_mod.Token) bool {
    return token.matchesKeyword("permissive") or token.matchesKeyword("restrictive");
}

fn generatedPolicyCommandToken(token: token_mod.Token) bool {
    return token.matchesKeywordTag(.all) or
        token.matchesKeywordTag(.select) or
        token.matchesKeywordTag(.insert) or
        token.matchesKeywordTag(.update) or
        token.matchesKeywordTag(.delete);
}

fn generatedPolicyPredicateRange(tokens: []const token_mod.Token, clause_index: usize, end: usize, with_check: bool) ?GeneratedSqlTokenRange {
    const open_index = if (with_check) clause_index + 2 else clause_index + 1;
    if (open_index >= end or tokens[open_index].kind != .lparen) return null;
    const close_index = findMatchingParen(tokens, open_index, end) orelse return null;
    if (open_index + 1 >= close_index) return null;
    return .{ .start = open_index + 1, .end = close_index };
}

fn generatedPolicyRoleTargetsRange(tokens: []const token_mod.Token, to_index: usize, end: usize) ?GeneratedSqlTokenRange {
    if (to_index >= end or !tokens[to_index].matchesKeywordTag(.to)) return null;
    var role_end = to_index + 1;
    while (role_end < end and !tokens[role_end].matchesKeywordTag(.using) and !tokens[role_end].matchesKeywordTag(.with)) : (role_end += 1) {}
    if (to_index + 1 >= role_end) return null;
    if (to_index + 2 == role_end and tokens[to_index + 1].matchesKeyword("public")) return null;
    return .{ .start = to_index + 1, .end = role_end };
}

fn generatedPolicyRoleTargetsPublic(tokens: []const token_mod.Token, to_index: usize, end: usize) bool {
    if (to_index + 2 > end or !tokens[to_index].matchesKeywordTag(.to)) return false;
    const next_index = to_index + 2;
    return tokens[to_index + 1].matchesKeyword("public") and
        (next_index == end or tokens[next_index].matchesKeywordTag(.using) or tokens[next_index].matchesKeywordTag(.with));
}

const GeneratedAliasedListItem = struct {
    expression_tokens: GeneratedSqlTokenRange,
    alias_tokens: ?GeneratedSqlTokenRange = null,
    alias_name_tokens: ?GeneratedSqlTokenRange = null,
    direction_tokens: ?GeneratedSqlTokenRange = null,
    direction: ?GeneratedSqlOrderDirection = null,
    order_using_operator_tokens: ?GeneratedSqlTokenRange = null,
    nulls_order_tokens: ?GeneratedSqlTokenRange = null,
    nulls_order: ?GeneratedSqlNullsOrder = null,
};

fn generatedAliasedListItem(
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
    options: GeneratedSqlListOptions,
) GeneratedAliasedListItem {
    var result = GeneratedAliasedListItem{ .expression_tokens = range };
    if (range.end <= range.start + 1 or range.end > tokens.len) return result;

    if (options.order_modifiers) {
        var expression_end = range.end;
        if (expression_end >= range.start + 2 and
            tokens[expression_end - 2].matchesKeywordTag(.nulls))
        {
            if (tokens[expression_end - 1].matchesKeywordTag(.first)) {
                result.nulls_order_tokens = .{ .start = expression_end - 2, .end = expression_end };
                result.nulls_order = .first;
                expression_end -= 2;
            } else if (tokens[expression_end - 1].matchesKeywordTag(.last)) {
                result.nulls_order_tokens = .{ .start = expression_end - 2, .end = expression_end };
                result.nulls_order = .last;
                expression_end -= 2;
            }
        }
        if (expression_end > range.start and tokens[expression_end - 1].matchesKeywordTag(.asc)) {
            result.direction_tokens = .{ .start = expression_end - 1, .end = expression_end };
            result.direction = .asc;
            expression_end -= 1;
        } else if (expression_end > range.start and tokens[expression_end - 1].matchesKeywordTag(.desc)) {
            result.direction_tokens = .{ .start = expression_end - 1, .end = expression_end };
            result.direction = .desc;
            expression_end -= 1;
        } else if (expression_end >= range.start + 2 and tokens[expression_end - 2].matchesKeywordTag(.using)) {
            switch (tokens[expression_end - 1].kind) {
                .eq, .neq, .lt, .lte, .gt, .gte => {
                    result.direction_tokens = .{ .start = expression_end - 2, .end = expression_end };
                    result.order_using_operator_tokens = .{ .start = expression_end - 1, .end = expression_end };
                    expression_end -= 2;
                },
                else => {},
            }
        }
        if (options.index_collation_modifier) {
            var depth: usize = 0;
            var index = range.start;
            while (index < expression_end) : (index += 1) {
                switch (tokens[index].kind) {
                    .lparen, .lbracket => depth += 1,
                    .rparen, .rbracket => {
                        if (depth == 0) break;
                        depth -= 1;
                    },
                    else => if (depth == 0 and tokens[index].matchesKeyword("collate")) {
                        if (index > range.start) expression_end = index;
                        break;
                    },
                }
            }
        }
        if (expression_end > range.start) result.expression_tokens = .{ .start = range.start, .end = expression_end };
        return result;
    }

    var depth: usize = 0;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return result;
                depth -= 1;
            },
            else => if (depth == 0 and tokens[index].matchesKeywordTag(.as) and index > range.start and index + 1 < range.end) {
                result.expression_tokens = .{ .start = range.start, .end = index };
                result.alias_tokens = .{ .start = index, .end = range.end };
                result.alias_name_tokens = .{ .start = index + 1, .end = range.end };
                return result;
            },
        }
    }
    if (options.bare_alias and generatedBareAliasCandidate(tokens, range)) {
        result.expression_tokens = .{ .start = range.start, .end = range.end - 1 };
        result.alias_tokens = .{ .start = range.end - 1, .end = range.end };
        result.alias_name_tokens = result.alias_tokens;
    }
    return result;
}

fn generatedBareAliasCandidate(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) bool {
    if (range.end <= range.start + 1 or range.end > tokens.len) return false;
    if (tokens[range.end - 1].kind != .identifier) return false;
    return switch (tokens[range.end - 2].kind) {
        .comma,
        .lparen,
        .lbracket,
        .eq,
        .neq,
        .lt,
        .lte,
        .gt,
        .gte,
        .plus,
        .minus,
        .slash,
        .percent,
        .pipe_concat,
        .at_contains,
        .range_overlap,
        .question,
        .question_any,
        .question_all,
        .arrow_json,
        .arrow_text,
        .path_arrow_json,
        .path_arrow_text,
        .regex_match,
        .regex_imatch,
        .regex_not_match,
        .regex_not_imatch,
        => false,
        else => true,
    };
}

fn generatedListExpressionTokens(list: GeneratedSqlListAst, index: usize) ?GeneratedSqlTokenRange {
    if (index < list.expression_items.len) return list.expression_items[index];
    if (index < list.items.len) return list.items[index];
    return null;
}

fn populateGeneratedInsertValueRowArgumentItems(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    rows: *GeneratedSqlListAst,
) !void {
    if (rows.expressions.len != rows.count) return;
    for (rows.expressions) |*expression| {
        try populateGeneratedGroupedArgumentItems(alloc, tokens, expression);
    }
}

fn populateGeneratedGroupedArgumentItems(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    expression: *GeneratedSqlExpressionAst,
) !void {
    if (expression.kind != .grouped) return;
    const inner_range = expression.inner_tokens orelse return;
    expression.argument_items.deinit(alloc);
    expression.argument_items = try buildTopLevelListAst(alloc, tokens, inner_range, .{});
}

fn recordGeneratedListItem(
    alloc: std.mem.Allocator,
    items: *std.ArrayListUnmanaged(GeneratedSqlTokenRange),
    ast: *GeneratedSqlListAst,
    range: GeneratedSqlTokenRange,
) !void {
    if (range.start >= range.end) return;
    try items.append(alloc, range);
    if (ast.count == 0) ast.first_tokens = range;
    ast.last_tokens = range;
    ast.count += 1;
}

fn buildGeneratedAssignmentExpressionAstInPlace(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
    ast: *GeneratedSqlExpressionAst,
) anyerror!void {
    ast.* = GeneratedSqlExpressionAst{
        .tokens = range,
        .identifier_name_tokens = generatedIdentifierNameRange(tokens, range),
        .identifier_qualified = generatedIdentifierIsQualified(tokens, range),
    };
    errdefer ast.deinit(alloc);

    const operator_index = findTopLevelAssignmentOperator(tokens, range) orelse {
        try buildGeneratedExpressionAstInPlace(alloc, tokens, range, ast);
        return;
    };
    if (operator_index == range.start or operator_index + 1 >= range.end) {
        try buildGeneratedExpressionAstInPlace(alloc, tokens, range, ast);
        return;
    }

    ast.kind = .comparison;
    ast.left_tokens = .{ .start = range.start, .end = operator_index };
    ast.left_expression_kind = generatedExpressionKindForRange(tokens, ast.left_tokens.?);
    ast.left_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, ast.left_tokens.?);
    if (ast.left_expression) |left_expression| {
        try populateGeneratedGroupedArgumentItems(alloc, tokens, left_expression);
    }
    ast.operator_tokens = .{ .start = operator_index, .end = operator_index + 1 };
    ast.right_tokens = .{ .start = operator_index + 1, .end = range.end };
    ast.right_expression_kind = generatedExpressionKindForRange(tokens, ast.right_tokens.?);
    ast.right_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, ast.right_tokens.?);
    if (ast.right_expression) |right_expression| {
        try populateGeneratedGroupedArgumentItems(alloc, tokens, right_expression);
    }
}

fn findTopLevelAssignmentOperator(
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) ?usize {
    if (range.start >= range.end or range.end > tokens.len) return null;
    var depth: usize = 0;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .eq => if (depth == 0) return index,
            else => {},
        }
    }
    return null;
}

fn buildGeneratedExpressionAstInPlace(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
    ast: *GeneratedSqlExpressionAst,
) anyerror!void {
    ast.* = GeneratedSqlExpressionAst{
        .tokens = range,
        .identifier_name_tokens = generatedIdentifierNameRange(tokens, range),
        .identifier_qualified = generatedIdentifierIsQualified(tokens, range),
    };
    errdefer ast.deinit(alloc);
    if (generatedQualifiedStarExpression(tokens, range)) return;
    if (generatedSubqueryExpressionInnerRange(tokens, range)) |inner_range| {
        ast.kind = .subquery;
        ast.inner_tokens = inner_range;
        try buildGeneratedSubqueryExpressionAst(alloc, tokens, inner_range, ast);
        return;
    }
    if (generatedWrappedExpressionInnerRange(tokens, range)) |inner_range| {
        ast.kind = .grouped;
        ast.inner_tokens = inner_range;
        ast.inner_expression_kind = generatedExpressionKindForRange(tokens, inner_range);
        ast.inner_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, inner_range);
        ast.argument_items = try buildTopLevelListAst(alloc, tokens, inner_range, .{});
        return;
    }
    if (generatedCastExpression(tokens, range)) |cast_expression| {
        ast.kind = .cast;
        ast.cast_expression_tokens = cast_expression.expression_tokens;
        ast.cast_expression_kind = generatedExpressionKindForRange(tokens, cast_expression.expression_tokens);
        ast.cast_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, cast_expression.expression_tokens);
        ast.cast_type_tokens = cast_expression.type_tokens;
        return;
    }
    if (generatedCaseExpression(tokens, range)) |case_expression| {
        ast.kind = .case_expression;
        ast.case_branch_count = case_expression.branch_count;
        ast.case_first_when_tokens = case_expression.first_when_tokens;
        ast.case_last_when_tokens = case_expression.last_when_tokens;
        ast.case_first_condition_tokens = case_expression.first_condition_tokens;
        ast.case_first_condition_kind = generatedExpressionKindForRange(tokens, case_expression.first_condition_tokens);
        ast.case_first_condition = try buildGeneratedExpressionNodeAlloc(alloc, tokens, case_expression.first_condition_tokens);
        ast.case_first_result_tokens = case_expression.first_result_tokens;
        ast.case_first_result_kind = generatedExpressionKindForRange(tokens, case_expression.first_result_tokens);
        ast.case_first_result = try buildGeneratedExpressionNodeAlloc(alloc, tokens, case_expression.first_result_tokens);
        const branch_lists = try buildGeneratedCaseBranchLists(alloc, tokens, range);
        ast.case_condition_items = branch_lists.conditions;
        ast.case_result_items = branch_lists.results;
        ast.case_else_tokens = case_expression.else_tokens;
        ast.case_else_expression_tokens = case_expression.else_expression_tokens;
        if (case_expression.else_expression_tokens) |else_expression_tokens| {
            ast.case_else_expression_kind = generatedExpressionKindForRange(tokens, else_expression_tokens);
            ast.case_else_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, else_expression_tokens);
        }
        return;
    }
    if (generatedIntervalLiteralExpression(tokens, range)) |value_tokens| {
        ast.kind = .interval_literal;
        ast.interval_value_tokens = value_tokens;
        return;
    }
    if (generatedTimestampLiteralExpression(tokens, range)) |timestamp_literal| {
        ast.kind = .timestamp_literal;
        ast.timestamp_type_tokens = timestamp_literal.type_tokens;
        ast.timestamp_value_tokens = timestamp_literal.value_tokens;
        return;
    }
    if (generatedCurrentTimestampExpression(tokens, range)) |current_timestamp| {
        ast.kind = .current_timestamp;
        ast.current_timestamp_precision_tokens = current_timestamp.precision_tokens;
        return;
    }
    if (generatedCurrentDateExpression(tokens, range)) {
        ast.kind = .current_date;
        return;
    }
    if (generatedExtractExpression(tokens, range)) |extract_expression| {
        ast.kind = .extract_expression;
        ast.extract_field_tokens = extract_expression.field_tokens;
        ast.extract_source_tokens = extract_expression.source_tokens;
        ast.extract_source_expression_kind = generatedExpressionKindForRange(tokens, extract_expression.source_tokens);
        ast.extract_source_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, extract_expression.source_tokens);
        return;
    }
    if (findTopLevelExpressionOperator(tokens, range)) |operator| {
        ast.kind = operator.kind;
        if (!operator.prefix) {
            if (range.start >= operator.index) return;
            if (!operator.postfix and operator.index + 1 >= range.end) return;
            const left_end = if (operator.negation_index) |negation_index|
                if (negation_index < operator.index) negation_index else operator.index
            else
                operator.index;
            if (range.start >= left_end) return;
            ast.left_tokens = .{ .start = range.start, .end = left_end };
            ast.left_expression_kind = generatedExpressionKindForRange(tokens, ast.left_tokens.?);
            ast.left_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, ast.left_tokens.?);
        } else if (operator.index + 1 >= range.end) {
            return;
        }
        if (operator.negation_index) |negation_index| ast.negation_tokens = .{ .start = negation_index, .end = negation_index + 1 };
        const operator_end = operator.operator_end_index orelse operator.index + 1;
        ast.operator_tokens = .{ .start = operator.index, .end = operator_end };
        const right_start = if (operator.quantifier_index) |quantifier_index| blk: {
            ast.quantifier_tokens = .{ .start = quantifier_index, .end = quantifier_index + 1 };
            break :blk quantifier_index + 1;
        } else operator_end;
        if (right_start >= range.end) return;
        var operand_start = right_start;
        if (isGeneratedBetweenExpressionKind(operator.kind)) {
            if (generatedBetweenModifier(tokens[right_start])) |modifier| {
                if (right_start + 1 >= range.end) return;
                ast.between_modifier_tokens = .{ .start = right_start, .end = right_start + 1 };
                ast.between_modifier = modifier;
                operand_start = right_start + 1;
            }
        }
        var right_end = range.end;
        if (isGeneratedLikeExpressionKind(operator.kind)) {
            if (findTopLevelKeyword(tokens, operand_start, range.end, .escape)) |escape_index| {
                if (operand_start >= escape_index or escape_index + 1 >= range.end) return;
                right_end = escape_index;
                ast.escape_tokens = .{ .start = escape_index, .end = range.end };
                const escape_expression_tokens = GeneratedSqlTokenRange{ .start = escape_index + 1, .end = range.end };
                ast.escape_expression_kind = generatedExpressionKindForRange(tokens, escape_expression_tokens);
                ast.escape_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, escape_expression_tokens);
            }
        }
        ast.right_tokens = .{ .start = operand_start, .end = right_end };
        ast.right_expression_kind = generatedExpressionKindForRange(tokens, ast.right_tokens.?);
        ast.right_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, ast.right_tokens.?);
        if (isGeneratedBetweenExpressionKind(operator.kind)) {
            if (generatedBetweenBoundExpressionRanges(tokens, .{ .start = operand_start, .end = right_end })) |bounds| {
                ast.between_lower_tokens = bounds.lower_tokens;
                ast.between_lower_expression_kind = generatedExpressionKindForRange(tokens, bounds.lower_tokens);
                ast.between_lower_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, bounds.lower_tokens);
                ast.between_upper_tokens = bounds.upper_tokens;
                ast.between_upper_expression_kind = generatedExpressionKindForRange(tokens, bounds.upper_tokens);
                ast.between_upper_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, bounds.upper_tokens);
            }
        }
        if (try generatedBooleanChainMetadata(alloc, tokens, range, operator.kind)) |boolean_chain| {
            ast.boolean_condition_count = boolean_chain.condition_count;
            ast.boolean_first_condition_tokens = boolean_chain.first_condition_tokens;
            ast.boolean_first_condition_kind = boolean_chain.first_condition_kind;
            ast.boolean_first_condition = boolean_chain.first_condition;
            ast.boolean_last_condition_tokens = boolean_chain.last_condition_tokens;
            ast.boolean_last_condition_kind = boolean_chain.last_condition_kind;
            ast.boolean_last_condition = boolean_chain.last_condition;
            ast.boolean_condition_items = boolean_chain.condition_items;
        }
        return;
    }
    if (generatedFunctionCallExpression(tokens, range)) |function_call| {
        ast.kind = .function_call;
        ast.function_name_tokens = function_call.name_tokens;
        ast.aggregate_function_kind = generatedAggregateFunctionKindForName(tokens, function_call.name_tokens);
        ast.window_function_kind = generatedWindowFunctionKindForName(tokens, function_call.name_tokens);
        ast.argument_tokens = function_call.argument_tokens;
        ast.argument_distinct_tokens = function_call.argument_distinct_tokens;
        ast.argument_value_tokens = function_call.argument_value_tokens;
        if (function_call.argument_value_tokens) |argument_value_tokens| {
            ast.argument_items = try buildTopLevelListAst(alloc, tokens, argument_value_tokens, .{});
        }
        ast.argument_order_tokens = function_call.argument_order_tokens;
        if (function_call.argument_order_tokens) |argument_order_tokens| {
            ast.argument_order_items = try buildTopLevelListAst(alloc, tokens, argument_order_tokens, .{ .order_modifiers = true });
        }
        ast.within_group_tokens = function_call.within_group_tokens;
        ast.within_group_order_tokens = function_call.within_group_order_tokens;
        if (function_call.within_group_order_tokens) |order_tokens| {
            ast.within_group_order_items = try buildTopLevelListAst(alloc, tokens, order_tokens, .{ .order_modifiers = true });
        }
        ast.filter_tokens = function_call.filter_tokens;
        ast.filter_predicate_tokens = function_call.filter_predicate_tokens;
        if (function_call.filter_predicate_tokens) |predicate_tokens| {
            ast.filter_expression_kind = generatedExpressionKindForRange(tokens, predicate_tokens);
            ast.filter_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, predicate_tokens);
        }
        ast.over_tokens = function_call.over_tokens;
        ast.over_name_tokens = function_call.over_name_tokens;
        ast.over_definition_tokens = function_call.over_definition_tokens;
        ast.over_partition_tokens = function_call.over_partition_tokens;
        if (function_call.over_partition_tokens) |partition_tokens| {
            ast.over_partition_items = try buildTopLevelListAst(alloc, tokens, partition_tokens, .{});
        }
        ast.over_order_tokens = function_call.over_order_tokens;
        if (function_call.over_order_tokens) |order_tokens| {
            ast.over_order_items = try buildTopLevelListAst(alloc, tokens, order_tokens, .{ .order_modifiers = true });
        }
        ast.over_frame_tokens = function_call.over_frame_tokens;
        if (function_call.over_frame_tokens) |frame_tokens| {
            if (generatedWindowFrameSemantics(tokens, frame_tokens)) |frame| {
                ast.over_frame_unit = frame.unit;
                ast.over_frame_start_bound = frame.start_bound;
                ast.over_frame_end_bound = frame.end_bound;
            }
            if (generatedWindowFrameExpressionRanges(tokens, frame_tokens)) |frame_expressions| {
                if (frame_expressions.start_expression_tokens) |expression_tokens| {
                    ast.over_frame_start_expression_tokens = expression_tokens;
                    ast.over_frame_start_expression_kind = generatedExpressionKindForRange(tokens, expression_tokens);
                    ast.over_frame_start_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, expression_tokens);
                }
                if (frame_expressions.end_expression_tokens) |expression_tokens| {
                    ast.over_frame_end_expression_tokens = expression_tokens;
                    ast.over_frame_end_expression_kind = generatedExpressionKindForRange(tokens, expression_tokens);
                    ast.over_frame_end_expression = try buildGeneratedExpressionNodeAlloc(alloc, tokens, expression_tokens);
                }
            }
        }
        return;
    }
    if (generatedArrayConstructorExpression(tokens, range)) |array_constructor| {
        ast.kind = .array_constructor;
        ast.array_tokens = array_constructor.element_tokens;
        if (array_constructor.element_tokens) |element_tokens| {
            ast.array_items = try buildTopLevelListAst(alloc, tokens, element_tokens, .{});
        }
        return;
    }
    return;
}

pub fn buildGeneratedExpressionAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) anyerror!GeneratedSqlExpressionAst {
    var ast = GeneratedSqlExpressionAst{};
    try buildGeneratedExpressionAstInPlace(alloc, tokens, range, &ast);
    return ast;
}

fn buildGeneratedExpressionNodeAlloc(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) !*GeneratedSqlExpressionAst {
    const node = try alloc.create(GeneratedSqlExpressionAst);
    errdefer alloc.destroy(node);
    node.* = .{};
    try buildGeneratedExpressionAstInPlace(alloc, tokens, range, node);
    return node;
}

fn generatedFunctionNameToken(
    tokens: []const token_mod.Token,
    name_tokens: GeneratedSqlTokenRange,
) ?token_mod.Token {
    if (name_tokens.end != name_tokens.start + 1 or name_tokens.end > tokens.len) return null;
    return tokens[name_tokens.start];
}

fn generatedAggregateFunctionKindForName(
    tokens: []const token_mod.Token,
    name_tokens: GeneratedSqlTokenRange,
) ?GeneratedSqlAggregateFunctionKind {
    const name = (generatedFunctionNameToken(tokens, name_tokens) orelse return null).text;
    if (std.ascii.eqlIgnoreCase(name, "count")) return .count;
    if (std.ascii.eqlIgnoreCase(name, "sum")) return .sum;
    if (std.ascii.eqlIgnoreCase(name, "avg")) return .avg;
    if (std.ascii.eqlIgnoreCase(name, "min")) return .min;
    if (std.ascii.eqlIgnoreCase(name, "max")) return .max;
    if (std.ascii.eqlIgnoreCase(name, "array_agg")) return .array_agg;
    if (std.ascii.eqlIgnoreCase(name, "string_agg")) return .string_agg;
    if (std.ascii.eqlIgnoreCase(name, "percentile_cont")) return .percentile_cont;
    if (std.ascii.eqlIgnoreCase(name, "percentile_disc")) return .percentile_disc;
    if (std.ascii.eqlIgnoreCase(name, "mode")) return .mode;
    if (std.ascii.eqlIgnoreCase(name, "bool_or")) return .bool_or;
    if (std.ascii.eqlIgnoreCase(name, "bool_and")) return .bool_and;
    return null;
}

fn generatedWindowFunctionKindForName(
    tokens: []const token_mod.Token,
    name_tokens: GeneratedSqlTokenRange,
) ?GeneratedSqlWindowFunctionKind {
    const name = (generatedFunctionNameToken(tokens, name_tokens) orelse return null).text;
    if (std.ascii.eqlIgnoreCase(name, "row_number")) return .row_number;
    if (std.ascii.eqlIgnoreCase(name, "rank")) return .rank;
    if (std.ascii.eqlIgnoreCase(name, "dense_rank")) return .dense_rank;
    if (std.ascii.eqlIgnoreCase(name, "percent_rank")) return .percent_rank;
    if (std.ascii.eqlIgnoreCase(name, "cume_dist")) return .cume_dist;
    if (std.ascii.eqlIgnoreCase(name, "ntile")) return .ntile;
    if (std.ascii.eqlIgnoreCase(name, "lag")) return .lag;
    if (std.ascii.eqlIgnoreCase(name, "lead")) return .lead;
    if (std.ascii.eqlIgnoreCase(name, "first_value")) return .first_value;
    if (std.ascii.eqlIgnoreCase(name, "last_value")) return .last_value;
    if (std.ascii.eqlIgnoreCase(name, "nth_value")) return .nth_value;
    if (std.ascii.eqlIgnoreCase(name, "count")) return .count;
    if (std.ascii.eqlIgnoreCase(name, "sum")) return .sum;
    if (std.ascii.eqlIgnoreCase(name, "avg")) return .avg;
    if (std.ascii.eqlIgnoreCase(name, "min")) return .min;
    if (std.ascii.eqlIgnoreCase(name, "max")) return .max;
    if (std.ascii.eqlIgnoreCase(name, "bool_or")) return .bool_or;
    if (std.ascii.eqlIgnoreCase(name, "bool_and")) return .bool_and;
    return null;
}

const GeneratedCaseBranchLists = struct {
    conditions: GeneratedSqlListAst = .{},
    results: GeneratedSqlListAst = .{},

    fn deinit(self: *GeneratedCaseBranchLists, alloc: std.mem.Allocator) void {
        self.conditions.deinit(alloc);
        self.results.deinit(alloc);
        self.* = .{};
    }
};

fn buildGeneratedExpressionListAstFromRanges(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    ranges: []const GeneratedSqlTokenRange,
) !GeneratedSqlListAst {
    var ast = GeneratedSqlListAst{};
    if (ranges.len == 0) return ast;
    errdefer ast.deinit(alloc);

    ast.count = ranges.len;
    ast.first_tokens = ranges[0];
    ast.last_tokens = ranges[ranges.len - 1];
    ast.items = try alloc.dupe(GeneratedSqlTokenRange, ranges);
    ast.identifier_name_items = try alloc.alloc(?GeneratedSqlTokenRange, ranges.len);
    for (ranges, 0..) |range, index| {
        ast.identifier_name_items[index] = generatedIdentifierNameRange(tokens, range);
    }
    ast.expression_items = try alloc.dupe(GeneratedSqlTokenRange, ranges);
    ast.expressions = try alloc.alloc(GeneratedSqlExpressionAst, ranges.len);
    @memset(ast.expressions, .{});
    for (ranges, 0..) |range, index| {
        try buildGeneratedExpressionAstInPlace(alloc, tokens, range, &ast.expressions[index]);
    }
    return ast;
}

fn buildGeneratedCaseBranchLists(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) !GeneratedCaseBranchLists {
    var condition_ranges: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    defer condition_ranges.deinit(alloc);
    var result_ranges: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    defer result_ranges.deinit(alloc);
    var lists = GeneratedCaseBranchLists{};
    errdefer lists.deinit(alloc);

    if (range.start + 5 > range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    if (!tokens[range.start].matchesKeywordTag(.case)) return error.UnsupportedSqlShape;
    if (!tokens[range.end - 1].matchesKeywordTag(.end)) return error.UnsupportedSqlShape;
    const body_end = range.end - 1;
    var cursor = range.start + 1;
    while (cursor < body_end) {
        if (tokens[cursor].matchesKeywordTag(.@"else")) break;
        if (!tokens[cursor].matchesKeywordTag(.when)) return error.UnsupportedSqlShape;
        const then_index = findTopLevelCaseKeyword(tokens, cursor + 1, body_end, .then) orelse return error.UnsupportedSqlShape;
        if (cursor + 1 >= then_index) return error.UnsupportedSqlShape;
        const next_index = findNextTopLevelCaseBoundary(tokens, then_index + 1, body_end) orelse body_end;
        if (then_index + 1 >= next_index) return error.UnsupportedSqlShape;
        try condition_ranges.append(alloc, .{ .start = cursor + 1, .end = then_index });
        try result_ranges.append(alloc, .{ .start = then_index + 1, .end = next_index });
        cursor = next_index;
    }
    if (condition_ranges.items.len == 0 or condition_ranges.items.len != result_ranges.items.len) {
        return error.UnsupportedSqlShape;
    }
    lists.conditions = try buildGeneratedExpressionListAstFromRanges(alloc, tokens, condition_ranges.items);
    lists.results = try buildGeneratedExpressionListAstFromRanges(alloc, tokens, result_ranges.items);
    return lists;
}

fn generatedExpressionKindForRange(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedSqlExpressionKind {
    if (generatedQualifiedStarExpression(tokens, range)) return .token_range;
    if (generatedSubqueryExpressionInnerRange(tokens, range) != null) return .subquery;
    if (generatedWrappedExpressionInnerRange(tokens, range) != null) return .grouped;
    if (generatedCastExpression(tokens, range) != null) return .cast;
    if (generatedCaseExpression(tokens, range) != null) return .case_expression;
    if (generatedIntervalLiteralExpression(tokens, range) != null) return .interval_literal;
    if (generatedTimestampLiteralExpression(tokens, range) != null) return .timestamp_literal;
    if (generatedCurrentTimestampExpression(tokens, range) != null) return .current_timestamp;
    if (generatedCurrentDateExpression(tokens, range)) return .current_date;
    if (generatedExtractExpression(tokens, range) != null) return .extract_expression;
    if (findTopLevelExpressionOperator(tokens, range)) |operator| return operator.kind;
    if (generatedFunctionCallExpression(tokens, range) != null) return .function_call;
    if (generatedArrayConstructorExpression(tokens, range) != null) return .array_constructor;
    if (range.start < range.end and range.end <= tokens.len) return .token_range;
    return null;
}

fn generatedQualifiedStarExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) bool {
    if (range.start >= range.end or range.end > tokens.len) return false;
    if (range.end == range.start + 2) {
        return tokens[range.start].kind == .identifier and
            tokens[range.start + 1].kind == .star;
    }
    return false;
}

const GeneratedBetweenBoundExpressionRanges = struct {
    lower_tokens: GeneratedSqlTokenRange,
    upper_tokens: GeneratedSqlTokenRange,
};

fn generatedBetweenBoundExpressionRanges(
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
) ?GeneratedBetweenBoundExpressionRanges {
    const and_index = findTopLevelBetweenBoundAnd(tokens, range) orelse return null;
    if (range.start >= and_index or and_index + 1 >= range.end) return null;
    return .{
        .lower_tokens = .{ .start = range.start, .end = and_index },
        .upper_tokens = .{ .start = and_index + 1, .end = range.end },
    };
}

fn findTopLevelBetweenBoundAnd(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?usize {
    if (range.start >= range.end or range.end > tokens.len) return null;
    var depth: usize = 0;
    var case_depth: usize = 0;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0) {
                if (tokens[index].matchesKeywordTag(.case)) {
                    case_depth += 1;
                } else if (tokens[index].matchesKeywordTag(.end)) {
                    if (case_depth == 0) return null;
                    case_depth -= 1;
                } else if (case_depth == 0 and tokens[index].matchesKeywordTag(.@"and")) {
                    return index;
                }
            },
        }
    }
    if (depth != 0 or case_depth != 0) return null;
    return null;
}

fn generatedSubqueryExpressionInnerRange(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedSqlTokenRange {
    const inner_range = generatedWrappedExpressionInnerRange(tokens, range) orelse return null;
    if (inner_range.start >= inner_range.end or inner_range.end > tokens.len) return null;
    if (tokens[inner_range.start].matchesKeywordTag(.select) or tokens[inner_range.start].matchesKeywordTag(.with)) return inner_range;
    return null;
}

fn generatedIntervalLiteralExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedSqlTokenRange {
    if (range.start >= range.end or range.end > tokens.len or range.end - range.start != 2) return null;
    if (!tokens[range.start].matchesKeywordTag(.interval)) return null;
    if (tokens[range.start + 1].kind != .string) return null;
    return .{ .start = range.start + 1, .end = range.end };
}

const GeneratedTimestampLiteralExpression = struct {
    type_tokens: GeneratedSqlTokenRange,
    value_tokens: GeneratedSqlTokenRange,
};

fn generatedTimestampLiteralExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedTimestampLiteralExpression {
    if (range.start >= range.end or range.end > tokens.len or range.end - range.start != 2) return null;
    if (!tokens[range.start].matchesKeywordTag(.timestamp) and !tokens[range.start].matchesKeywordTag(.timestamptz)) return null;
    if (tokens[range.start + 1].kind != .string) return null;
    return .{
        .type_tokens = .{ .start = range.start, .end = range.start + 1 },
        .value_tokens = .{ .start = range.start + 1, .end = range.end },
    };
}

fn generatedCurrentDateExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) bool {
    return range.start < range.end and range.end <= tokens.len and range.end - range.start == 1 and tokens[range.start].matchesKeywordTag(.current_date);
}

const GeneratedCurrentTimestampExpression = struct {
    precision_tokens: ?GeneratedSqlTokenRange = null,
};

fn generatedCurrentTimestampExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedCurrentTimestampExpression {
    if (range.start >= range.end or range.end > tokens.len) return null;
    if (!tokens[range.start].matchesKeywordTag(.current_timestamp)) return null;
    if (range.end - range.start == 1) return .{};
    if (range.end - range.start != 4) return null;
    if (tokens[range.start + 1].kind != .lparen) return null;
    if (tokens[range.start + 2].kind != .number) return null;
    if (tokens[range.start + 3].kind != .rparen) return null;
    return .{ .precision_tokens = .{ .start = range.start + 2, .end = range.start + 3 } };
}

const GeneratedExtractExpression = struct {
    field_tokens: GeneratedSqlTokenRange,
    source_tokens: GeneratedSqlTokenRange,
};

fn generatedExtractExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedExtractExpression {
    if (range.start >= range.end or range.end > tokens.len or range.end - range.start < 6) return null;
    if (!tokens[range.start].matchesKeywordTag(.extract)) return null;
    if (tokens[range.start + 1].kind != .lparen) return null;
    if (tokens[range.start + 2].kind != .identifier) return null;
    if (!tokens[range.start + 3].matchesKeywordTag(.from)) return null;
    if (tokens[range.end - 1].kind != .rparen) return null;
    const source_tokens = GeneratedSqlTokenRange{ .start = range.start + 4, .end = range.end - 1 };
    if (source_tokens.start >= source_tokens.end) return null;
    return .{
        .field_tokens = .{ .start = range.start + 2, .end = range.start + 3 },
        .source_tokens = source_tokens,
    };
}

const GeneratedFunctionCallExpression = struct {
    name_tokens: GeneratedSqlTokenRange,
    argument_tokens: ?GeneratedSqlTokenRange = null,
    argument_distinct_tokens: ?GeneratedSqlTokenRange = null,
    argument_value_tokens: ?GeneratedSqlTokenRange = null,
    argument_order_tokens: ?GeneratedSqlTokenRange = null,
    within_group_tokens: ?GeneratedSqlTokenRange = null,
    within_group_order_tokens: ?GeneratedSqlTokenRange = null,
    filter_tokens: ?GeneratedSqlTokenRange = null,
    filter_predicate_tokens: ?GeneratedSqlTokenRange = null,
    over_tokens: ?GeneratedSqlTokenRange = null,
    over_name_tokens: ?GeneratedSqlTokenRange = null,
    over_definition_tokens: ?GeneratedSqlTokenRange = null,
    over_partition_tokens: ?GeneratedSqlTokenRange = null,
    over_order_tokens: ?GeneratedSqlTokenRange = null,
    over_frame_tokens: ?GeneratedSqlTokenRange = null,
};

const GeneratedFunctionArgumentMetadata = struct {
    argument_tokens: ?GeneratedSqlTokenRange = null,
    distinct_tokens: ?GeneratedSqlTokenRange = null,
    value_tokens: ?GeneratedSqlTokenRange = null,
    order_tokens: ?GeneratedSqlTokenRange = null,
};

fn generatedFunctionCallExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedFunctionCallExpression {
    if (range.start + 2 > range.end or range.end > tokens.len) return null;

    var depth: usize = 0;
    var lparen_index: ?usize = null;
    var function_close_index: ?usize = null;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => {
                if (depth == 0 and lparen_index == null) lparen_index = index;
                depth += 1;
            },
            .rparen => {
                if (depth == 0) return null;
                depth -= 1;
                if (depth == 0 and function_close_index == null) {
                    function_close_index = index;
                    break;
                }
            },
            else => {},
        }
    }
    if (depth != 0) return null;
    const open_index = lparen_index orelse return null;
    const close_index = function_close_index orelse return null;
    if (open_index <= range.start) return null;
    if (isGeneratedFunctionCallBlockedName(tokens[open_index - 1])) return null;
    if (!isGeneratedQualifiedNameRange(tokens, .{ .start = range.start, .end = open_index })) return null;
    const argument_metadata = generatedFunctionArgumentMetadata(tokens, open_index, close_index) orelse return null;
    var cursor = close_index + 1;
    var within_group_tokens: ?GeneratedSqlTokenRange = null;
    var within_group_order_tokens: ?GeneratedSqlTokenRange = null;
    if (cursor < range.end and tokens[cursor].matchesKeywordTag(.within)) {
        if (cursor + 5 > range.end) return null;
        if (!tokens[cursor + 1].matchesKeywordTag(.group)) return null;
        if (tokens[cursor + 2].kind != .lparen) return null;
        if (!tokens[cursor + 3].matchesKeywordTag(.order)) return null;
        if (cursor + 4 >= range.end or !tokens[cursor + 4].matchesKeywordTag(.by)) return null;
        const within_close = findMatchingParen(tokens, cursor + 2, range.end) orelse return null;
        if (within_close >= range.end) return null;
        within_group_tokens = .{ .start = cursor, .end = within_close + 1 };
        within_group_order_tokens = .{ .start = cursor + 5, .end = within_close };
        if (within_group_order_tokens.?.start >= within_group_order_tokens.?.end) return null;
        cursor = within_close + 1;
    }
    var filter_tokens: ?GeneratedSqlTokenRange = null;
    var filter_predicate_tokens: ?GeneratedSqlTokenRange = null;
    if (cursor < range.end and tokens[cursor].matchesKeywordTag(.filter)) {
        if (cursor + 4 > range.end) return null;
        if (!tokens[cursor].matchesKeywordTag(.filter)) return null;
        if (tokens[cursor + 1].kind != .lparen) return null;
        if (!tokens[cursor + 2].matchesKeywordTag(.where)) return null;
        const filter_close = findMatchingParen(tokens, cursor + 1, range.end) orelse return null;
        filter_tokens = .{ .start = cursor, .end = filter_close + 1 };
        filter_predicate_tokens = .{ .start = cursor + 3, .end = filter_close };
        if (filter_predicate_tokens.?.start >= filter_predicate_tokens.?.end) return null;
        cursor = filter_close + 1;
    }
    var over_tokens: ?GeneratedSqlTokenRange = null;
    var over_name_tokens: ?GeneratedSqlTokenRange = null;
    var over_definition_tokens: ?GeneratedSqlTokenRange = null;
    var over_partition_tokens: ?GeneratedSqlTokenRange = null;
    var over_order_tokens: ?GeneratedSqlTokenRange = null;
    var over_frame_tokens: ?GeneratedSqlTokenRange = null;
    if (cursor < range.end and tokens[cursor].matchesKeywordTag(.over)) {
        if (cursor + 1 >= range.end) return null;
        if (tokens[cursor + 1].kind == .identifier) {
            if (cursor + 2 != range.end) return null;
            over_tokens = .{ .start = cursor, .end = range.end };
            over_name_tokens = .{ .start = cursor + 1, .end = range.end };
        } else if (tokens[cursor + 1].kind == .lparen) {
            const over_close = findMatchingParen(tokens, cursor + 1, range.end) orelse return null;
            over_tokens = .{ .start = cursor, .end = over_close + 1 };
            const definition = GeneratedSqlTokenRange{ .start = cursor + 2, .end = over_close };
            if (definition.start < definition.end) over_definition_tokens = definition;
            const partition_index = findTopLevelKeywordSequence(tokens, definition.start, definition.end, .partition, .by);
            const order_index = findTopLevelKeywordSequence(tokens, definition.start, definition.end, .order, .by);
            const rows_index = findTopLevelKeyword(tokens, definition.start, definition.end, .rows);
            const range_index = findTopLevelKeyword(tokens, definition.start, definition.end, .range);
            const frame_index = minOptionalIndex(rows_index, range_index);
            if (partition_index) |idx| {
                const partition_start = idx + 2;
                const partition_end = firstOptionalIndex(&[_]?usize{ order_index, frame_index }) orelse definition.end;
                if (partition_start < partition_end) over_partition_tokens = .{ .start = partition_start, .end = partition_end };
            }
            if (order_index) |idx| {
                const order_start = idx + 2;
                const order_end = frame_index orelse definition.end;
                if (order_start < order_end) over_order_tokens = .{ .start = order_start, .end = order_end };
            }
            if (frame_index) |idx| over_frame_tokens = .{ .start = idx, .end = definition.end };
        } else {
            return null;
        }
        cursor = over_tokens.?.end;
    }
    if (cursor != range.end) return null;
    return .{
        .name_tokens = .{ .start = range.start, .end = open_index },
        .argument_tokens = argument_metadata.argument_tokens,
        .argument_distinct_tokens = argument_metadata.distinct_tokens,
        .argument_value_tokens = argument_metadata.value_tokens,
        .argument_order_tokens = argument_metadata.order_tokens,
        .within_group_tokens = within_group_tokens,
        .within_group_order_tokens = within_group_order_tokens,
        .filter_tokens = filter_tokens,
        .filter_predicate_tokens = filter_predicate_tokens,
        .over_tokens = over_tokens,
        .over_name_tokens = over_name_tokens,
        .over_definition_tokens = over_definition_tokens,
        .over_partition_tokens = over_partition_tokens,
        .over_order_tokens = over_order_tokens,
        .over_frame_tokens = over_frame_tokens,
    };
}

fn generatedFunctionArgumentMetadata(tokens: []const token_mod.Token, open_index: usize, close_index: usize) ?GeneratedFunctionArgumentMetadata {
    if (open_index + 1 >= close_index) return .{};
    var metadata = GeneratedFunctionArgumentMetadata{
        .argument_tokens = .{ .start = open_index + 1, .end = close_index },
        .value_tokens = .{ .start = open_index + 1, .end = close_index },
    };
    var value_start = open_index + 1;
    if (tokens[value_start].matchesKeywordTag(.distinct)) {
        metadata.distinct_tokens = .{ .start = value_start, .end = value_start + 1 };
        value_start += 1;
        if (value_start >= close_index) return null;
    }
    const order_index = findTopLevelKeywordSequence(tokens, value_start, close_index, .order, .by);
    const value_end = order_index orelse close_index;
    if (value_start >= value_end) return null;
    metadata.value_tokens = .{ .start = value_start, .end = value_end };
    if (order_index) |idx| {
        if (idx + 2 >= close_index) return null;
        metadata.order_tokens = .{ .start = idx + 2, .end = close_index };
    }
    return metadata;
}

fn isGeneratedFunctionCallBlockedName(token: token_mod.Token) bool {
    return token.matchesKeywordTag(.in) or
        token.matchesKeywordTag(.not) or
        token.matchesKeywordTag(.any) or
        token.matchesKeywordTag(.all) or
        token.matchesKeywordTag(.some);
}

fn isGeneratedQualifiedNameRange(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) bool {
    if (range.start >= range.end or range.end > tokens.len) return false;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        if (tokens[index].kind != .identifier) return false;
    }
    return true;
}

const GeneratedArrayConstructorExpression = struct {
    element_tokens: ?GeneratedSqlTokenRange = null,
};

fn generatedArrayConstructorExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedArrayConstructorExpression {
    if (range.start + 3 > range.end or range.end > tokens.len) return null;
    if (!tokens[range.start].matchesKeywordTag(.array)) return null;
    if (tokens[range.start + 1].kind != .lbracket or tokens[range.end - 1].kind != .rbracket) return null;
    var depth: usize = 0;
    var index = range.start + 1;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lbracket, .lparen => depth += 1,
            .rbracket, .rparen => {
                if (depth == 0) return null;
                depth -= 1;
                if (depth == 0 and index + 1 != range.end) return null;
            },
            else => {},
        }
    }
    if (depth != 0) return null;
    return .{
        .element_tokens = if (range.start + 2 < range.end - 1)
            .{ .start = range.start + 2, .end = range.end - 1 }
        else
            null,
    };
}

const GeneratedCastExpression = struct {
    expression_tokens: GeneratedSqlTokenRange,
    type_tokens: GeneratedSqlTokenRange,
};

fn generatedCastExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedCastExpression {
    if (range.start >= range.end or range.end > tokens.len) return null;
    if (range.start + 6 <= range.end and tokens[range.start].matchesKeywordTag(.cast)) {
        if (tokens[range.start + 1].kind != .lparen or tokens[range.end - 1].kind != .rparen) return null;
        const inner_start = range.start + 2;
        const inner_end = range.end - 1;
        const as_index = findTopLevelKeyword(tokens, inner_start, inner_end, .as) orelse return null;
        if (inner_start >= as_index or as_index + 1 >= inner_end) return null;
        const expression_tokens = GeneratedSqlTokenRange{ .start = inner_start, .end = as_index };
        const type_tokens = GeneratedSqlTokenRange{ .start = as_index + 1, .end = inner_end };
        if (!isGeneratedTypeNameRange(tokens, type_tokens)) return null;
        return .{
            .expression_tokens = expression_tokens,
            .type_tokens = type_tokens,
        };
    }
    return null;
}

fn isGeneratedTypeNameRange(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) bool {
    if (range.start >= range.end or range.end > tokens.len) return false;
    var name_end = range.end;
    if (range.end >= range.start + 2 and tokens[range.end - 2].kind == .lbracket and tokens[range.end - 1].kind == .rbracket) {
        name_end = range.end - 2;
    }
    return isGeneratedQualifiedNameRange(tokens, .{ .start = range.start, .end = name_end });
}

const GeneratedCaseExpression = struct {
    branch_count: usize,
    first_when_tokens: GeneratedSqlTokenRange,
    last_when_tokens: GeneratedSqlTokenRange,
    first_condition_tokens: GeneratedSqlTokenRange,
    first_result_tokens: GeneratedSqlTokenRange,
    else_tokens: ?GeneratedSqlTokenRange = null,
    else_expression_tokens: ?GeneratedSqlTokenRange = null,
};

fn generatedCaseExpression(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedCaseExpression {
    if (range.start + 5 > range.end or range.end > tokens.len) return null;
    if (!tokens[range.start].matchesKeywordTag(.case)) return null;
    if (!tokens[range.end - 1].matchesKeywordTag(.end)) return null;
    var cursor = range.start + 1;
    var branch_count: usize = 0;
    var first_when_tokens: ?GeneratedSqlTokenRange = null;
    var last_when_tokens: ?GeneratedSqlTokenRange = null;
    var first_condition_tokens: ?GeneratedSqlTokenRange = null;
    var first_result_tokens: ?GeneratedSqlTokenRange = null;
    var else_tokens: ?GeneratedSqlTokenRange = null;
    var else_expression_tokens: ?GeneratedSqlTokenRange = null;
    const body_end = range.end - 1;
    while (cursor < body_end) {
        if (tokens[cursor].matchesKeywordTag(.@"else")) {
            const expression_tokens = GeneratedSqlTokenRange{ .start = cursor + 1, .end = body_end };
            if (expression_tokens.start >= expression_tokens.end) return null;
            else_tokens = .{ .start = cursor, .end = body_end };
            else_expression_tokens = expression_tokens;
            cursor = body_end;
            break;
        }
        if (!tokens[cursor].matchesKeywordTag(.when)) return null;
        const then_index = findTopLevelCaseKeyword(tokens, cursor + 1, body_end, .then) orelse return null;
        if (cursor + 1 >= then_index) return null;
        const next_index = findNextTopLevelCaseBoundary(tokens, then_index + 1, body_end) orelse body_end;
        if (then_index + 1 >= next_index) return null;
        const when_tokens = GeneratedSqlTokenRange{ .start = cursor, .end = next_index };
        if (branch_count == 0) {
            first_when_tokens = when_tokens;
            first_condition_tokens = .{ .start = cursor + 1, .end = then_index };
            first_result_tokens = .{ .start = then_index + 1, .end = next_index };
        }
        last_when_tokens = when_tokens;
        branch_count += 1;
        cursor = next_index;
    }
    if (branch_count == 0 or cursor != body_end) return null;
    return .{
        .branch_count = branch_count,
        .first_when_tokens = first_when_tokens.?,
        .last_when_tokens = last_when_tokens.?,
        .first_condition_tokens = first_condition_tokens.?,
        .first_result_tokens = first_result_tokens.?,
        .else_tokens = else_tokens,
        .else_expression_tokens = else_expression_tokens,
    };
}

fn findNextTopLevelCaseBoundary(tokens: []const token_mod.Token, start: usize, end: usize) ?usize {
    var depth: usize = 0;
    var case_depth: usize = 0;
    var index = start;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0) {
                if (tokens[index].matchesKeywordTag(.case)) {
                    case_depth += 1;
                } else if (tokens[index].matchesKeywordTag(.end)) {
                    if (case_depth == 0) return null;
                    case_depth -= 1;
                } else if (case_depth == 0 and (tokens[index].matchesKeywordTag(.when) or tokens[index].matchesKeywordTag(.@"else"))) {
                    return index;
                }
            },
        }
    }
    return null;
}

fn findTopLevelCaseKeyword(tokens: []const token_mod.Token, start: usize, end: usize, keyword: token_mod.TokenKeyword) ?usize {
    var depth: usize = 0;
    var case_depth: usize = 0;
    var index = start;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0) {
                if (tokens[index].matchesKeywordTag(.case)) {
                    case_depth += 1;
                } else if (tokens[index].matchesKeywordTag(.end)) {
                    if (case_depth == 0) return null;
                    case_depth -= 1;
                } else if (case_depth == 0 and tokens[index].matchesKeywordTag(keyword)) {
                    return index;
                }
            },
        }
    }
    return null;
}

fn generatedWrappedExpressionInnerRange(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedSqlTokenRange {
    if (range.start >= range.end or range.end > tokens.len or range.end - range.start < 2) return null;
    if (tokens[range.start].kind != .lparen or tokens[range.end - 1].kind != .rparen) return null;
    var depth: usize = 0;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return null;
                depth -= 1;
                if (depth == 0 and index + 1 != range.end) return null;
            },
            else => {},
        }
    }
    if (depth != 0) return null;
    return .{ .start = range.start + 1, .end = range.end - 1 };
}

const GeneratedSqlExpressionOperator = struct {
    kind: GeneratedSqlExpressionKind,
    index: usize,
    operator_end_index: ?usize = null,
    negation_index: ?usize = null,
    quantifier_index: ?usize = null,
    prefix: bool = false,
    postfix: bool = false,
};

const GeneratedSqlBooleanChainMetadata = struct {
    condition_count: usize,
    first_condition_tokens: GeneratedSqlTokenRange,
    first_condition_kind: ?GeneratedSqlExpressionKind,
    first_condition: *GeneratedSqlExpressionAst,
    last_condition_tokens: GeneratedSqlTokenRange,
    last_condition_kind: ?GeneratedSqlExpressionKind,
    last_condition: *GeneratedSqlExpressionAst,
    condition_items: GeneratedSqlListAst,
};

fn generatedBooleanChainMetadata(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
    kind: GeneratedSqlExpressionKind,
) !?GeneratedSqlBooleanChainMetadata {
    if (range.start >= range.end or range.end > tokens.len) return null;

    var condition_items = try buildGeneratedBooleanConditionListAst(alloc, tokens, range, kind);
    errdefer condition_items.deinit(alloc);
    if (condition_items.count < 2) return null;

    const first_tokens = condition_items.first_tokens orelse return null;
    const last_tokens = condition_items.last_tokens orelse return null;
    const first_condition = try buildGeneratedExpressionNodeAlloc(alloc, tokens, first_tokens);
    errdefer {
        first_condition.deinit(alloc);
        alloc.destroy(first_condition);
    }
    const last_condition = try buildGeneratedExpressionNodeAlloc(alloc, tokens, last_tokens);
    return .{
        .condition_count = condition_items.count,
        .first_condition_tokens = first_tokens,
        .first_condition_kind = generatedExpressionKindForRange(tokens, first_tokens),
        .first_condition = first_condition,
        .last_condition_tokens = last_tokens,
        .last_condition_kind = generatedExpressionKindForRange(tokens, last_tokens),
        .last_condition = last_condition,
        .condition_items = condition_items,
    };
}

fn buildGeneratedBooleanConditionListAst(
    alloc: std.mem.Allocator,
    tokens: []const token_mod.Token,
    range: GeneratedSqlTokenRange,
    kind: GeneratedSqlExpressionKind,
) !GeneratedSqlListAst {
    const keyword: token_mod.TokenKeyword = switch (kind) {
        .logical_or => .@"or",
        .logical_and => .@"and",
        else => return .{},
    };
    var ast = GeneratedSqlListAst{};
    if (range.start >= range.end or range.end > tokens.len) return ast;

    var items: std.ArrayListUnmanaged(GeneratedSqlTokenRange) = .empty;
    errdefer items.deinit(alloc);
    var depth: usize = 0;
    var case_depth: usize = 0;
    var item_start = range.start;
    var skip_next_between_and = false;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) {
                    items.deinit(alloc);
                    return .{};
                }
                depth -= 1;
            },
            else => if (depth == 0) {
                if (tokens[index].matchesKeywordTag(.case)) {
                    case_depth += 1;
                } else if (tokens[index].matchesKeywordTag(.end)) {
                    if (case_depth == 0) {
                        items.deinit(alloc);
                        return .{};
                    }
                    case_depth -= 1;
                } else if (case_depth == 0) {
                    if (tokens[index].matchesKeywordTag(.between) and kind == .logical_and) {
                        skip_next_between_and = true;
                    } else if (tokens[index].matchesKeywordTag(keyword)) {
                        if (kind == .logical_and and skip_next_between_and) {
                            skip_next_between_and = false;
                        } else {
                            if (item_start >= index) {
                                items.deinit(alloc);
                                return .{};
                            }
                            try recordGeneratedListItem(alloc, &items, &ast, .{ .start = item_start, .end = index });
                            item_start = index + 1;
                        }
                    }
                }
            },
        }
    }
    if (depth != 0 or case_depth != 0 or item_start >= range.end or ast.count == 0) {
        items.deinit(alloc);
        return .{};
    }

    try recordGeneratedListItem(alloc, &items, &ast, .{ .start = item_start, .end = range.end });
    ast.items = try items.toOwnedSlice(alloc);
    errdefer {
        alloc.free(ast.items);
        ast.items = &.{};
    }
    ast.expression_items = try alloc.alloc(GeneratedSqlTokenRange, ast.items.len);
    errdefer {
        alloc.free(ast.expression_items);
        ast.expression_items = &.{};
    }
    for (ast.items, 0..) |item, item_index| {
        ast.expression_items[item_index] = item;
    }
    ast.expressions = try alloc.alloc(GeneratedSqlExpressionAst, ast.items.len);
    var expression_count: usize = 0;
    errdefer {
        for (ast.expressions[0..expression_count]) |*expression| expression.deinit(alloc);
        alloc.free(ast.expressions);
        ast.expressions = &.{};
    }
    for (ast.expression_items) |item| {
        try buildGeneratedExpressionAstInPlace(alloc, tokens, item, &ast.expressions[expression_count]);
        expression_count += 1;
    }
    return ast;
}

fn findTopLevelExpressionOperator(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?GeneratedSqlExpressionOperator {
    if (range.start >= range.end or range.end > tokens.len) return null;
    var depth: usize = 0;
    var index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0 and tokens[index].matchesKeywordTag(.@"or")) return .{ .kind = .logical_or, .index = index },
        }
    }
    depth = 0;
    index = range.start;
    var skip_next_between_and = false;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0) {
                if (tokens[index].matchesKeywordTag(.between)) {
                    skip_next_between_and = true;
                } else if (tokens[index].matchesKeywordTag(.@"and")) {
                    if (skip_next_between_and) {
                        skip_next_between_and = false;
                    } else {
                        return .{ .kind = .logical_and, .index = index };
                    }
                }
            },
        }
    }
    depth = 0;
    index = range.start;
    if (tokens[index].matchesKeywordTag(.not)) {
        if (index + 1 < range.end and tokens[index + 1].matchesKeywordTag(.exists)) {
            return .{ .kind = .not_exists_subquery, .index = index + 1, .negation_index = index, .prefix = true };
        }
        return .{ .kind = .logical_not, .index = index, .prefix = true };
    }
    if (tokens[index].matchesKeywordTag(.exists)) return .{ .kind = .exists_subquery, .index = index, .prefix = true };
    if (tokens[index].kind == .plus and index + 1 < range.end) return .{ .kind = .unary_positive, .index = index, .prefix = true };
    if (tokens[index].kind == .minus and index + 1 < range.end) return .{ .kind = .unary_negative, .index = index, .prefix = true };
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .eq, .neq, .lt, .lte, .gt, .gte => if (depth == 0 and index > range.start and index + 1 < range.end) {
                if (tokens[index].kind == .eq and tokens[index + 1].kind == .gt) continue;
                if (tokens[index].kind == .gt and tokens[index - 1].kind == .eq) continue;
                if (index + 1 < range.end and isGeneratedQuantifiedOperator(tokens[index + 1])) {
                    return .{ .kind = .quantified_comparison, .index = index, .quantifier_index = index + 1 };
                }
                return .{ .kind = .comparison, .index = index };
            },
            .at_contains => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .contains, .index = index },
            .range_overlap => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .overlaps, .index = index },
            .question => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .json_key_exists, .index = index },
            .question_any => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .json_key_any, .index = index },
            .question_all => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .json_key_all, .index = index },
            .regex_match => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .regex_match, .index = index },
            .regex_imatch => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .regex_imatch, .index = index },
            .regex_not_match => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .regex_not_match, .index = index },
            .regex_not_imatch => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .regex_not_imatch, .index = index },
            else => if (depth == 0) {
                if (tokens[index].matchesKeywordTag(.not) and index + 1 < range.end) {
                    if (tokens[index + 1].matchesKeywordTag(.like)) {
                        if (index + 2 < range.end and isGeneratedQuantifiedOperator(tokens[index + 2])) {
                            return .{ .kind = .not_like, .index = index + 1, .negation_index = index, .quantifier_index = index + 2 };
                        }
                        return .{ .kind = .not_like, .index = index + 1, .negation_index = index };
                    }
                    if (tokens[index + 1].matchesKeywordTag(.ilike)) {
                        if (index + 2 < range.end and isGeneratedQuantifiedOperator(tokens[index + 2])) {
                            return .{ .kind = .not_ilike, .index = index + 1, .negation_index = index, .quantifier_index = index + 2 };
                        }
                        return .{ .kind = .not_ilike, .index = index + 1, .negation_index = index };
                    }
                    if (tokens[index + 1].matchesKeywordTag(.in)) return .{ .kind = .not_in_list, .index = index + 1, .negation_index = index };
                    if (tokens[index + 1].matchesKeywordTag(.between)) return .{ .kind = .not_between, .index = index + 1, .negation_index = index };
                }
                if (tokens[index].matchesKeywordTag(.like)) {
                    if (index + 1 < range.end and isGeneratedQuantifiedOperator(tokens[index + 1])) {
                        return .{ .kind = .like, .index = index, .quantifier_index = index + 1 };
                    }
                    return .{ .kind = .like, .index = index };
                }
                if (tokens[index].matchesKeywordTag(.ilike)) {
                    if (index + 1 < range.end and isGeneratedQuantifiedOperator(tokens[index + 1])) {
                        return .{ .kind = .ilike, .index = index, .quantifier_index = index + 1 };
                    }
                    return .{ .kind = .ilike, .index = index };
                }
                if (tokens[index].matchesKeywordTag(.in)) return .{ .kind = .in_list, .index = index };
                if (tokens[index].matchesKeywordTag(.between)) return .{ .kind = .between, .index = index };
                if (tokens[index].matchesKeywordTag(.isnull)) return .{ .kind = .is_null, .index = index, .postfix = true };
                if (tokens[index].matchesKeywordTag(.notnull)) return .{ .kind = .is_not_null, .index = index, .postfix = true };
                if (tokens[index].matchesKeywordTag(.is) and index + 1 < range.end) {
                    if (tokens[index + 1].matchesKeywordTag(.null)) return .{ .kind = .is_null, .index = index };
                    if (tokens[index + 1].matchesKeywordTag(.true)) return .{ .kind = .is_true, .index = index };
                    if (tokens[index + 1].matchesKeywordTag(.false)) return .{ .kind = .is_false, .index = index };
                    if (tokens[index + 1].matchesKeywordTag(.unknown)) return .{ .kind = .is_unknown, .index = index };
                    if (index + 3 < range.end and tokens[index + 1].matchesKeywordTag(.distinct) and tokens[index + 2].matchesKeywordTag(.from)) {
                        return .{ .kind = .is_distinct_from, .index = index, .operator_end_index = index + 3 };
                    }
                    if (index + 2 < range.end and tokens[index + 1].matchesKeywordTag(.not) and tokens[index + 2].matchesKeywordTag(.null)) {
                        return .{ .kind = .is_not_null, .index = index };
                    }
                    if (index + 2 < range.end and tokens[index + 1].matchesKeywordTag(.not) and tokens[index + 2].matchesKeywordTag(.true)) {
                        return .{ .kind = .is_not_true, .index = index };
                    }
                    if (index + 2 < range.end and tokens[index + 1].matchesKeywordTag(.not) and tokens[index + 2].matchesKeywordTag(.false)) {
                        return .{ .kind = .is_not_false, .index = index };
                    }
                    if (index + 2 < range.end and tokens[index + 1].matchesKeywordTag(.not) and tokens[index + 2].matchesKeywordTag(.unknown)) {
                        return .{ .kind = .is_not_unknown, .index = index };
                    }
                    if (index + 4 < range.end and tokens[index + 1].matchesKeywordTag(.not) and tokens[index + 2].matchesKeywordTag(.distinct) and tokens[index + 3].matchesKeywordTag(.from)) {
                        return .{ .kind = .is_not_distinct_from, .index = index, .operator_end_index = index + 4, .negation_index = index + 1 };
                    }
                }
            },
        }
    }
    depth = 0;
    index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .pipe_concat => if (depth == 0 and index > range.start and index + 1 < range.end) return .{ .kind = .string_concat, .index = index },
            else => {},
        }
    }
    depth = 0;
    index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .plus => if (depth == 0 and index > range.start) return .{ .kind = .additive, .index = index },
            .minus => if (depth == 0 and index > range.start) return .{ .kind = .subtractive, .index = index },
            else => {},
        }
    }
    depth = 0;
    index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .star => if (depth == 0 and index > range.start) return .{ .kind = .multiplicative, .index = index },
            .slash => if (depth == 0 and index > range.start) return .{ .kind = .divisive, .index = index },
            .percent => if (depth == 0 and index > range.start) return .{ .kind = .modulo, .index = index },
            else => {},
        }
    }
    depth = 0;
    index = range.start;
    while (index < range.end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            .arrow_json => if (depth == 0 and index > range.start) return .{ .kind = .json_access, .index = index },
            .arrow_text => if (depth == 0 and index > range.start) return .{ .kind = .json_text_access, .index = index },
            .path_arrow_json => if (depth == 0 and index > range.start) return .{ .kind = .json_path_access, .index = index },
            .path_arrow_text => if (depth == 0 and index > range.start) return .{ .kind = .json_path_text_access, .index = index },
            else => {},
        }
    }
    return null;
}

fn isGeneratedQuantifiedOperator(token: token_mod.Token) bool {
    return token.matchesKeywordTag(.any) or token.matchesKeywordTag(.all) or token.matchesKeywordTag(.some);
}

fn isGeneratedLikeExpressionKind(kind: GeneratedSqlExpressionKind) bool {
    return kind == .like or kind == .ilike or kind == .not_like or kind == .not_ilike;
}

fn isGeneratedBetweenExpressionKind(kind: GeneratedSqlExpressionKind) bool {
    return kind == .between or kind == .not_between;
}

fn generatedBetweenModifier(token: token_mod.Token) ?GeneratedSqlBetweenModifier {
    if (token.matchesKeywordTag(.asymmetric)) return .asymmetric;
    if (token.matchesKeywordTag(.symmetric)) return .symmetric;
    return null;
}

fn findKeyword(tokens: []const token_mod.Token, start: usize, end: usize, keyword: token_mod.TokenKeyword) ?usize {
    var index = start;
    while (index < end) : (index += 1) {
        if (tokens[index].matchesKeywordTag(keyword)) return index;
    }
    return null;
}

fn findTopLevelKeyword(tokens: []const token_mod.Token, start: usize, end: usize, keyword: token_mod.TokenKeyword) ?usize {
    var depth: usize = 0;
    var index = start;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0 and tokens[index].matchesKeywordTag(keyword)) return index,
        }
    }
    return null;
}

fn findTopLevelKeywordText(tokens: []const token_mod.Token, start: usize, end: usize, keyword: []const u8) ?usize {
    var depth: usize = 0;
    var index = start;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0 and tokens[index].matchesKeyword(keyword)) return index,
        }
    }
    return null;
}

fn findTopLevelKeywordSequence(tokens: []const token_mod.Token, start: usize, end: usize, first: token_mod.TokenKeyword, second: token_mod.TokenKeyword) ?usize {
    var depth: usize = 0;
    var index = start;
    while (index + 1 < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => if (depth == 0 and tokens[index].matchesKeywordTag(first) and tokens[index + 1].matchesKeywordTag(second)) return index,
        }
    }
    return null;
}

fn findTopLevelInsertConflictKeyword(tokens: []const token_mod.Token, start: usize, end: usize) ?usize {
    var depth: usize = 0;
    var index = start;
    while (index + 2 < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen, .lbracket => depth += 1,
            .rparen, .rbracket => {
                if (depth == 0) return null;
                depth -= 1;
            },
            else => {},
        }
        if (depth != 0 or !tokens[index].matchesKeywordTag(.on) or !tokens[index + 1].matchesKeywordTag(.conflict)) continue;
        if (tokens[index + 2].kind == .lparen or tokens[index + 2].matchesKeywordTag(.on) or tokens[index + 2].matchesKeywordTag(.do)) return index;
    }
    return null;
}

fn findKeywordText(tokens: []const token_mod.Token, start: usize, end: usize, keyword: []const u8) ?usize {
    var index = start;
    while (index < end) : (index += 1) {
        if (tokens[index].matchesKeyword(keyword)) return index;
    }
    return null;
}

fn findMatchingParen(tokens: []const token_mod.Token, open_index: usize, end: usize) ?usize {
    if (open_index >= end or tokens[open_index].kind != .lparen) return null;
    var depth: usize = 1;
    var index = open_index + 1;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lparen => depth += 1,
            .rparen => {
                depth -= 1;
                if (depth == 0) return index;
            },
            else => {},
        }
    }
    return null;
}

fn findMatchingBracket(tokens: []const token_mod.Token, open_index: usize, end: usize) ?usize {
    if (open_index >= end or tokens[open_index].kind != .lbracket) return null;
    var depth: usize = 1;
    var index = open_index + 1;
    while (index < end) : (index += 1) {
        switch (tokens[index].kind) {
            .lbracket => depth += 1,
            .rbracket => {
                depth -= 1;
                if (depth == 0) return index;
            },
            else => {},
        }
    }
    return null;
}

fn minOptionalIndex(a: ?usize, b: ?usize) ?usize {
    if (a == null) return b;
    if (b == null) return a;
    return @min(a.?, b.?);
}

fn firstOptionalIndex(indices: []const ?usize) ?usize {
    var best: ?usize = null;
    for (indices) |index| {
        if (index) |idx| {
            if (best == null or idx < best.?) best = idx;
        }
    }
    return best;
}

fn statementTokenEnd(tokens: []const token_mod.Token) usize {
    var end = tokens.len;
    while (end > 0 and tokens[end - 1].kind == .semicolon) end -= 1;
    return end;
}

fn sourceSpanForTokenRange(tokens: []const token_mod.Token, range: GeneratedSqlTokenRange) ?token_mod.SourceSpan {
    if (range.start >= range.end or range.end > tokens.len) return null;
    return .{
        .start = tokens[range.start].source_start,
        .end = tokens[range.end - 1].source_end,
    };
}

test "generated SQL parser accepts session and control statements" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    for (first_family_corpus) |case| {
        const result = try parseSqlAlloc(alloc, case.sql);
        try std.testing.expectEqual(case.kind, result.kind);
    }
}

test "generated SQL parser facade classifies gated corpus" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    const corpus = first_family_corpus ++ simple_ddl_corpus ++ simple_dml_corpus ++ simple_read_corpus ++ antfly_extension_read_corpus ++ simple_graph_corpus ++ unsupported_corpus;
    for (corpus) |case| {
        const generated_result = parseSqlAlloc(alloc, case.sql) catch |err| {
            std.debug.print("generated parser rejected corpus SQL: {s}\n", .{case.sql});
            return err;
        };
        if (case.kind != generated_result.kind) {
            std.debug.print("generated parser classified corpus SQL unexpectedly: {s}\n", .{case.sql});
        }
        try std.testing.expectEqual(case.kind, generated_result.kind);
    }
}

